-- Charles — the whole database, in one script.
-- Generated by scripts/build-setup-sql.mjs on 2026-10-30 from the files in db/, in order.
-- Paste into Supabase → SQL Editor → New query → Run. Safe to run more than once.
-- Before running: Database → Extensions → enable "vector" (pgvector). Everything else is here.
-- Afterwards: run the checks in docs/SUPABASE-SETUP.md.


-- ============================================================================
-- 0000_base_tables.sql
-- ============================================================================

/*
# Charles — the seven base tables

Apply in Supabase → SQL Editor → New query → paste → Run. Run FIRST, before
0001. Safe to run more than once.

1. What this does, in plain terms
Charlie's first project had these seven tables made by hand before any script
existed, so 0001 onward only ALTER them. A fresh project has none of them.
This file creates them with the columns the original schema had
(docs/ARCHITECTURE.md Part 3); every later column is added by the file that
introduced it, with IF NOT EXISTS, so the order below is the only order.

2. The vector extension
Supabase → Database → Extensions → enable "vector" first, or this file's
CREATE EXTENSION does it where the role is allowed to. The embedding columns
are empty until the second-pass search is populated; nothing reads them
until then.

3. Security
Row-level security is switched on and locked down by 0001, straight after.
*/

CREATE EXTENSION IF NOT EXISTS vector;

-- One row per household (one WhatsApp number). Named businesses because
-- Charles is built from Charlie; see db/0033.
CREATE TABLE IF NOT EXISTS public.businesses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  wa_id text UNIQUE NOT NULL,
  country text NOT NULL DEFAULT 'ZA',
  stage text NOT NULL DEFAULT 'diag',
  identity jsonb,
  context jsonb,
  customer jsonb,
  angle jsonb,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- The Money Map: eight areas, red/amber/green, one note each.
CREATE TABLE IF NOT EXISTS public.business_map (
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  domain text NOT NULL,
  status text NOT NULL,
  note text,
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (business_id, domain)
);

CREATE TABLE IF NOT EXISTS public.plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  goal text,
  headline text,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.plan_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id uuid REFERENCES public.plans(id) ON DELETE CASCADE,
  workstream_title text,
  step_order int,
  title text,
  push text,
  artifact text,
  tool_id text,
  status text DEFAULT 'open',
  done_when text
);

CREATE TABLE IF NOT EXISTS public.decisions (
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  what text,
  source text,
  created_at timestamptz DEFAULT now()
);

-- The library: researched once, read on every answer.
CREATE TABLE IF NOT EXISTS public.knowledge_entries (
  id text PRIMARY KEY,
  country text NOT NULL,
  domain text,
  stages text[],
  keywords text[],
  title text,
  owner_summary text,
  applies_when text,
  not_when text,
  steps text[],
  cost text,
  stakes text,
  verified_on date,
  embedding vector(1536),
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.tools (
  id text PRIMARY KEY,
  country text NOT NULL,
  domain text,
  stages text[],
  keywords text[],
  name text,
  fits text,
  not_when text,
  why text,
  cost text,
  url text,
  setup text,
  walkthrough text[],
  verified_on date,
  embedding vector(1536),
  created_at timestamptz DEFAULT now()
);


-- ============================================================================
-- 0001_rls_lockdown.sql
-- ============================================================================

/*
# Charlie — RLS lockdown (the security fix)

Apply in Supabase → SQL Editor → New query → paste → Run.
Safe to run more than once.

1. What this does, in plain terms
- Your two research tables (knowledge_entries, tools) become readable by
  everyone but writable by nobody except your backend. They are reference
  data, like a public library.
- Your five owner-data tables (businesses, business_map, plans, plan_steps,
  decisions) become completely locked. Nobody can read or write them with
  the public key. Only the backend (service role) can touch them.

2. Why
Right now anyone holding the project's public key can read AND overwrite
every business's data. This change seals that.
*/

-- Reference tables: public to read, locked to write
ALTER TABLE public.knowledge_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tools ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "public_read_knowledge_entries" ON public.knowledge_entries;
CREATE POLICY "public_read_knowledge_entries"
  ON public.knowledge_entries FOR SELECT
  TO anon, authenticated
  USING (true);

DROP POLICY IF EXISTS "public_read_tools" ON public.tools;
CREATE POLICY "public_read_tools"
  ON public.tools FOR SELECT
  TO anon, authenticated
  USING (true);

-- Owner-data tables: fully locked. No policies = no access for public keys.
ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.business_map ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.plan_steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.decisions ENABLE ROW LEVEL SECURITY;


-- ============================================================================
-- 0002_model_config.sql
-- ============================================================================

/*
# Charlie — model_config table (never hardcode a model name)

Apply in Supabase → SQL Editor → New query → paste → Run.
Run AFTER 0001. Safe to run more than once.

1. What this does, in plain terms
Creates one small table that says which AI model does which job in Charlie.
The backend reads this table at runtime. All calls go through OpenRouter —
you pick and change models on your OpenRouter dashboard, then update one
row here, no code change, no redeploy.

2. Jobs and their starting models (all via OpenRouter)
The `model` column holds OpenRouter model slugs (vendor/name format). The
examples below are starting points — replace them with the models you have
actually chosen on your OpenRouter dashboard. `OPENROUTER_API_KEY` is the only
credential needed; OpenRouter routes to whichever provider serves the model,
which is the point of going through it.

3. Security
RLS enabled, no policies: nobody with a public key can read or write it.
Only the backend (service role) uses this table.

4. Changing a model later
Update the row here (SQL Editor) — done. The webhook reads this table on
every call, so the change is live immediately.
*/

CREATE TABLE IF NOT EXISTS public.model_config (
  role text PRIMARY KEY,              -- router | wa_reply | help | voice | plan_builder
  provider text NOT NULL,             -- openrouter
  model text NOT NULL,                -- OpenRouter model slug, e.g. "groq/llama-3.1-8b-instant"
  params jsonb DEFAULT '{}'::jsonb,   -- extra settings (max_tokens, temperature)
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.model_config ENABLE ROW LEVEL SECURITY;

-- TODO(founder): replace each slug below with one you have actually chosen on
-- your OpenRouter dashboard. db/0005 corrects the `voice` row, whose seeded
-- slug was not a real OpenRouter model.
INSERT INTO public.model_config (role, provider, model, params) VALUES
  ('router',      'openrouter', 'groq/llama-3.1-8b-instant',  '{"max_tokens": 300}'),
  ('wa_reply',    'openrouter', 'groq/llama-3.3-70b-versatile','{"max_tokens": 900}'),
  ('help',        'openrouter', 'groq/llama-3.3-70b-versatile','{"max_tokens": 700}'),
  ('voice',       'openrouter', 'groq/whisper-large-v3',     '{}'),
  ('plan_builder','openrouter', 'anthropic/claude-sonnet-4.5','{"max_tokens": 2200}')
ON CONFLICT (role) DO NOTHING;


-- ============================================================================
-- 0003_conversation_state.sql
-- ============================================================================

/*
# Charlie — conversation state (apply AFTER 0001 and 0002)

Apply in Supabase → SQL Editor → New query → paste → Run.
Safe to run more than once.

1. What this does, in plain terms
Adds what the WhatsApp backend needs to remember where each owner is:
- answers: the diagnostic answers the owner has given so far
- diag_step: which diagnostic question they're on (0 = just started)
- messages: a log of every message in and out, so the backend and the
  owner's own AI share one memory

2. Security
The messages table is locked the same way as the other owner-data tables:
RLS enabled with no policies, so only the backend (service role) can touch it.
Existing data is not changed or removed.
*/

ALTER TABLE public.businesses
  ADD COLUMN IF NOT EXISTS answers jsonb DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS diag_step int DEFAULT 0;

CREATE TABLE IF NOT EXISTS public.messages (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  direction text NOT NULL,             -- 'in' | 'out'
  text text,
  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS messages_business_idx ON public.messages (business_id, id);

ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;


-- ============================================================================
-- 0004_plan_flow_state.sql
-- ============================================================================

/*
# Charlie — plan-building flow state (apply AFTER 0001, 0002, 0003)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run
more than once.

1. What this does, in plain terms
The diagnostic used to end with just "Got it". This adds the columns the
rest of the flow needs to run end to end: confirming what the business
actually is, choosing who to aim at, choosing the angle, and the context
+ map the plan gets built from. Also widens `plans` / `plan_steps` (created
before Claude Code touched this project) with the columns the new plan
builder writes.

2. Security
Same as the rest of `businesses`, `plans` and `plan_steps`: RLS already
enabled with no public policies, so only the backend (service role) can
read or write these columns.
*/

-- `stage` already means the conversation-flow stage (diag, diag_done, ...) in
-- the existing schema — `biz_stage` is the separate business-lifecycle stage
-- (idea | start | run | grow) the plan builder needs, kept in its own column
-- rather than overloading `stage` with two different meanings.
ALTER TABLE public.businesses
  ADD COLUMN IF NOT EXISTS biz_stage text,
  ADD COLUMN IF NOT EXISTS identity jsonb,
  ADD COLUMN IF NOT EXISTS signals jsonb,
  ADD COLUMN IF NOT EXISTS objective_read text,
  ADD COLUMN IF NOT EXISTS pending_customer_options jsonb,
  ADD COLUMN IF NOT EXISTS customer jsonb,
  ADD COLUMN IF NOT EXISTS pending_angle_options jsonb,
  ADD COLUMN IF NOT EXISTS angle jsonb,
  ADD COLUMN IF NOT EXISTS alternatives jsonb,
  ADD COLUMN IF NOT EXISTS context jsonb,
  ADD COLUMN IF NOT EXISTS map jsonb,
  ADD COLUMN IF NOT EXISTS current_plan_id uuid;

ALTER TABLE public.plans
  ADD COLUMN IF NOT EXISTS headline text;

ALTER TABLE public.plan_steps
  ADD COLUMN IF NOT EXISTS domain text,
  ADD COLUMN IF NOT EXISTS why_for_you text,
  ADD COLUMN IF NOT EXISTS artifact text,
  ADD COLUMN IF NOT EXISTS done_when text;


-- ============================================================================
-- 0005_platform.sql
-- ============================================================================

/*
# Charlie — the platform tables (apply AFTER 0001–0004)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this does, in plain terms
Everything the webhook needed but did not have:
- jobs          — a work queue. WhatsApp gets its "received" in under a second;
                  the slow work (models, PDFs) happens after, in a worker.
- wa_inbound    — every WhatsApp message id we have already handled, so Meta's
                  automatic retries can never build a second plan.
- safety_events — every guardrail check that ran, and whether it actually ran.
                  A guardrail that is quietly switched off is now impossible to
                  miss: it writes an 'unavailable' row.
- retrieval_gaps— questions the keyword search could not match. This is the
                  evidence that decides whether semantic search is ever worth
                  turning on.
- commitments / outcomes — what the owner said they would do, and what happened.
- nudges / wa_templates  — the follow-up messages and their approved templates.
- connector_tokens       — lets the owner's own AI (Claude, ChatGPT) read their
                  business, one revocable token each.
- plan_access_codes / plan_sessions — logging in to see the plan on the website,
                  using the owner's WhatsApp number as the identity.
- proposed_changes       — when the owner's AI suggests changing a critical fact,
                  it never silently edits the plan; it waits for a yes on WhatsApp.

2. Security
Every table here is owner data: RLS enabled, no policies, so only the backend
(service role) can read or write. Same lockdown as 0001.
*/

-- ── The work queue ───────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.jobs (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  kind text NOT NULL,                              -- inbound | nudge | freshness
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  wa_id text,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'queued',           -- queued | running | done | failed | dead
  attempts int NOT NULL DEFAULT 0,
  max_attempts int NOT NULL DEFAULT 3,
  run_after timestamptz NOT NULL DEFAULT now(),
  locked_at timestamptz,
  locked_by text,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS jobs_claim_idx ON public.jobs (status, run_after, id);
CREATE INDEX IF NOT EXISTS jobs_business_idx ON public.jobs (business_id, created_at DESC);

/*
Claiming a job has to be atomic: two worker instances can wake at the same
moment and must never get the same row. FOR UPDATE SKIP LOCKED is the standard
Postgres answer — the second worker skips the locked row instead of blocking on
it. The CTE form is used rather than a scalar subquery so the row the lock was
taken on is provably the row that gets updated.

A 'running' job whose lock is older than 5 minutes is treated as abandoned —
the function crashed, or the platform killed it at its timeout — and becomes
claimable again. Five minutes is chosen to match the longest maxDuration any
function in vercel.json is given, so a job can never be reclaimed while it is
still legitimately running.

Note this claims a job, not an OWNER. Two messages from the same person are
both claimable; the worker holds the second one back itself (see
otherJobRunningFor in api/_lib/db.ts), because interleaving two turns of one
conversation makes it jump backwards in front of a real person.
*/
CREATE OR REPLACE FUNCTION public.claim_job(p_worker text)
RETURNS SETOF public.jobs
LANGUAGE sql
AS $$
  WITH picked AS (
    SELECT id
      FROM public.jobs
     WHERE (status = 'queued'  AND run_after <= now())
        OR (status = 'running' AND locked_at < now() - interval '5 minutes')
     ORDER BY run_after, id
     FOR UPDATE SKIP LOCKED
     LIMIT 1
  )
  UPDATE public.jobs j
     SET status     = 'running',
         locked_at  = now(),
         locked_by  = p_worker,
         attempts   = j.attempts + 1,
         updated_at = now()
    FROM picked
   WHERE j.id = picked.id
  RETURNING j.*;
$$;

-- ── Meta redelivers. Handle each message exactly once. ───────────
CREATE TABLE IF NOT EXISTS public.wa_inbound (
  wa_message_id text PRIMARY KEY,
  wa_id text NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now()
);

-- ── Message log: richer, and now written in BOTH directions ──────
ALTER TABLE public.messages
  ADD COLUMN IF NOT EXISTS kind text DEFAULT 'text',
  ADD COLUMN IF NOT EXISTS wa_message_id text,
  ADD COLUMN IF NOT EXISTS meta jsonb DEFAULT '{}'::jsonb;

-- ── Guardrails that can be audited ───────────────────────────────
CREATE TABLE IF NOT EXISTS public.safety_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  check_name text NOT NULL,          -- distress | step_compliance | question_gate | selection | map_score
  engine text NOT NULL,              -- jev | model | none
  outcome text NOT NULL,             -- pass | flag | block | unavailable
  score numeric,
  flags text[],
  detail text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS safety_events_recent_idx ON public.safety_events (created_at DESC);
CREATE INDEX IF NOT EXISTS safety_events_outcome_idx ON public.safety_events (outcome, created_at DESC);

-- ── Evidence for whether semantic search is ever needed ──────────
CREATE TABLE IF NOT EXISTS public.retrieval_gaps (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  business_id uuid REFERENCES public.businesses(id) ON DELETE SET NULL,
  country text,
  query text NOT NULL,
  domain text,
  top_score numeric NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS retrieval_gaps_recent_idx ON public.retrieval_gaps (created_at DESC);

-- ── Follow-through ───────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.commitments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  plan_step_id uuid REFERENCES public.plan_steps(id) ON DELETE SET NULL,
  what text NOT NULL,
  due date,
  status text NOT NULL DEFAULT 'open',   -- open | done | stuck | dropped
  source text NOT NULL DEFAULT 'whatsapp',
  nudged_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS commitments_open_idx ON public.commitments (business_id, status, due);

CREATE TABLE IF NOT EXISTS public.outcomes (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  plan_step_id uuid REFERENCES public.plan_steps(id) ON DELETE SET NULL,
  what text,
  effect text,                            -- better | same | worse | too_early
  source text NOT NULL DEFAULT 'whatsapp',
  created_at timestamptz NOT NULL DEFAULT now()
);

-- `decisions` predates this build and had no primary key or reason column.
ALTER TABLE public.decisions
  ADD COLUMN IF NOT EXISTS id uuid DEFAULT gen_random_uuid(),
  ADD COLUMN IF NOT EXISTS why text,
  ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();

-- ── Nudges, and the templates Meta has to approve first ──────────
CREATE TABLE IF NOT EXISTS public.wa_templates (
  id text PRIMARY KEY,                    -- our id, e.g. 'commitment_check'
  meta_name text,                         -- the name registered with Meta
  language text NOT NULL DEFAULT 'en',
  category text NOT NULL DEFAULT 'UTILITY',
  body text NOT NULL,
  variables text[] NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'draft',   -- draft | submitted | approved | rejected
  approved_on date,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.nudges (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  template_id text,
  variables jsonb NOT NULL DEFAULT '{}'::jsonb,
  reason text,
  status text NOT NULL DEFAULT 'sent',    -- sent | skipped | failed
  sent_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS nudges_business_idx ON public.nudges (business_id, sent_at DESC);

-- ── The owner's own AI ───────────────────────────────────────────
-- Only the hash is stored: a leaked database row cannot be replayed as a token.
CREATE TABLE IF NOT EXISTS public.connector_tokens (
  token_hash text PRIMARY KEY,
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  label text,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);
CREATE INDEX IF NOT EXISTS connector_tokens_business_idx ON public.connector_tokens (business_id);

CREATE TABLE IF NOT EXISTS public.proposed_changes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  fact text NOT NULL,
  from_value text,
  to_value text,
  reason text,
  status text NOT NULL DEFAULT 'pending', -- pending | accepted | rejected | expired
  created_at timestamptz NOT NULL DEFAULT now(),
  decided_at timestamptz
);
CREATE INDEX IF NOT EXISTS proposed_changes_pending_idx ON public.proposed_changes (business_id, status);

-- ── Seeing your plan on the website ──────────────────────────────
-- The owner's WhatsApp number is the identity; the one-time code arrives on
-- WhatsApp, so only someone holding that phone can log in. Hashes only.
CREATE TABLE IF NOT EXISTS public.plan_access_codes (
  wa_id text PRIMARY KEY,
  code_hash text NOT NULL,
  expires_at timestamptz NOT NULL,
  attempts int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.plan_sessions (
  token_hash text PRIMARY KEY,
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ── Columns the rest of the build needs ──────────────────────────
ALTER TABLE public.businesses
  ADD COLUMN IF NOT EXISTS language text DEFAULT 'en',
  ADD COLUMN IF NOT EXISTS consent_at timestamptz,
  ADD COLUMN IF NOT EXISTS nudge_prefs jsonb DEFAULT '{"day":"monday","hour":7,"max_per_week":2}'::jsonb,
  ADD COLUMN IF NOT EXISTS paused boolean DEFAULT false,
  ADD COLUMN IF NOT EXISTS last_inbound_at timestamptz,
  ADD COLUMN IF NOT EXISTS last_outbound_at timestamptz,
  ADD COLUMN IF NOT EXISTS pending_action jsonb,
  ADD COLUMN IF NOT EXISTS walk jsonb,
  ADD COLUMN IF NOT EXISTS baseline_tier text,
  ADD COLUMN IF NOT EXISTS deleted_at timestamptz;

ALTER TABLE public.plan_steps
  ADD COLUMN IF NOT EXISTS pushed_at timestamptz,
  ADD COLUMN IF NOT EXISTS done_at timestamptz,
  ADD COLUMN IF NOT EXISTS skipped_reason text,
  ADD COLUMN IF NOT EXISTS step_key text;      -- the fixed library id, e.g. 'o2'

-- model_config: a role can now name its own ordered fallbacks, so a deprecated
-- model is one UPDATE away from fixed instead of a redeploy.
ALTER TABLE public.model_config
  ADD COLUMN IF NOT EXISTS fallbacks text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS enabled boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS notes text;

-- The seeded voice row used "groq/whisper-large-v3", which is not how
-- OpenRouter namespaces Whisper (groq is a provider that serves the model, not
-- the slug namespace). A wrong slug surfaces as a 400 on the first voice note,
-- not at deploy time. OpenRouter proxies an OpenAI-shaped transcription
-- endpoint, so voice needs no second account and no second key.
--   Transcription models are hidden from the default catalogue; list them with
--   https://openrouter.ai/api/v1/models?output_modalities=transcription
-- To move voice to Groq or OpenAI later (cheaper per hour, and the only way to
-- get per-segment confidence back), change provider and model on this one row.
UPDATE public.model_config
   SET provider = 'openrouter',
       model = 'openai/whisper-1',
       notes = 'Transcription via OpenRouter /audio/transcriptions. Set provider to groq or openai (with GROQ_API_KEY / OPENAI_API_KEY) to route direct.'
 WHERE role = 'voice' AND model = 'groq/whisper-large-v3';

-- The safety role did not exist before: the P10 check had no model to run on.
INSERT INTO public.model_config (role, provider, model, params, notes) VALUES
  ('safety', 'openrouter', 'google/gemma-4-31b-it:free', '{"max_tokens": 400, "temperature": 0}'::jsonb,
   'Backstop for the guardrails when Jev is unavailable. Small and strict; never writes owner-facing prose.')
ON CONFLICT (role) DO NOTHING;

-- ── Lock every new table ─────────────────────────────────────────
ALTER TABLE public.jobs              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.wa_inbound        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.safety_events     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.retrieval_gaps    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commitments       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.outcomes          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nudges            ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.wa_templates      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.connector_tokens  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.proposed_changes  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.plan_access_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.plan_sessions     ENABLE ROW LEVEL SECURITY;

-- claim_job runs as the caller (service role). Nobody else may execute it.
REVOKE ALL ON FUNCTION public.claim_job(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.claim_job(text) FROM anon, authenticated;


-- ============================================================================
-- 0006_freshness_and_templates.sql
-- ============================================================================

/*
# Charlie — knowledge freshness + the WhatsApp templates (apply AFTER 0005)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this does, in plain terms
- Two views that answer "what in the knowledge base is out of date?" without
  anyone having to remember to look. Anything checked more than 90 days ago is
  stale; the plan builder already hedges those to "confirm at sign-up", and the
  quarterly job writes a report so a human can go re-check them.
- The five follow-up messages, written out as the templates Meta has to approve
  before Charlie is allowed to start a conversation outside the 24-hour window.
  They live in the database so the approved Meta name can be filled in later
  without touching code.
*/

-- ── What has gone stale ──────────────────────────────────────────
CREATE OR REPLACE VIEW public.knowledge_freshness AS
SELECT id, country, domain, title, verified_on,
       (CURRENT_DATE - verified_on) AS days_old,
       (verified_on IS NULL OR CURRENT_DATE - verified_on > 90) AS is_stale
  FROM public.knowledge_entries;

CREATE OR REPLACE VIEW public.tools_freshness AS
SELECT id, country, domain, name, cost, verified_on,
       (CURRENT_DATE - verified_on) AS days_old,
       (verified_on IS NULL OR CURRENT_DATE - verified_on > 90) AS is_stale
  FROM public.tools;

CREATE TABLE IF NOT EXISTS public.freshness_reports (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  ran_at timestamptz NOT NULL DEFAULT now(),
  stale_knowledge int NOT NULL DEFAULT 0,
  stale_tools int NOT NULL DEFAULT 0,
  detail jsonb NOT NULL DEFAULT '{}'::jsonb
);
ALTER TABLE public.freshness_reports ENABLE ROW LEVEL SECURITY;

-- ── The five templates ───────────────────────────────────────────
-- Meta's own placeholder syntax is {{1}}, {{2}} — positional, not named.
-- Keep the wording short: these are interruptions, and they cost money.
INSERT INTO public.wa_templates (id, meta_name, language, category, body, variables, status) VALUES
  ('commitment_check', 'charlie_commitment_check', 'en', 'UTILITY',
   'Did you manage to {{1}}? Tap Done, or Help me if you got stuck.',
   ARRAY['what_they_committed_to'], 'draft'),
  ('monday_focus', 'charlie_monday_focus', 'en', 'UTILITY',
   'This week for {{1}}: {{2}}. Reply NEXT when you want the step.',
   ARRAY['business_name','one_thing'], 'draft'),
  ('month_end_money', 'charlie_month_end_money', 'en', 'UTILITY',
   'Month-end. Want me to draft the reminders to whoever still owes {{1}}? Reply YES.',
   ARRAY['business_name'], 'draft'),
  ('monthly_checkin', 'charlie_monthly_checkin', 'en', 'UTILITY',
   'Quick one for {{1}}: sales this month against last month — up, same or down?',
   ARRAY['business_name'], 'draft'),
  ('reengage', 'charlie_reengage', 'en', 'UTILITY',
   'Still thinking about {{1}}? Reply and we pick up exactly where we left off.',
   ARRAY['their_open_headache'], 'draft'),
  -- Signing in to read the plan on the web. Meta categorises one-time codes
  -- separately from utility messages, and an AUTHENTICATION template is the
  -- only thing that will deliver a code outside the 24-hour window.
  ('login_code', 'charlie_login_code', 'en', 'AUTHENTICATION',
   'Your Charlie code is {{1}}. It works for ten minutes. If you did not ask for it, ignore this message.',
   ARRAY['code'], 'draft')
ON CONFLICT (id) DO NOTHING;


-- ============================================================================
-- 0007_forget_cascades.sql
-- ============================================================================

/*
# Charlie — make "forget my business" actually possible (apply AFTER 0005, 0006)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this fixes, in plain terms
An owner can send "forget my business" and everything about them is deleted.
That promise is in the product and it is a POPIA obligation. But `wa_id` is
UNIQUE on `businesses`, so anything short of removing the row leaves that
phone number permanently taken — and the owner who changes their mind a week
later cannot come back, because creating their business fails on a constraint
they can neither see nor clear.

So the deletion has to be a real one. These tables were created before the
rest of the schema and their foreign keys have no ON DELETE behaviour at all,
which means deleting a business fails on the first child row instead.

2. Why cascade rather than deleting each table by hand
The backend does delete the children explicitly too, so this works whether or
not this file has been applied. But a promise about someone's data should not
depend on an application remembering every table — the next table someone adds
would quietly break it. The database should enforce it.

3. `decisions` has no primary key in the original schema
It was created as an append-only log. Adding one now makes it addressable,
which the connector's decision history needs.
*/

-- plans → businesses
ALTER TABLE public.plans DROP CONSTRAINT IF EXISTS plans_business_id_fkey;
ALTER TABLE public.plans
  ADD CONSTRAINT plans_business_id_fkey
  FOREIGN KEY (business_id) REFERENCES public.businesses(id) ON DELETE CASCADE;

-- plan_steps → plans
ALTER TABLE public.plan_steps DROP CONSTRAINT IF EXISTS plan_steps_plan_id_fkey;
ALTER TABLE public.plan_steps
  ADD CONSTRAINT plan_steps_plan_id_fkey
  FOREIGN KEY (plan_id) REFERENCES public.plans(id) ON DELETE CASCADE;

-- business_map → businesses
ALTER TABLE public.business_map DROP CONSTRAINT IF EXISTS business_map_business_id_fkey;
ALTER TABLE public.business_map
  ADD CONSTRAINT business_map_business_id_fkey
  FOREIGN KEY (business_id) REFERENCES public.businesses(id) ON DELETE CASCADE;

-- decisions → businesses
ALTER TABLE public.decisions DROP CONSTRAINT IF EXISTS decisions_business_id_fkey;
ALTER TABLE public.decisions
  ADD CONSTRAINT decisions_business_id_fkey
  FOREIGN KEY (business_id) REFERENCES public.businesses(id) ON DELETE CASCADE;

-- The map is upserted per (business, domain); without this key that upsert
-- silently becomes an insert and the map grows a duplicate row every turn.
CREATE UNIQUE INDEX IF NOT EXISTS business_map_business_domain_key
  ON public.business_map (business_id, domain);

-- Make the decision log addressable, for the connector's history.
ALTER TABLE public.decisions ADD COLUMN IF NOT EXISTS id uuid DEFAULT gen_random_uuid();
UPDATE public.decisions SET id = gen_random_uuid() WHERE id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS decisions_id_key ON public.decisions (id);

-- Worth knowing at a glance how many owners have asked to be forgotten.
CREATE TABLE IF NOT EXISTS public.forget_log (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  country text,
  requested_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.forget_log IS
  'One row per "forget my business", with NOTHING identifying in it. Enough to answer "how many people asked?" without keeping what they asked us to delete.';
ALTER TABLE public.forget_log ENABLE ROW LEVEL SECURITY;

-- `businesses.deleted_at` from 0005 is now unused: forgetting removes the row.
-- It is left in place rather than dropped, because dropping a column is the one
-- migration that cannot be undone by re-running a file.
COMMENT ON COLUMN public.businesses.deleted_at IS
  'Unused. "Forget my business" deletes the row outright — a soft delete would leave wa_id taken (it is UNIQUE) and the owner could never come back.';


-- ============================================================================
-- 0008_strategy.sql
-- ============================================================================

/*
# Charlie — the strategy document (apply AFTER 0007)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this adds, in plain terms
The plan document was a list of steps with a map stapled to the front. Real
feedback: no depth. An owner — and a funder they show it to — needs three
things in one document: where the business stands today, the strategy (who we
serve, why they choose us, how we win, what we deliberately won't do, the
money logic in the owner's own numbers), and only THEN the 90 days of steps.

The steps stay exactly what they were: assembled from the fixed library,
never freestyled (rule 1). The strategy is prose, not structure, so the model
may write it — grounded in the diagnostic, the chosen customer and angle, and
the verified library, and checked by the same guardrails as everything else
before it is stored.

2. Why a column on `plans` rather than its own table
The strategy is written once, with the plan, from the same evidence, and is
meaningless without it. One row, one document.
*/

ALTER TABLE public.plans ADD COLUMN IF NOT EXISTS strategy jsonb;

COMMENT ON COLUMN public.plans.strategy IS
  'The narrative two-thirds of the plan document: reading of the business, what is working and leaking, how we win, what we will not do, the money logic in the owner''s own numbers, milestones at day 30/60/90, and risks with responses. Written by the plan_builder model, grounded and compliance-checked. Null on plans built before this existed — the document renders without it.';


-- ============================================================================
-- 0009_mimo_and_usage.sql
-- ============================================================================

/*
# Charlie — one model for everything, and a real cost meter (apply AFTER 0008)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this does, in plain terms
- Points every role at Xiaomi MiMo-V2.5 (`xiaomi/mimo-v2.5` on OpenRouter): one
  model that reads text, pictures, voice notes and video, at roughly
  $0.14 per million tokens in and $0.28 out. The text-only MiMo-V2.5-Pro is the
  one configured fallback for every role.
- `model_usage`: one row per model call (tokens and, when OpenRouter reports
  it, dollars). PRODUCT-DEFINITION section 7 says to measure real cost per
  active owner in the pilot before quoting anyone a price; this is that
  measurement.

2. Reasoning
MiMo can spend tokens "thinking" before it answers. That is good for the plan
and wasteful for a yes/no. So the `reasoning` setting is per role, in `params`:
off for the classifier and the safety backstop, low for live replies, medium for
the plan builder. If the usage table shows reasoning eating more than it earns,
change it here with one UPDATE — no deploy.

3. Voice
The `voice` row now uses provider `openrouter_chat`: MiMo listens to the note
directly. If that call fails, the code falls back to Whisper on OpenRouter's
transcription route, so a voice note is never simply dropped.

4. Security
`model_usage` is RLS-on with no policies, like every other table.
*/

CREATE TABLE IF NOT EXISTS public.model_usage (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  role text,
  model text,
  prompt_tokens int NOT NULL DEFAULT 0,
  completion_tokens int NOT NULL DEFAULT 0,
  cost_usd numeric(12, 6),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS model_usage_created_idx ON public.model_usage (created_at DESC);
CREATE INDEX IF NOT EXISTS model_usage_role_idx ON public.model_usage (role, created_at DESC);
ALTER TABLE public.model_usage ENABLE ROW LEVEL SECURITY;

-- Every role gets the same model. `params || ...` merges, so max_tokens and
-- temperature already set on a row are kept.
UPDATE public.model_config
   SET provider = 'openrouter',
       model = 'xiaomi/mimo-v2.5',
       fallbacks = ARRAY['xiaomi/mimo-v2.5-pro'],
       params = params || '{"reasoning": {"enabled": false}}'::jsonb
 WHERE role IN ('router', 'safety');

UPDATE public.model_config
   SET provider = 'openrouter',
       model = 'xiaomi/mimo-v2.5',
       fallbacks = ARRAY['xiaomi/mimo-v2.5-pro'],
       params = params || '{"reasoning": {"effort": "low"}}'::jsonb
 WHERE role IN ('wa_reply', 'help');

UPDATE public.model_config
   SET provider = 'openrouter',
       model = 'xiaomi/mimo-v2.5',
       fallbacks = ARRAY['xiaomi/mimo-v2.5-pro'],
       params = params || '{"reasoning": {"effort": "medium"}}'::jsonb
 WHERE role = 'plan_builder';

-- Voice: MiMo listens directly. Whisper on OpenRouter is the code-level fallback.
INSERT INTO public.model_config (role, provider, model, params, notes)
VALUES ('voice', 'openrouter_chat', 'xiaomi/mimo-v2.5', '{}'::jsonb,
        'MiMo hears the voice note itself. Falls back to openai/whisper-1 on the transcription route.')
ON CONFLICT (role) DO UPDATE
   SET provider = 'openrouter_chat', model = 'xiaomi/mimo-v2.5', notes = EXCLUDED.notes;


-- ============================================================================
-- 0010_vector_search.sql
-- ============================================================================

/*
# Charlie — semantic search, as a second pass under the keywords (apply AFTER 0009)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this does, in plain terms
Keyword search stays the default, because it is free and predictable. This
adds the second pass for the moment it fails: an owner asks in words the
library's keywords never anticipated, and instead of "nothing matched" the
question is matched by MEANING against the same knowledge and tool rows.

It only runs when keywords found nothing, so most messages never pay for it.
The embedding columns have existed since the start (1536 dimensions); this
adds the index, the two lookup functions, and a hash so an edited row is
re-embedded rather than left searching on stale text.

2. Which rows the second pass rescued
`retrieval_gaps.rescued` records whether meaning found something keywords
missed. A row with rescued = true is a keyword worth adding; a row with
rescued = false is a real gap in the library.

3. Security
The functions are callable only by the backend (service role). Nobody holding
the project's public key can call them.
*/

ALTER TABLE public.knowledge_entries ADD COLUMN IF NOT EXISTS embedding_hash text;
ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS embedding_hash text;
ALTER TABLE public.retrieval_gaps ADD COLUMN IF NOT EXISTS rescued boolean NOT NULL DEFAULT false;

CREATE INDEX IF NOT EXISTS knowledge_entries_embedding_idx
  ON public.knowledge_entries USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS tools_embedding_idx
  ON public.tools USING hnsw (embedding vector_cosine_ops);

CREATE OR REPLACE FUNCTION public.match_knowledge(
  query_embedding vector(1536),
  match_country text,
  match_count int DEFAULT 4
) RETURNS TABLE (id text, similarity double precision)
LANGUAGE sql STABLE AS $$
  SELECT k.id::text, 1 - (k.embedding <=> query_embedding)
    FROM public.knowledge_entries k
   WHERE k.country = match_country AND k.embedding IS NOT NULL
   ORDER BY k.embedding <=> query_embedding
   LIMIT match_count
$$;

CREATE OR REPLACE FUNCTION public.match_tools(
  query_embedding vector(1536),
  match_country text,
  match_count int DEFAULT 4
) RETURNS TABLE (id text, similarity double precision)
LANGUAGE sql STABLE AS $$
  SELECT t.id::text, 1 - (t.embedding <=> query_embedding)
    FROM public.tools t
   WHERE t.country = match_country AND t.embedding IS NOT NULL
   ORDER BY t.embedding <=> query_embedding
   LIMIT match_count
$$;

REVOKE ALL ON FUNCTION public.match_knowledge(vector, text, int) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.match_tools(vector, text, int) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.match_knowledge(vector, text, int) TO service_role;
GRANT EXECUTE ON FUNCTION public.match_tools(vector, text, int) TO service_role;


-- ============================================================================
-- 0011_surfaces.sql
-- ============================================================================

/*
# Charlie — the owner's progress view and the sponsor console (apply AFTER 0010)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more than once.

1. What this adds, in plain terms
- `businesses.map_first`: the eight-area map exactly as it stood on day one, kept
  so an owner can see where they started against where they are now. Written
  once, when the first plan is built, and never overwritten.
- `sponsor_tokens`: a funder's key to the cohort report. It can read aggregates
  and nothing else, can be revoked by its label, and is stored only as a hash.
  It is a separate key from the internal secret on purpose: that secret also runs
  the job queue and the PDF renderer.

2. Security
`sponsor_tokens` is RLS-on with no policies, like every other table.
*/

ALTER TABLE public.businesses ADD COLUMN IF NOT EXISTS map_first jsonb;

CREATE TABLE IF NOT EXISTS public.sponsor_tokens (
  token_hash text PRIMARY KEY,
  label text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);
CREATE INDEX IF NOT EXISTS sponsor_tokens_label_idx ON public.sponsor_tokens (label);
ALTER TABLE public.sponsor_tokens ENABLE ROW LEVEL SECURITY;

-- Meta fixes the wording of an AUTHENTICATION template, so the stored body has
-- to be Meta's, not ours. Only kept in sync so the table describes what is sent.
update public.wa_templates
   set body = '{{1}} is your verification code. For your security, do not share this code. This code expires in 10 minutes.'
 where id = 'login_code' and status = 'draft';


-- ============================================================================
-- 0012_plan_build_stages.sql
-- ============================================================================

/*
# Charlie — resumable plan builds (apply AFTER 0001–0011)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this does, in plain terms
Before this, building a 90-day plan was one function call doing five or six
model calls back to back — context, a module audit, a strategy, and one call
per part of the plan — inside a single job that a single Vercel invocation
had to finish inside its own timeout. A stuck or slow call anywhere in that
chain meant the whole thing had to be retried from the top, and the owner's
`stage` sat on "building_plan" with nothing behind it to show for however
long that took.

`plan_builds` is the durable memory of how far a build has actually got.
Each phase (context, then strategy + the plan's parts together, then
writing the plan to the database, then the PDF) now runs as its own short
job, and writes what it produced here before the next phase is even
enqueued. A crash or a Vercel timeout loses at most one phase's work, not
the whole build — the next attempt picks up from `stage`, not from zero.

2. Why heartbeat_at, not the jobs table's own 5-minute reclaim
`claim_job()` reclaims an abandoned 'running' job after 5 minutes — sized to
the longest function timeout in vercel.json, because a job legitimately
running the OLD, monolithic build really could take that long. A single
*stage* here is one or two model calls: if a stage job's heartbeat has gone
quiet for even 90 seconds, something has actually gone wrong, and the
opportunistic sweep in api/_lib/queue.ts re-enqueues that phase rather than
waiting minutes to notice.

3. Security
Owner data: RLS enabled, no policies — service role only, same as every
table in db/0005.
*/

CREATE TABLE IF NOT EXISTS public.plan_builds (
  business_id uuid PRIMARY KEY REFERENCES public.businesses(id) ON DELETE CASCADE,
  stage text NOT NULL DEFAULT 'context',   -- context | building | finalize | pdf | done | failed
  goal text,
  context jsonb,
  map jsonb,
  dropped_modules text[] NOT NULL DEFAULT '{}',
  strategy jsonb,
  strategy_done boolean NOT NULL DEFAULT false,
  workstreams jsonb NOT NULL DEFAULT '[]'::jsonb,
  pending_workstreams text[] NOT NULL DEFAULT '{}',
  plan_id uuid REFERENCES public.plans(id) ON DELETE SET NULL,
  last_error text,
  heartbeat_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS plan_builds_stale_idx ON public.plan_builds (stage, heartbeat_at);

ALTER TABLE public.plan_builds ENABLE ROW LEVEL SECURITY;


-- ============================================================================
-- 0013_claim_job_owner_order.sql
-- ============================================================================

/*
# Charlie — claim_job() must never skip over an earlier job for the same owner

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What was actually wrong (PRIORITY 0, live-verified 2026-09-22)
`claim_job()` (db/0005) picked the globally earliest eligible row by
`(run_after, id)`, with NO awareness of `wa_id` at all. Per-owner exclusion was
bolted on AFTER the claim, in application code (api/_lib/queue.ts's
otherJobRunningFor + holdJob): a worker claimed a job, THEN asked "is another
job for this owner already running?", and if so put it straight back with
`run_after = now() + 5s`.

That after-the-fact hold is what actually produced the bug. A live burst of
four messages 2-3s apart (jobs 59-62 for one wa_id) was claimed in the order
59 -> 61 -> 62 -> 60: job 60 kept losing the claim race, got held, and every
hold pushed its `run_after` five seconds into the future — which is often
LATER than a message the owner hadn't even sent yet when 60 was first held.
Once 61 and 62 existed with their own (earlier, untouched) `run_after`, they
sorted ahead of 60's repeatedly-postponed one, and 60 was claimed dead last.
The "done" tap's own handler was fine (proven separately, live, with real
pauses between messages) — the ordering was corrupted before it ever ran.

The same after-the-claim check also has a TOCTOU race: two workers can each
claim a DIFFERENT job for the SAME owner within milliseconds of each other,
and each one's "is anyone else running?" query can run before the other's
claim has committed, so BOTH proceed unheld. That is a second, independent way
for two messages from one owner to be handled concurrently, which is very
likely the root cause of two other bugs found the same day: a diagnostic
answer landing under the wrong key when a later message raced an earlier one's
read-modify-write, and a duplicate "That's right / Not quite" identity
read-back sent by two concurrent handlers.

2. The fix
Move the per-owner ordering INTO the same atomic statement that claims the
job, instead of checking it afterwards from a second, separate query. A job is
now only eligible to be claimed at all when no EARLIER job (by id) for the
same wa_id is still `queued`, `running` or `failed`. Under Postgres's default
READ COMMITTED isolation, an uncommitted status change made by a concurrent
claim is invisible to this check until it actually commits — so two workers
racing for the same owner's jobs cannot both conclude "nothing else is
pending" at once, and a job can never be handed out ahead of an older one for
its own owner, however the claim attempts are timed or ordered.

`otherJobRunningFor` / `holdJob` in api/_lib/queue.ts are kept as a harmless,
now-redundant safety net (see the comment above their use) rather than
removed, since this migration is the thing that actually has to land in
production for the fix to take effect.

3. Verify it worked
  select id, wa_id, status, locked_at from public.jobs where wa_id = '<a real
  wa_id>' order by id; -- locked_at should only ever advance in id order.
*/

CREATE OR REPLACE FUNCTION public.claim_job(p_worker text)
RETURNS SETOF public.jobs
LANGUAGE plpgsql
AS $$
DECLARE
  v_id bigint;
BEGIN
  SELECT j.id
    INTO v_id
    FROM public.jobs j
   WHERE (
           (j.status = 'queued'  AND j.run_after <= now())
        OR (j.status = 'running' AND j.locked_at < now() - interval '5 minutes')
         )
     AND (
           j.wa_id IS NULL
           -- Strict creation order, per owner: a job is claimable only when no
           -- STILL-PENDING earlier job (lower id) exists for the same wa_id.
           -- 'failed' is included defensively — nothing in this codebase sets
           -- it today (a failed attempt goes back to 'queued' with backoff, or
           -- to 'dead' once max_attempts is hit), but a job in that state has
           -- not finished either, and must not be skipped over any more than
           -- a 'queued' or 'running' one.
        OR NOT EXISTS (
             SELECT 1
               FROM public.jobs o
              WHERE o.wa_id = j.wa_id
                AND o.id < j.id
                AND o.status IN ('queued', 'running', 'failed')
           )
         )
   ORDER BY j.run_after, j.id
   FOR UPDATE OF j SKIP LOCKED
   LIMIT 1;

  IF v_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  UPDATE public.jobs j
     SET status     = 'running',
         locked_at  = now(),
         locked_by  = p_worker,
         attempts   = j.attempts + 1,
         updated_at = now()
   WHERE j.id = v_id
  RETURNING j.*;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_job(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.claim_job(text) FROM anon, authenticated;

-- Speeds the per-owner NOT EXISTS check above: without it, every claim scans
-- every other queued/running job for a busy owner instead of an index range.
CREATE INDEX IF NOT EXISTS jobs_owner_order_idx ON public.jobs (wa_id, id) WHERE wa_id IS NOT NULL;


-- ============================================================================
-- 0013_tool_content_fixes.sql
-- ============================================================================

/*
# Charles — `tools.needs_verification` (apply AFTER 0012)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once: the only statement is an idempotent ADD COLUMN.

In Charlie this file also corrected a handful of business-tool rows. Charles
carries none of those rows (its library is db/0034, generated from seed/),
so only the schema part is kept. The flag means the same thing here: a
human still needs to check this row's steps against the live site, and the
code shows the row with that hedge instead of hiding it.

Security: `tools` is a reference table (RLS public-read since db/0001);
adding a column changes no policy.
*/

ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS needs_verification boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN public.tools.needs_verification IS 'True when the walkthrough has not been checked against the live site. Shown with a hedge, never hidden.';


-- ============================================================================
-- 0014_tools_ingestion.sql
-- ============================================================================

/*
# Charles — tools: which kind of free, works-without-a-payslip, a ten-minute first action (apply AFTER both 0013 files)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once: every column is ADD COLUMN IF NOT EXISTS and the constraint is
added only if missing.

1. What this does, in plain terms
  - Adds three columns to `tools`:
      `free_type text NOT NULL DEFAULT 'UNKNOWN'` — WHICH kind of free (or
        not) a tool is: FREE_FOREVER, FREE_TIER, FREE_TRIAL,
        FREE_FOR_QUALIFYING_USERS, NO_MONTHLY_FEE, PAY_PER_TRANSACTION,
        GOVERNMENT_GRANT or UNKNOWN (CHECK-constrained to exactly those).
        The default is UNKNOWN on purpose: a row nobody classified can never
        be labelled free by accident. See api/_lib/freetype.ts for the label
        each one puts in front of the cost, everywhere a cost is shown.
      `informal_business_supported boolean` — for Charles: can a person with
        no payslip, no formal job or no bank statement use it? NULL means
        nobody checked, and the code never reads NULL as "no".
      `ten_minute_action text` — the one thing a person can do in the next
        ten minutes to start. Required for every row in seed/tools.json
        (enforced by test/tools-ingestion.test.ts, not by a constraint).
  - Adds no rows. In Charlie this file also inserted ten business tools;
    Charles's whole library is db/0034, generated from seed/, so a fresh
    project holds exactly the rows in seed/tools.json and nothing else.

2. Security
`tools` is a reference table (RLS public-read since db/0001); adding columns
changes no policy.
*/

-- ── 1. Columns ──────────────────────────────────────────────────────────
ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS free_type text NOT NULL DEFAULT 'UNKNOWN';
ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS informal_business_supported boolean;
ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS ten_minute_action text;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'tools_free_type_check' AND conrelid = 'public.tools'::regclass
  ) THEN
    ALTER TABLE public.tools ADD CONSTRAINT tools_free_type_check CHECK (free_type IN (
      'FREE_FOREVER', 'FREE_TIER', 'FREE_TRIAL', 'FREE_FOR_QUALIFYING_USERS',
      'NO_MONTHLY_FEE', 'PAY_PER_TRANSACTION', 'GOVERNMENT_GRANT', 'UNKNOWN'
    ));
  END IF;
END $$;

COMMENT ON COLUMN public.tools.free_type IS 'Which kind of free (or not) this tool is. See api/_lib/freetype.ts. UNKNOWN is never labelled free.';
COMMENT ON COLUMN public.tools.informal_business_supported IS 'Usable with no payslip, formal job or bank statement? NULL = not checked, never read as no.';
COMMENT ON COLUMN public.tools.ten_minute_action IS 'The first thing a person can do in ten minutes. Required on every seed row (enforced in tests).';


-- ============================================================================
-- 0015_knowledge_signals.sql
-- ============================================================================

/*
# Charlie — knowledge_signals: what real conversations say the library is missing or has wrong (apply AFTER 0014)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. What this is
One small, dated, atomic row per thing worth a second look — never a growing
transcript. The same pattern as `retrieval_gaps` (db/0005), generalised:
  - unanswered_question  a question the library could not match (written
                         alongside every retrieval_gaps row, no extra cost)
  - correction           an owner (or their connected AI) says a stored fact
                         is wrong: "that's not R699 anymore"
  - outcome_report       an owner reports how a tool or step actually went:
                         "Yoco took 3 days, not 1-2"
  - new_fact_candidate   something a connected AI logged that the library
                         might want to know
  - contradiction        reserved for the promotion pass (docs/PROMOTION-PASS.md)

2. What it is NOT
Nothing here ever changes `tools` or `knowledge_entries` by itself. A signal
is one owner's anecdote. Promotion to canonical fact is a deliberate,
agent-run research pass with a cited source and a checked date — see
docs/PROMOTION-PASS.md — never code.

3. Privacy
`raw_quote` is the owner's (or their AI's) own words, so it is owner data:
the row belongs to the business and goes when the business goes (ON DELETE
CASCADE, and api/_lib/db.ts forgetBusiness deletes it explicitly as well).
RLS on, no policies: only the service role (this backend) can read or write,
exactly like every other owner-data table since db/0001.
*/

CREATE TABLE IF NOT EXISTS public.knowledge_signals (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  source text NOT NULL CHECK (source IN ('whatsapp', 'mcp')),
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  country text,
  signal_type text NOT NULL CHECK (signal_type IN ('correction', 'new_fact_candidate', 'unanswered_question', 'outcome_report', 'contradiction')),
  related_entity_type text CHECK (related_entity_type IS NULL OR related_entity_type IN ('tool', 'knowledge_entry')),
  related_entity_id text,
  raw_quote text NOT NULL CHECK (char_length(raw_quote) BETWEEN 1 AND 2000),
  candidate_claim text CHECK (candidate_claim IS NULL OR char_length(candidate_claim) <= 500),
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'reviewed', 'promoted', 'rejected')),
  reviewed_at timestamptz,
  reviewed_by text,
  notes text,
  CHECK ((related_entity_type IS NULL) = (related_entity_id IS NULL))
);

CREATE INDEX IF NOT EXISTS knowledge_signals_open_idx ON public.knowledge_signals (status, related_entity_type, related_entity_id, created_at DESC);
CREATE INDEX IF NOT EXISTS knowledge_signals_business_idx ON public.knowledge_signals (business_id);

COMMENT ON TABLE public.knowledge_signals IS
  'Atomic, dated signals from real conversations that the library may be missing or wrong. Never promoted automatically: see docs/PROMOTION-PASS.md.';

ALTER TABLE public.knowledge_signals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.knowledge_signals FROM anon, authenticated;


-- ============================================================================
-- 0016_signals_web_source.sql
-- ============================================================================

/*
# Charlie — knowledge signals can come from the web ask page too (apply AFTER 0015)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

The web page /ask.html (api/ask.ts) answers an owner's questions with the
same engine as WhatsApp, so the same owner-typed question can carry the
same kind of signal. `source` was CHECK-constrained to 'whatsapp' | 'mcp';
this widens it to include 'web'. Nothing else changes: no new table, no
policy change (RLS stays on, service-role only, as db/0015 set it).

Until this runs, a signal from the web page fails its insert — which is
not silent: api/_lib/db.ts records a knowledge_signal safety_events row
flagged write_failed with the database's own error message.
*/

ALTER TABLE public.knowledge_signals DROP CONSTRAINT IF EXISTS knowledge_signals_source_check;
ALTER TABLE public.knowledge_signals ADD CONSTRAINT knowledge_signals_source_check CHECK (source IN ('whatsapp', 'mcp', 'web'));


-- ============================================================================
-- 0018_messages_inbound_dedupe_index.sql
-- ============================================================================

/*
# Charlie — an index for "has this owner message already been recorded?" (apply AFTER 0017)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once (IF NOT EXISTS). Changes no data.

Why: round 6 made recording an owner's message idempotent. A retried or
reclaimed inbound job re-runs the turn, and used to write the same message
into the conversation twice (api/_lib/jobctx.ts). The check is
`select … from messages where wa_message_id = $1 and direction = 'in'`,
which runs on every inbound message. Without this, messages.wa_message_id
(db/0005) has no index, and that check scans the whole table.
*/

CREATE INDEX IF NOT EXISTS messages_in_wa_message_id_idx
  ON public.messages (wa_message_id)
  WHERE direction = 'in';


-- ============================================================================
-- 0024_tracking.sql
-- ============================================================================

/*
# Charlie — tracking: what owners do, how the platform performs, and every failure (apply AFTER 0023)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once. Code does not depend on it to keep working: until it runs, every
tracking write fails quietly (one console line) and the product carries on.

1. What this is
  - events         one row per thing that happened: an owner's tap, a stage
                   entered, a question answered or not, a model call and how
                   long it took, a WhatsApp send that failed, a job retried,
                   anything logged as an error. api/_lib/track.ts writes it.
  - incidents      one row per distinct problem (a fingerprint), counted:
                   first seen, last seen, how many times, when it was last
                   emailed. The per-minute tick (queue.ts cronTick → alerts.ts)
                   reads it to decide what to email, so one broken thing is one
                   email, not one per minute.
  - alert_state    when each kind of email last went out (rate limits).
  - event_daily    a daily count per event name, kept after events are pruned.

2. Privacy — "forget my business" stays true
An event's business_id and its `excerpt` (at most 200 characters of what the
owner said, phone numbers and links already stripped by the code) are the
only owner data here. When a business is deleted, the trigger below wipes
both from every one of its events BEFORE the row goes, so what is left is
anonymous: an event name, a stage, a time, a number. That keeps the funnel
honest (an owner who leaves still counts as someone who left) without keeping
anything they asked us to forget. api/_lib/db.ts forgetBusiness does the same
scrub explicitly as well, belt and braces, like every other table.
No raw phone number is ever stored here: `internal` marks the founder's and
the testers' own numbers (env INTERNAL_WA_IDS) so they stay out of the funnel.
RLS on, no policies, revoked from anon and authenticated: backend only.

3. Size
Info-level events are pruned after 180 days by the daily pass (alerts.ts);
warn and above are kept a year. event_daily keeps the counts for good.
*/

CREATE TABLE IF NOT EXISTS public.events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  at timestamptz NOT NULL DEFAULT now(),
  name text NOT NULL,
  category text NOT NULL CHECK (category IN ('behaviour', 'funnel', 'performance', 'failure', 'unmet_request', 'security', 'ops')),
  severity text NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warn', 'error', 'critical')),
  business_id uuid REFERENCES public.businesses(id) ON DELETE SET NULL,
  channel text CHECK (channel IN ('whatsapp', 'web', 'mcp', 'system')),
  country text,
  stage text,
  turn_id text,
  job_id bigint,
  ms bigint,
  props jsonb NOT NULL DEFAULT '{}'::jsonb,
  excerpt text CHECK (excerpt IS NULL OR length(excerpt) <= 200),
  fingerprint text,
  internal boolean NOT NULL DEFAULT false
);

-- int4 in the first draft: a long gap in ms overflows it and loses the batch.
ALTER TABLE public.events ALTER COLUMN ms TYPE bigint;

CREATE INDEX IF NOT EXISTS events_at_idx ON public.events (at DESC);
CREATE INDEX IF NOT EXISTS events_name_at_idx ON public.events (name, at DESC);
CREATE INDEX IF NOT EXISTS events_business_at_idx ON public.events (business_id, at DESC);
CREATE INDEX IF NOT EXISTS events_problems_idx ON public.events (at DESC) WHERE severity IN ('error', 'critical') OR category IN ('failure', 'unmet_request');

COMMENT ON TABLE public.events IS
  'Everything that happened: owner behaviour, funnel, performance, failures, unmet requests. Written by api/_lib/track.ts. Anonymised (business_id and excerpt cleared) when a business is forgotten.';

CREATE TABLE IF NOT EXISTS public.incidents (
  fingerprint text PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  severity text NOT NULL CHECK (severity IN ('info', 'warn', 'error', 'critical')),
  alert text NOT NULL DEFAULT 'digest' CHECK (alert IN ('none', 'digest', 'immediate')),
  summary text NOT NULL DEFAULT '',
  first_seen timestamptz NOT NULL DEFAULT now(),
  last_seen timestamptz NOT NULL DEFAULT now(),
  count integer NOT NULL DEFAULT 1,
  since_email integer NOT NULL DEFAULT 1,
  last_props jsonb NOT NULL DEFAULT '{}'::jsonb,
  emailed_at timestamptz,
  resolved_at timestamptz
);

CREATE INDEX IF NOT EXISTS incidents_pending_idx ON public.incidents (last_seen DESC) WHERE since_email > 0;

COMMENT ON TABLE public.incidents IS
  'One row per distinct problem, counted. Read every minute by alerts.ts to decide what to email. Never holds owner text or phone numbers.';

-- One atomic upsert-and-count, so two workers reporting the same problem in
-- the same second add up instead of overwriting each other.
CREATE OR REPLACE FUNCTION public.bump_incident(
  p_fingerprint text,
  p_name text,
  p_category text,
  p_severity text,
  p_alert text,
  p_summary text,
  p_props jsonb
) RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  INSERT INTO public.incidents AS i (fingerprint, name, category, severity, alert, summary, last_props)
  VALUES (p_fingerprint, p_name, p_category, p_severity, p_alert, left(p_summary, 500), coalesce(p_props, '{}'::jsonb))
  ON CONFLICT (fingerprint) DO UPDATE SET
    last_seen = now(),
    count = i.count + 1,
    since_email = i.since_email + 1,
    -- The worst it has ever been, so one critical repeat is never downgraded.
    severity = CASE
      WHEN array_position(ARRAY['info','warn','error','critical'], EXCLUDED.severity) > array_position(ARRAY['info','warn','error','critical'], i.severity) THEN EXCLUDED.severity
      ELSE i.severity END,
    alert = CASE WHEN EXCLUDED.alert = 'immediate' OR i.alert = 'immediate' THEN 'immediate' WHEN EXCLUDED.alert = 'digest' OR i.alert = 'digest' THEN 'digest' ELSE 'none' END,
    summary = left(EXCLUDED.summary, 500),
    last_props = EXCLUDED.last_props,
    resolved_at = NULL;
$$;

-- What an email carried is taken off, not zeroed: a repeat counted while the
-- email was being sent is still waiting for the next one.
CREATE OR REPLACE FUNCTION public.mark_incident_emailed(p_fingerprint text, p_sent integer, p_at timestamptz) RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  UPDATE public.incidents SET emailed_at = p_at, since_email = GREATEST(since_email - p_sent, 0) WHERE fingerprint = p_fingerprint;
$$;

CREATE TABLE IF NOT EXISTS public.alert_state (
  key text PRIMARY KEY,
  at timestamptz NOT NULL DEFAULT now(),
  detail text
);

CREATE TABLE IF NOT EXISTS public.event_daily (
  day date NOT NULL,
  name text NOT NULL,
  category text NOT NULL,
  internal boolean NOT NULL DEFAULT false,
  count integer NOT NULL,
  businesses integer NOT NULL DEFAULT 0,
  PRIMARY KEY (day, name, internal)
);

-- One UTC day's counts per event name, counted in the database whatever the
-- day's size, so nothing is lost when its events are pruned. Re-runnable.
CREATE OR REPLACE FUNCTION public.rollup_event_day(p_day date) RETURNS integer
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH r AS (
    INSERT INTO public.event_daily (day, name, category, internal, count, businesses)
    SELECT p_day, name, min(category), internal, count(*)::int, count(DISTINCT business_id)::int
    FROM public.events
    WHERE at >= (p_day::timestamp AT TIME ZONE 'UTC') AND at < ((p_day + 1)::timestamp AT TIME ZONE 'UTC')
    GROUP BY name, internal
    ON CONFLICT (day, name, internal) DO UPDATE SET count = EXCLUDED.count, businesses = EXCLUDED.businesses, category = EXCLUDED.category
    RETURNING 1
  )
  SELECT count(*)::int FROM r;
$$;

COMMENT ON TABLE public.event_daily IS 'Daily counts per event name, rolled up by alerts.ts before events are pruned. Nothing identifying.';

-- "forget my business": wipe the owner's words and the link to them from
-- their events before the business row is deleted (the FK then has nothing
-- left to set null). db.ts forgetBusiness does the same explicitly.
CREATE OR REPLACE FUNCTION public.scrub_events_on_forget() RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.events SET business_id = NULL, excerpt = NULL, turn_id = NULL WHERE business_id = OLD.id;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS scrub_events_on_forget ON public.businesses;
CREATE TRIGGER scrub_events_on_forget BEFORE DELETE ON public.businesses
  FOR EACH ROW EXECUTE FUNCTION public.scrub_events_on_forget();

-- Done and dead inbound jobs kept the owner's phone number and words in
-- payload after a forget (forgetBusiness only cleared queued ones). The code
-- now deletes every one that is not running, and the forget request's own
-- (running) job has its number and payload cleared once the forget succeeds.

ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.incidents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alert_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.events FROM anon, authenticated;
REVOKE ALL ON public.incidents FROM anon, authenticated;
REVOKE ALL ON public.alert_state FROM anon, authenticated;
REVOKE ALL ON public.event_daily FROM anon, authenticated;
REVOKE ALL ON FUNCTION public.bump_incident(text, text, text, text, text, text, jsonb) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.scrub_events_on_forget() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.mark_incident_emailed(text, integer, timestamptz) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.rollup_event_day(date) FROM PUBLIC, anon, authenticated;


-- ============================================================================
-- 0025_alert_levels.sql
-- ============================================================================

/*
# Charlie — alert levels that can come down (apply AFTER 0024)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once.

1. Why
0024's bump_incident kept the worst severity and the loudest alert an
incident had EVER had. So when the code decides a problem is quieter than it
first thought, the incident never hears it: round 19's
`delivery_failed:131026` (an undeliverable number — the recipient's side, now
an hourly warning) was stored as "immediate" and would have kept paging for
good. Now an incident takes the level of its latest occurrence once what came
before has been dealt with: emailed (nothing pending) or resolved. While
something louder is still waiting to be emailed it is never quietened — a
critical repeat is never lost to a warning that came after it.

2. The incidents round 19 filed wrongly, put right once
  - delivery_failed:131026  → warn, hourly (it was error, immediate)
  - "Error logged" lines that were not failures, resolved: the guardrail's own
    flags (safety[step_compliance] — it caught something, as designed), the
    log line of a delivery failure (delivery_failed is its record), the
    Meta number lookup on a health check; and Node's own runtime warning.
    The code no longer files any of these (PR "Round 19"), so resolving them
    does not hide anything that will happen again.
Only `incidents` is touched; no owner data.
*/

CREATE OR REPLACE FUNCTION public.bump_incident(
  p_fingerprint text,
  p_name text,
  p_category text,
  p_severity text,
  p_alert text,
  p_summary text,
  p_props jsonb
) RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  INSERT INTO public.incidents AS i (fingerprint, name, category, severity, alert, summary, last_props)
  VALUES (p_fingerprint, p_name, p_category, p_severity, p_alert, left(p_summary, 500), coalesce(p_props, '{}'::jsonb))
  ON CONFLICT (fingerprint) DO UPDATE SET
    last_seen = now(),
    count = i.count + 1,
    since_email = i.since_email + 1,
    -- Nothing pending (emailed, or resolved): this occurrence's own level.
    -- Something pending: the worst of the two, so it is never quietened.
    severity = CASE
      WHEN i.resolved_at IS NOT NULL OR i.since_email = 0 THEN EXCLUDED.severity
      WHEN array_position(ARRAY['info','warn','error','critical'], EXCLUDED.severity) > array_position(ARRAY['info','warn','error','critical'], i.severity) THEN EXCLUDED.severity
      ELSE i.severity END,
    alert = CASE
      WHEN i.resolved_at IS NOT NULL OR i.since_email = 0 THEN EXCLUDED.alert
      WHEN EXCLUDED.alert = 'immediate' OR i.alert = 'immediate' THEN 'immediate'
      WHEN EXCLUDED.alert = 'digest' OR i.alert = 'digest' THEN 'digest'
      ELSE 'none' END,
    summary = left(EXCLUDED.summary, 500),
    last_props = EXCLUDED.last_props,
    resolved_at = NULL;
$$;

REVOKE ALL ON FUNCTION public.bump_incident(text, text, text, text, text, text, jsonb) FROM PUBLIC, anon, authenticated;

UPDATE public.incidents
   SET alert = 'digest', severity = 'warn'
 WHERE fingerprint = 'delivery_failed:131026'
   AND alert = 'immediate';

UPDATE public.incidents
   SET resolved_at = now(), since_email = 0
 WHERE resolved_at IS NULL
   AND (
        (name = 'log_error' AND (
              summary LIKE 'Error logged: safety[step_compliance] flags%'
           OR summary LIKE 'Error logged: wa delivery failed%'
           OR summary LIKE 'Error logged: wa-number%'))
     OR (name = 'log_warning' AND summary LIKE 'Warning logged: (node:%')
   );


-- ============================================================================
-- 0026_kept_questions.sql
-- ============================================================================

/*
# Charlie — questions kept from the diagnostic; one stray incident (apply AFTER 0025)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once. The code does not depend on it: until it runs, a question asked
mid-diagnostic is not kept and the owner is asked to send it again, as before.

1. businesses.kept_questions
Round 20 (live): an owner asked "how much does it cost to register a business
name in Kenya?" at question 4 and was told to ask again later. Nothing kept
the question. Now it is kept here — at most three, each at most 300
characters, in the owner's words, with the question number and time — and
answered straight after the plan is handed over (api/_lib/engine/kept.ts).
Cleared once the answer is queued. Owner data like the rest of the row: it
goes when the business is forgotten, and RLS on businesses is unchanged
(service role only).

2. The Node warning incident 0025 missed
0025 resolved a "Warning logged: (node:…" incident, but in production the
runtime's ExperimentalWarning had been filed as an ERROR, under the catch-all
fingerprint "log_error:log" (a line starting with "(" left the fingerprint
nothing to name it by). The code stopped filing it in round 19, and a line
starting with "(" now gets a fingerprint of its own (track.ts), so this
resolves the one that exists.
*/

ALTER TABLE public.businesses ADD COLUMN IF NOT EXISTS kept_questions jsonb;

COMMENT ON COLUMN public.businesses.kept_questions IS
  'Questions the owner asked during the diagnostic, kept to be answered after the plan is handed over (engine/kept.ts). [{text, step, at}], at most 3. Never diagnostic answers.';

UPDATE public.incidents
   SET resolved_at = now(), since_email = 0
 WHERE resolved_at IS NULL
   AND fingerprint = 'log_error:log'
   AND summary LIKE 'Error logged: (node:%';


-- ============================================================================
-- 0032_owner_notes.sql
-- ============================================================================

/*
# Charlie — what Charlie remembers about the owner (apply AFTER 0031)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once. The code does not depend on it: until it runs, nothing about the
owner is remembered, every answer works as before, and the owner's AI is told
a note "could not be saved" (owner_notes_failed names this file).

1. owner_notes
Round 27: the owner's own AI (Claude, ChatGPT) can now drive Charlie through
the connector, and the founder asked that Charlie start remembering things
about the PERSON — the time they have, who helps them, how they like to work,
what worries them — so advice fits them on both doors. That is not a business
fact (businesses.context holds what they sell, who they sell to, their price)
and it is not a decision or a commitment, so it gets its own small table:

  - written by the owner's AI (the `remember` tool, source 'connector') and by
    the memory step after a WhatsApp or web answer (source 'whatsapp'/'web');
  - read back into every answer's prompt and the owner's AI's context;
  - deleted one at a time when the owner says "forget that" (`forget_note`),
    and all at once with the business ("forget my business": the cascade
    below, and api/_lib/db.ts forgetBusiness deletes it explicitly too).

Never an ID, bank, card, PIN or password detail: the tool and the memory
prompt both refuse them, and a note is at most 300 characters.

2. Locked like every other owner-data table
RLS on, no policies: only the backend's service role can read or write it.
The publishable key cannot see a single row.
*/

CREATE TABLE IF NOT EXISTS public.owner_notes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  about text NOT NULL DEFAULT 'other'
    CHECK (about IN ('person', 'situation', 'preference', 'constraint', 'worry', 'goal', 'other')),
  note text NOT NULL CHECK (char_length(note) BETWEEN 1 AND 300),
  source text NOT NULL DEFAULT 'connector' CHECK (source IN ('connector', 'whatsapp', 'web')),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS owner_notes_business_idx ON public.owner_notes (business_id, created_at DESC);

COMMENT ON TABLE public.owner_notes IS
  'What Charlie remembers about the owner as a person (time, help, preferences, worries), from their own AI or the WhatsApp/web memory step. Never ID, bank or card details. Deleted with the business.';

ALTER TABLE public.owner_notes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.owner_notes FROM anon, authenticated;


-- ============================================================================
-- 0033_charles_schema.sql
-- ============================================================================

/*
# Charles — the money journey's columns (from Charlie's business journey)

Apply in Supabase → SQL Editor → New query → paste → Run.
Run AFTER 0032. Safe to run more than once.

1. What this does, in plain terms
Charles is built from Charlie. The tables keep their names (a `businesses` row is
one household's money; `business_map` is the Money Map; `owner_notes` is what
Charles remembers about the person), because renaming every table buys nothing
and risks a lot. Four columns change meaning enough to deserve their new
names, and the code reads the new ones:

  pending_customer_options → pending_goal_options   (the goals offered)
  customer                 → goal                   (the goal(s) chosen)
  pending_angle_options    → pending_rule_options   (the rules offered)
  angle                    → rule                   (the rule(s) chosen)

`biz_stage` now holds the money stage: surviving | stretching | steady |
building. `business_map.domain` and `plan_steps.domain` now hold the eight
money areas: income, spending, debt, cushion, credit_record, protection,
family_money, goals. Neither column was ever constrained, so no constraint
changes.

2. Existing rows
A fresh project has none. On a project that ran Charlie, rows built for a
business are meaningless to Charles: delete them (or the whole project) before
pointing Charles at it. This script only renames; it never deletes.

3. Security
Nothing changes: RLS stays on, backend-only, as 0001 set it.
*/

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'pending_customer_options')
     AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'pending_goal_options') THEN
    ALTER TABLE public.businesses RENAME COLUMN pending_customer_options TO pending_goal_options;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'customer')
     AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'goal') THEN
    ALTER TABLE public.businesses RENAME COLUMN customer TO goal;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'pending_angle_options')
     AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'pending_rule_options') THEN
    ALTER TABLE public.businesses RENAME COLUMN pending_angle_options TO pending_rule_options;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'angle')
     AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'rule') THEN
    ALTER TABLE public.businesses RENAME COLUMN angle TO rule;
  END IF;
END $$;

-- A project that never ran Charlie (0004 applied after this file was written) gets the new names directly.
ALTER TABLE public.businesses
  ADD COLUMN IF NOT EXISTS pending_goal_options jsonb,
  ADD COLUMN IF NOT EXISTS goal jsonb,
  ADD COLUMN IF NOT EXISTS pending_rule_options jsonb,
  ADD COLUMN IF NOT EXISTS rule jsonb;

-- Running the whole script a second time: 0000 and 0004 add the Charlie
-- names back (IF NOT EXISTS, and they are gone), next to the new ones. Fold
-- anything in them into the new columns, then drop them, so the table ends
-- with one name per fact however many times the script runs.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'customer') THEN
    UPDATE public.businesses SET goal = customer WHERE goal IS NULL AND customer IS NOT NULL;
    ALTER TABLE public.businesses DROP COLUMN customer;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'angle') THEN
    UPDATE public.businesses SET rule = angle WHERE rule IS NULL AND angle IS NOT NULL;
    ALTER TABLE public.businesses DROP COLUMN angle;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'pending_customer_options') THEN
    UPDATE public.businesses SET pending_goal_options = pending_customer_options WHERE pending_goal_options IS NULL AND pending_customer_options IS NOT NULL;
    ALTER TABLE public.businesses DROP COLUMN pending_customer_options;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'pending_angle_options') THEN
    UPDATE public.businesses SET pending_rule_options = pending_angle_options WHERE pending_rule_options IS NULL AND pending_angle_options IS NOT NULL;
    ALTER TABLE public.businesses DROP COLUMN pending_angle_options;
  END IF;
END $$;

COMMENT ON COLUMN public.businesses.biz_stage IS 'Money stage: surviving | stretching | steady | building';
COMMENT ON COLUMN public.businesses.goal IS 'The goal(s) the person chose (GoalOption[])';
COMMENT ON COLUMN public.businesses.rule IS 'The one money rule they chose to live by (RuleOption[])';
COMMENT ON TABLE public.businesses IS 'One row per household (one WhatsApp number). Named businesses because Charles is built from Charlie; see db/0033.';
COMMENT ON TABLE public.business_map IS 'The Money Map: eight areas (income, spending, debt, cushion, credit_record, protection, family_money, goals), red/amber/green.';
COMMENT ON TABLE public.owner_notes IS 'What Charles remembers about the person, in their words.';


-- ============================================================================
-- 0034_charles_za_library.sql
-- ============================================================================

/*
# Charles — South Africa, the money library (apply AFTER 0033)

Data only, no schema change, safe to run more than once. It loads the
personal-finance knowledge base Charles runs on: 56 knowledge entries and
30 tools for South Africa (country 'ZA'), covering all eight areas of the
Money Map (income, spending, debt, cushion, credit_record, protection,
family_money, goals), as whole-row upserts keyed on id. Every id that
api/_lib/playbooks.ts pins (knowledge_ids, tool_choices) is here under exactly
that id. seed/knowledge.json and seed/tools.json carry the same rows; this
file is generated from them by scripts/seed-to-sql.mjs and must not be
hand-edited (regenerate it instead).

Charlie's business rows (k.deposits, yoco, …) are not touched by this file;
removing them is a separate, deliberate step for the founder once the Charles
rows are live (the two sets share no ids).

## How to apply — no SQL needed

  SUPABASE_URL=https://ybfqeaeujsbvdzcpuobe.supabase.co \
  SUPABASE_SERVICE_ROLE_KEY=<service role key> \
  node scripts/apply-knowledge.mjs \
    --knowledge k.sassa_grants_overview,k.sassa_deductions_rule,k.uif_claim,k.indigent_register,k.srd_grant,k.severance_pay,k.sars_refund_threshold,k.income_calendar,k.week_spend_log,k.three_pots_budget,k.bank_fees_audit,k.payshap_free_rule,k.layby_rights,k.debit_order_control,k.twenty_four_hour_rule,k.debt_list,k.debt_snowball,k.settled_account,k.mashonisa_law,k.debt_review_what_it_is,k.debt_counselling_vs_removal_scams,k.debt_collectors_rights,k.nca_caps_reckless,k.garnishee_order,k.prescribed_debt,k.no_new_credit,k.cushion_target,k.separate_money,k.payday_first,k.cushion_when_to_use,k.goalsave_rules,k.free_credit_report,k.dispute_credit_listing,k.credit_score_moves,k.paid_up_judgment_removal,k.debt_review_clearance,k.funeral_cover_rules,k.double_cover,k.beneficiary_nomination,k.sim_swap_signs,k.ponzi_signs,k.safps_protective_reg,k.family_line,k.stokvel_safety,k.burial_society_vs_policy,k.lending_to_family,k.pyramid_scheme_law,k.goal_vehicle,k.tfsa_rules,k.first_home_finance,k.two_pot_withdrawal,k.goal_monthly_number,k.partner_money,k.maintenance_claim,k.creditor_arrangement,k.prize_sms_scam \
    --tools bank_fraud_report,cdc_register,debicheck,experian_free_report,fsca_check,gotyme_everyday,gotyme_goalsave,municipal_indigent_register,nasasa_stokvel,ncr_complaint,ncr_debt_counsellor,nfo_complaint,nhfc_first_home_finance,notes_money_log,payshap,safps_protective_registration,saps_case,sars_efiling,sassa_office,sassa_srd_online,sheets_budget,tfsa_account,transunion_free_report,ufiling_uif,xds_free_report,ccma_referral,eskom_fbe_token,fund_two_pot_portal,legal_aid_sa,sassa_whatsapp

A bare id is a whole-row upsert; nothing here updates part of a row. Add
--dry first to see the request. The key is never printed. Or paste this file
into Supabase → SQL Editor.

## What is in it

Rights and rules a person can act on (the free annual credit report and the
20-business-day dispute, prescribed debt, debt review and its fees, the NCA
caps and reckless lending, mashonisa law, garnishee orders, the NFO and NCR
routes, SASSA grants and the 10% funeral-deduction rule, the SRD grant, UIF,
severance, two-pot, the tax-free savings limits, SARS thresholds, funeral
cover rules, stokvel safety, lay-by rights, scams, free basic electricity,
First Home Finance, the budgeting rules of thumb, the family line, the debt
snowball) and the places a step sends someone (GoTyme EveryDay and GoalSave,
PayShap, DebiCheck, the three bureaus' free reports, the NCR register and
line, the NFO, SAFPS, the FSCA check, SASSA online, office and WhatsApp,
uFiling, SARS eFiling, the fund's two-pot portal, a tax-free account, the
NHFC portal, the municipal indigent office, the Eskom token, the Council for
Debt Collectors, NASASA, the CCMA, Legal Aid SA, a notes-app log, a sheet).

Nothing in it recommends credit. `tools.informal_business_supported` keeps
Charlie's column name but now means "works without a payslip" (true: a
person with no formal job can use it; false: it needs an employer, a fund or
a home loan).

## Where the facts come from

Every row was written on 2026-10-30 from web searches; the build environment
could not open any official site directly (nfosa.co.za, sassa.gov.za,
sars.gov.za, transunion.co.za, safps.org.za, fsca.co.za, gotyme.co.za and
the rest all failed to resolve), so every figure was read from search-result
text of the named page. Where sources conflict (debt-review fee caps, grant
amounts, GoalSave tiers, PayShap fees, the SASSA WhatsApp number, the UIF
line) the row says "published figures differ" and names the place to confirm;
where nothing could be confirmed the figure was left out. verified_on is
2026-10-30 on every row. Sources and the verdict for every row are in
docs/kb-sources.md.
*/

