-- k.income_calendar (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.income_calendar',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['when does money come in', 'payday', 'pay day', 'grant day', 'grant payment dates', 'sassa payment dates', 'piece jobs', 'irregular income', 'my income changes', 'hustle money', 'cash jobs', 'side income', 'how much do i earn', 'i don''t know my income', 'income', 'salary date', 'paid late', 'paid weekly', 'paid on the 25th']::text[],
  'Know what comes in and on which day',
  'You cannot plan a month you cannot see. Write down every rand that comes in and the day it lands: salary, grants (SASSA publishes the payment dates each month, older persons first, then disability, then children''s grants), piece jobs, money from family. For income that changes, use the lowest month of the last 3 as your planning number, never the best one. The day money lands is the day every plan in this app starts: bills, the money put aside and the family amount all move on that day, before the month can eat it.',
  'you are not sure what you earn in a month, your income changes, or money comes from more than one place',
  'you get one fixed salary on one fixed day and already know the amount after deductions',
  ARRAY['Write one line per source of money: who pays, how much, and the day it lands (SASSA''s grant dates for the month are on sassa.gov.za and in the news on the first days of each month)', 'For piece jobs or hustle money, look at the last 3 months and write the lowest month; that is the number you plan on', 'Add them up: that is your month, after deductions, not before', 'Circle the biggest landing day; that becomes your payday for every rule in your plan', 'Keep this page next to your month plan and fix it whenever a source changes', 'Never plan on money that is promised but not yet in your hand; a loan or a ''maybe'' job is not income']::text[],
  'free',
  'medium',
  '2026-10-30'::date
)
