-- k.week_spend_log (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.week_spend_log',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['where my money goes', 'spending', 'track spending', 'spend log', 'write down spending', 'budget', 'money disappears', 'i don''t know where it goes', 'airtime', 'data', 'taxi fare', 'transport', 'groceries', 'small things add up', 'track expenses', 'expenses', 'money runs out', 'month is too long', 'mid-month', 'by the 20th', 'notes app', 'notebook']::text[],
  'Write down a week of spending, every rand',
  'Nobody knows where their money goes until they write it down for 7 days: every taxi, every R12 airtime, every loaf. The point is not to judge, it is to see. One line per spend in your phone''s notes app or a notebook: what and how much. At the end of the week add it up and circle the 3 biggest lines. Those 3 are where your month plan starts. Most people find one line they did not know was that big, usually airtime bought in small pieces, transport, or bank fees.',
  'you run out before the month ends and cannot say exactly where the money went',
  'you already keep a full record and the month plan fits; go straight to the month plan',
  ARRAY['Open the notes app on your phone (or take a small notebook) and make a page called ''Week 1''', 'Each time money leaves your hands, write one line the same day: ''taxi R18'', ''airtime R12'', ''bread R19''', 'Include the small things and the cash ones: airtime, data, electricity, a cooldrink, money given to a child', 'On day 7, add it all up and write the total at the bottom', 'Circle the 3 biggest lines; those are the lines your month plan has to deal with first', 'Before you change anything, do a second week: one week can be unusual, two weeks is a pattern']::text[],
  'free',
  'low',
  '2026-10-30'::date
)
