-- k.three_pots_budget (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.three_pots_budget',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['budget', 'how to budget', 'month plan', 'monthly budget', 'three pots', 'bills first', 'make the month fit', 'my money doesn''t last', 'money finishes', 'plan my salary', 'plan my grant', 'payday plan', 'envelope', 'spreadsheet budget', 'budget template', 'budget on low income', 'r3500 budget', 'needs and wants', 'money runs out before month end', 'prioritise bills', 'month is longer than the money', 'the month is longer', 'what do i do first', 'split my salary', 'when my salary comes in', 'divide my pay', 'when the money comes in']::text[],
  'The three pots: bills, aside, the rest',
  'A budget that works on a prepaid phone has three pots, decided on payday before anything is spent. Pot 1 is the bills and debts that must be paid, each with its date. Pot 2 is the money put aside: the cushion, and the family amount if there is one. Pot 3 is everything else: food, transport, airtime, electricity. Take pot 1 and pot 2 off the top on the day money lands; pot 3 is what is left, divided by the weeks until the next payday. If pot 1 alone is more than the money, do not invent savings; that is a debt problem, and the owed list comes first.',
  'money lands once or twice a month and runs out before the next payday',
  'the bills already exceed the income; then the owed list and the hardship steps come before any budget',
  ARRAY['Write what lands on payday at the top of a page, after deductions, using the lowest month if income changes', 'List pot 1 under it: rent, electricity, school, every debt minimum, each with the day it is due, and add them up', 'Write pot 2: the amount going to the cushion (GoalSave or a separate pocket) and the fixed family amount, moved on payday itself', 'Subtract pots 1 and 2 from the top number: what is left is pot 3, and divide it by the number of weeks to the next payday for a weekly food-and-transport number', 'Pay pot 1 and move pot 2 on the day money lands, then live on the weekly number', 'After 2 weeks, compare the plan with your spend log and fix the lines that did not fit; never fix a gap by borrowing']::text[],
  'free',
  'medium',
  '2026-10-30'::date
)
