-- k.bank_fees_audit (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.bank_fees_audit',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['bank fees', 'bank charges', 'fees', 'monthly fee', 'account fee', 'atm fee', 'withdrawal fee', 'cash withdrawal', 'declined debit order fee', 'unpaid debit order', 'bounced debit order', 'returned debit order', 'penalty fee', 'bank is taking my money', 'cheapest bank account', 'statement', 'read my statement', 'fees eat my money', 'airtime markup', 'cash at till', 'till withdrawal']::text[],
  'Find every fee on last month''s statement',
  'Bank fees are a bill nobody reads. Get last month''s statement in your banking app and add up every line that is a fee: monthly fee, ATM withdrawals, declined or ''unpaid'' debit orders, SMS notifications, cash deposits. A declined debit order is the one that hurts: the bank charges you for the failure and the company tries again. GoTyme''s published fee page lists R0 monthly, R3 for a declined debit order and cash out at a till, so confirm your own bank''s numbers in its app. The free versions of most things are: withdraw cash at a supermarket till, pay by PayShap to a cellphone number, and time debit orders for the day money lands.',
  'you pay a monthly account fee, draw cash at ATMs, or have had a debit order bounce',
  'you have no bank account and are paid in cash; the fee to look at then is the cost of carrying cash',
  ARRAY['Open your banking app, find last month''s statement, and write down every line that is a fee: monthly fee, ATM, declined debit order, SMS, deposit', 'Add them up: that total is what you paid last month just to use your own money', 'Circle the single biggest one; for most people it is either ATM withdrawals or a declined debit order fee', 'Replace that one habit this week: cash from the till at Pick n Pay, Boxer, Shoprite or Spar instead of the ATM, or PayShap instead of a branch EFT, or the debit order moved to the day after payday', 'Check your bank''s fee guide in the app for the exact numbers, and compare it with GoTyme''s published R0 monthly fee if you are thinking of moving', 'Never let a debit order bounce to ''save'' money: the fee plus the retry costs more than the payment']::text[],
  'free to check; fees differ by bank and account, for example GoTyme publishes a R0 monthly fee and R3 for a declined debit order, confirm yours in your bank''s app (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
