-- k.payshap_free_rule (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.payshap_free_rule',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['payshap', 'pay shap', 'shapid', 'shap id', 'instant payment', 'send money', 'send money to a cellphone', 'pay by cellphone number', 'eft fee', 'immediate payment fee', 'transfer fee', 'cheapest way to send money', 'send money to family', 'send money home', 'ewallet', 'e-wallet', 'cash send', 'money transfer', 'bank to bank', 'pay someone', 'small payments']::text[],
  'PayShap: send small amounts for free or nearly free',
  'PayShap sends money instantly to someone''s cellphone number (their ShapID) or account, and at most banks it is free or costs very little below R100, which is where most family and small payments sit. The fees differ by bank and change: TymeBank (now GoTyme) was reported as free at every amount, Nedbank and Capitec free or under R2 below R100, FNB and Standard Bank charging more above R100, so check your own bank''s fee guide. Compared with an ''immediate payment'' EFT, a cash-send voucher or a trip to deposit cash, it is the cheapest way to move money to a person. Pay in amounts under R100 where your bank''s free rule allows it.',
  'you send money to family, pay someone by cellphone number, or pay a fee every time you transfer',
  'the person you are paying has no bank account at all; a cash voucher or the till is the only route then',
  ARRAY['Open your banking app, find ''PayShap'' or ''Pay by cellphone number'', and register your own ShapID (your cellphone number linked to your account)', 'Ask the person you pay to register theirs; a ShapID payment is often cheaper than one to an account number at the same bank', 'Look up your bank''s PayShap fee in the app''s fee guide: many banks charge R0 under R100, and the per-transaction limit differs (R3,000 at some banks, higher at others)', 'Send a test of R10 to a family member and check it arrives instantly', 'Move your regular small payments to PayShap: family money, a stokvel contribution, a share of groceries', 'Never pay a stranger by PayShap for goods you have not seen; it is instant and cannot be reversed']::text[],
  'free at some banks, up to about R7.50 a payment at others, mostly free or near-free under R100; fees are set by each bank and change, so confirm in your bank''s fee guide (checked 2026-10-30)',
  'low',
  '2026-10-30'::date
)
