-- k.layby_rights (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.layby_rights',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['lay-by', 'layby', 'lay by', 'lay-bye', 'cancel lay-by', 'lay-by refund', 'cancellation fee', 'clothing account', 'store account', 'buy on account', 'instalments', 'account at the shop', 'pep lay-by', 'jet lay-by', 'ackermans', 'pay off before you take', 'consumer protection act', 'cpa', 'furniture account', 'hire purchase', 'buy on credit or save', 'credit or save up', 'save up or buy on account', 'should i save up']::text[],
  'Lay-by: the free way to buy on instalments',
  'A lay-by is the one instalment plan that costs no interest: you pay the shop in parts and take the goods when it is paid. Under section 62 of the Consumer Protection Act your money stays yours until you take the goods, and if you cancel or cannot finish, the shop must refund you less a cancellation charge of at most 1% of the full price, and nothing at all if you stopped paying because of death or hospitalisation. A store account or furniture ''credit'' is the opposite: interest, fees, and a listing on your credit record if you miss a payment. When you want something you cannot pay for today, lay-by first.',
  'you want to buy something over time, or you have a lay-by you cannot finish',
  'you need the item today; a lay-by only works when you can wait until it is paid',
  ARRAY['Ask the shop for a lay-by before you ask about an account: Pep, Ackermans, Jet and most furniture and clothing shops offer one', 'Get the agreement in writing: the full price, each instalment, the dates, and the cancellation charge (the law caps it at 1% of the full price)', 'Pay the instalments on payday from pot 1 and keep every receipt or SMS', 'If you cannot finish, cancel in writing and ask for your refund; the shop may keep at most 1% of the price, and nothing if the reason was death or hospital', 'If the shop refuses to refund, write to the National Consumer Commission or your provincial consumer office with the agreement and receipts; it is free', 'Never swap a lay-by for a store account to get the item sooner; the interest and the credit listing cost more than the wait']::text[],
  'free: no interest; a cancellation charge of at most 1% of the full price under Consumer Protection Act regulation 34 (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
