-- k.debit_order_control (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debit_order_control',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['debit order', 'debit orders', 'debicheck', 'stop debit order', 'cancel debit order', 'reverse debit order', 'dispute debit order', 'unknown debit order', 'debit order i did not sign', 'money taken from my account', 'debit order bounced', 'debit order went off early', 'debit order date', 'change debit order date', 'r99 debit order', 'mystery debit', 'strange debit', 'unauthorised debit']::text[],
  'Debit orders: approve them, time them, dispute the wrong ones',
  'A debit order is permission for a company to take money from your account. Since DebiCheck, a new one must be approved by you in your banking app, by USSD or by phone before the first collection, so never approve one you do not recognise. Time every debit order for the day after money lands, so nothing bounces. If a debit order you did not agree to goes off, you can dispute and reverse it in the app: from 13 April 2026 the window across all debit order types is 60 calendar days, and after that it is a complaint to the company and the ombud. A DebiCheck debit that matches what you approved is very hard to reverse, so check the amount and date before you tap approve.',
  'debit orders go off your account, one has bounced, or you see one you do not recognise',
  'you pay everything in cash or by manual transfer; there is nothing to dispute',
  ARRAY['Open your banking app and list every debit order on the account under ''Debit orders'' or ''DebiCheck''; write the company, amount and date for each', 'Move each date to the day after your money lands (ask the company; most change it by phone or app), so none bounce and you pay no declined fee', 'When a DebiCheck approval SMS arrives, check the company, amount and date against your list before you approve; decline anything you do not recognise', 'For a debit you never agreed to, dispute it in the app within 60 days of the debit (the rule since 13 April 2026); the bank reverses it and the company must prove you consented', 'Phone the company and cancel the agreement in writing the same day, or the debit returns next month', 'If the company keeps debiting, complain free to the National Financial Ombud on 0860 800 900; never close the account to escape a debit order, it follows you as a debt']::text[],
  'free to approve, move or dispute; the dispute window is 60 calendar days from 13 April 2026 (PASA rule change, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
