-- k.twenty_four_hour_rule (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.twenty_four_hour_rule',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['impulse', 'impulse buying', 'spent it all', 'i waste money', 'wasteful', 'can''t stop spending', 'temptation', 'payday weekend', 'month end spending', 'sales', 'black friday', 'shopping', 'specials', 'i buy things i don''t need', 'self control', 'discipline', '24 hour rule', 'wait before buying', 'want vs need']::text[],
  'The 24-hour rule for anything you did not plan',
  'One rule stops most wasted money: anything that is not in the month plan waits 24 hours before you buy it. Not forever, just one night. Write it on a ''waiting'' list in your notes app with the price. Most of the time the want fades by morning; when it does not, you buy it from pot 3 knowing what it replaces. The rule is strongest on payday weekend and at month-end specials, which is exactly when most unplanned money goes. It costs nothing and it is the single habit people who make the month fit have in common.',
  'money goes on things you did not plan, especially around payday or specials',
  'the month plan has no room for anything unplanned at all; then the plan itself needs fixing, not the rule',
  ARRAY['Make a page in your notes app called ''Waiting'' and put the date next to it', 'When you want something that is not in the plan, write it there with the price instead of buying it', 'Wait 24 hours; do not go back to the shop or the link in that time', 'The next day, decide: if you still want it and pot 3 can carry it, buy it; if not, cross it out', 'On payday weekend and during specials like Black Friday, apply the rule to everything over the price of a loaf of bread', 'Once a month, read the crossed-out lines and add up what you did not spend; that number is why the rule works']::text[],
  'free',
  'low',
  '2026-10-30'::date
)
