-- k.debt_list (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debt_list',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['debt', 'debts', 'owe', 'owe money', 'who do i owe', 'list my debts', 'how much do i owe', 'repayments', 'repayments eat my pay', 'too many debts', 'drowning in debt', 'loan', 'loans', 'store account', 'clothing account', 'cellphone contract', 'mashonisa', 'interest rate', 'what does my loan cost', 'statement', 'balance', 'settlement balance', 'i don''t know how much i owe', 'debt overview']::text[],
  'Write down everyone you owe, and what each one costs',
  'You cannot pay down what you cannot see, and most people are paying whoever shouts loudest while the most expensive debt grows quietly. One list changes that: who, how much is left, what you pay a month, and the interest or fee. The cost is the column that matters: a mashonisa charging 30% to 50% a month goes to the top even if the amount is small, a store account next, a bank loan after. Ask each lender for a settlement balance; under the National Credit Act they must give it to you free. Then add up what goes out to all of them in a month. That number is the start of every debt plan.',
  'you owe money to more than one place, or you are not sure what you owe in total',
  'you owe nobody; then the list is the cushion and the month plan',
  ARRAY['Go through your SMSes, statements, the papers in the drawer and your banking app''s debit orders, and write one line for every debt: bank, store account, cellphone contract, mashonisa, stokvel, family', 'Write 4 columns for each: how much is left, what you pay a month, the interest or fee, and the day it is due', 'Phone or message each lender for a settlement balance and the interest rate; the National Credit Act says they must give you a statement free of charge', 'Put the most expensive at the top: a mashonisa (often 30% to 50% a month) first, then store accounts, then bank loans, whatever the amounts', 'Add up the monthly payments: that total against your income tells you whether this is a snowball job or a debt review job', 'Keep the list where you see it on payday and update the balances every month; never add a new line to it']::text[],
  'free; a lender must give you a statement of your account free of charge under the National Credit Act; mashonisa interest is commonly reported at 30% to 50% a month (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
