-- k.debt_snowball (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debt_snowball',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['snowball', 'debt snowball', 'which debt to pay first', 'pay off debt', 'pay off debt fast', 'get out of debt', 'smallest debt first', 'highest interest first', 'avalanche', 'extra payment', 'pay more on my loan', 'how to pay off loans', 'payment arrangement', 'arrangement with creditor', 'can''t pay all my debts', 'minimum payment', 'settle my accounts', 'debt free', 'clear my debts', 'consolidation', 'consolidate my debt']::text[],
  'Kill the smallest debt first: the snowball',
  'Pay the minimum on every debt, on time, and send everything spare to one debt until it is gone: the mashonisa if there is one, otherwise the smallest balance. When it dies, add its whole payment to the next one. A study of about 6,000 people in debt programmes (Gal and McShane, Journal of Marketing Research 2012) found that closing accounts, however small, was the best predictor of clearing all the debt: the first win keeps you going. Highest-interest-first is better arithmetic, but most people quit it. Never take a ''consolidation loan'' to do this; it is new credit with new fees, and the old habit comes back on top of it.',
  'you owe two or more debts and can cover all the minimums from your income',
  'the minimums alone are more than the money; then debt review, not the snowball, is the route',
  ARRAY['Take your owed list and write the balances in order, smallest at the top; a mashonisa goes to the very top whatever its size', 'Write the minimum payment next to each one, and circle the top one', 'On payday, pay every minimum first, in the order of the due dates, so nothing bounces', 'Send everything spare, even R50, to the circled debt the same day; do not touch the order when another one feels more urgent', 'For any lender you cannot pay in full, send one calm message with the amount and day you can pay: ''I can pay R300 on the 26th of each month until the balance is settled. Please confirm.'' Keep the reply', 'When the top debt is paid, get the paid-up letter, cancel any insurance tied to it, and add its whole payment to the next one; never borrow to pay a debt']::text[],
  'free; the evidence is Gal and McShane 2012, about 6,000 people, closing small accounts first predicted paying everything off (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
