-- k.settled_account (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.settled_account',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['paid up letter', 'paid-up letter', 'settlement letter', 'settled', 'settle my account', 'close my account', 'account paid but still showing', 'paid but still listed', 'still on my credit report', 'credit life', 'credit life insurance', 'cancel insurance on loan', 'settle early', 'early settlement', 'closing a store account', 'finished paying', 'last payment', 'balance zero', 'account closed']::text[],
  'When a debt is paid: the letter, the insurance, the record',
  'Paying the last instalment is not the end; three things make it stick. Ask the lender for a paid-up or settlement letter and keep it forever: it is your proof. Cancel any credit life insurance or ''account protection'' tied to that account; under section 106 of the National Credit Act, if you paid the premium yearly you are owed the unused part back on settlement. Then check your credit report a month later: the account should show as settled, and a paid-up judgment must be removed by the bureau within 7 days of proof of payment under the 2014 regulations. If it still shows as owing, dispute it free with the bureau, letter attached.',
  'you have just made the last payment on a debt, or a paid account still shows as owing',
  'the account is still open with a balance; this comes after the last instalment',
  ARRAY['Ask the lender, in writing, for a paid-up or settlement letter showing a zero balance and the date; message or email so you have a copy', 'Check your bank app for any debit order still linked to that account (an insurance premium, a monthly fee) and cancel it with the company', 'Ask whether credit life insurance was charged on the loan; if you paid it yearly, section 106 of the National Credit Act gives you a refund of the unused part', 'Add the whole payment you were making to the next debt on your list the same payday', 'A month later, pull your free credit report and check the account shows ''settled'' or ''closed''; a paid-up judgment must come off within 7 days of the bureau receiving proof', 'If it still shows as owing, lodge a dispute with the bureau with the letter attached; it is free and they have 20 business days; never pay a company to ''clear'' it']::text[],
  'free: the letter, the dispute and the bureau update cost nothing; a paid-up judgment must be removed within 7 days of proof of payment (NCA regulations 2014, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
