-- k.mashonisa_law (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.mashonisa_law',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['mashonisa', 'umashonisa', 'loan shark', 'loan sharks', 'skoppers', 'informal lender', 'money lender', 'unregistered lender', 'they have my card', 'took my sassa card', 'keeping my id', 'holding my bank card', 'they know my pin', '30 percent a month', '50 percent interest', 'threatened', 'threats', 'intimidation', 'borrow from a mashonisa', 'cash loan in the township', 'quick cash', 'payday loan', 'pay back double']::text[],
  'What a mashonisa can and cannot do to you',
  'Since 11 November 2016 anyone who lends money for interest must be registered with the National Credit Regulator, whatever the amount. A loan from an unregistered lender is an unlawful agreement under the National Credit Act, which means a court can declare it void and the lender cannot enforce it or its interest; and the NCR says holding your bank card, SASSA card, ID or PIN as security is a criminal offence. None of that makes the person go away, so the plan is quiet: pay a fixed amount on a fixed day, get your card and ID back, borrow nothing new, and report threats to the police. Report the lender to the NCR on 0860 627 627; it is free and they act on unregistered lenders.',
  'you owe a mashonisa, or one is holding your card, ID or PIN',
  'the lender is registered with the NCR (ask for the NCRCP number and check it on ncr.org.za); then the normal NCA rules and caps apply',
  ARRAY['Ask the lender for their NCR registration number (it starts NCRCP) and check it on ncr.org.za or by phoning 0860 627 627; no number means the agreement is unlawful under the National Credit Act', 'Write down what you borrowed, what you have paid so far and what they say you still owe; most people have already paid back more than they borrowed', 'If they hold your bank card, SASSA card, ID or PIN, ask once for it back; if they refuse, report it at the police station and to the NCR, because the NCR says holding it is a criminal offence', 'The moment the card is back, change the PIN in your banking app or at the bank, and check the account for withdrawals you did not make', 'Pay a fixed amount on a fixed day in a way that leaves a record (PayShap or a deposit slip), ask for the balance each time, and say no to any new loan', 'Never hand over a card, ID or PIN to anyone again, and report threats or intimidation to SAPS on 10111']::text[],
  'free to report; registration threshold for lenders is R0 since 11 November 2016 (Government Notice 513 of 2016), so every lender must be registered with the NCR (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
