-- k.debt_review_what_it_is (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debt_review_what_it_is',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching']::text[],
  ARRAY['debt review', 'debt counselling', 'debt counsellor', 'over-indebted', 'over indebted', 'can''t afford my repayments', 'repayments more than my salary', 'nca section 86', 'form 16 debt review', 'form 17.1 notice', 'debt review cost', 'how much is debt review', 'debt review fees', 'what does debt review do', 'should i go under debt review', 'debt review pros and cons', 'clearance certificate', 'legal protection from creditors', 'stop the calls', 'creditors calling', 'debt relief', 'debt rescue', 'ncr debt review']::text[],
  'Debt review: what it does, what it costs, what it stops',
  'Debt review (section 86 of the National Credit Act) is a legal process for people whose repayments are more than they can pay. A registered debt counsellor tells your creditors, they must stop legal action while it runs, your payments are restructured into one lower amount, and when you finish you get a clearance certificate and the record is cleared. The catch: you cannot take any new credit while under review, and it costs money: an application fee of R50 and a restructuring fee that the NCR caps, with published figures of R8,000 (R9,000 if married in community of property) and an aftercare fee of 5% of the monthly payment capped at R400 or R450 depending on the source, so confirm the fee guideline on ncr.org.za before you sign. Most people who need it never use it, and many pay a scam for a worse version.',
  'your debt minimums are more than your income can carry, and lenders are threatening legal action',
  'you can cover every minimum from your income; then the snowball clears it without fees or a listing',
  ARRAY['Add up every monthly minimum on your owed list and compare it with your income after rent, food and transport; if the minimums do not fit, debt review is built for you', 'Read the cost before anything: R50 application fee, a restructuring fee capped by the NCR (published figures differ, R8,000 to R9,000, confirm on ncr.org.za), and a monthly aftercare fee of 5% of your payment with a cap', 'Understand the one thing it stops: no new credit of any kind until the clearance certificate, which for most people is the point', 'Find a counsellor registered with the NCR (the number starts NCRDC) and check it on ncr.org.za or on 0860 627 627; walk away from anyone who cannot show it', 'Sign Form 16 only after you have seen the fees in writing; within 5 business days the counsellor must send Form 17.1 to every creditor, and your payments then go through a registered payment distribution agent', 'Keep paying the restructured amount every month without fail; when the plan is done, the counsellor must issue the clearance certificate (Form 19) within 7 days, and never pay anyone extra to ''remove'' you from review']::text[],
  'application fee R50; restructuring fee capped by the NCR, published figures differ (R8,000, R9,000 for couples in community of property); aftercare 5% of the monthly payment capped at R400 or R450 depending on the source; confirm on ncr.org.za (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
