-- k.debt_counselling_vs_removal_scams (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debt_counselling_vs_removal_scams',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['debt removal', 'remove my name', 'clear my name', 'credit clearance', 'credit repair', 'blacklisting removal', 'remove blacklisting', 'remove debt review', 'debt review removal', 'credit fixer', 'fix my credit for a fee', 'pay to clear my record', 'scam', 'fake debt counsellor', 'is this company legit', 'ncrdc', 'check debt counsellor', 'debt counsellor registered', 'whatsapp debt help', 'guaranteed clearance', 'itc clearance', 'remove my bad credit', 'remove bad credit for a fee', 'clear my name for a fee', 'credit removal company']::text[],
  'Registered counsellor or removal scam: how to tell',
  'There is no such thing as paying to have a true listing removed. Companies selling ''credit clearance'', ''blacklisting removal'' or ''debt review removal'' for a fee are selling what the law already gives you free: a dispute with the bureau, a paid-up letter, a prescription defence, or a clearance certificate from your own counsellor. The NCR has warned (Circular 1 of 2024) about people using registered counsellors'' numbers without permission, so the number alone is not enough; the name must match on the register. A real debt counsellor has an NCRDC number on ncr.org.za, puts fees in writing before Form 16, and never takes your payments into their own account.',
  'someone offers to clear your record, remove debt review or fix your credit for a fee',
  'you are dealing with a counsellor whose NCRDC number and name you have already checked on ncr.org.za',
  ARRAY['Ask for the NCRDC number in writing and check both the number and the name on the NCR register at ncr.org.za, or phone 0860 627 627; a CIPC company number is not registration', 'Refuse anyone who promises a ''guaranteed'' clearance, asks for an upfront fee to remove a listing, or contacts you first on WhatsApp or Facebook', 'Ask the first-call questions: what are your fees in rand, who is the payment distribution agent, and how long until the court order; a real counsellor answers all three', 'Do for free what they charge for: dispute a wrong listing with the bureau (section 72), get the paid-up letter from the lender, or ask your counsellor for the clearance certificate (section 71)', 'If you already paid a removal company, stop further payments, keep the proof, and report them to the NCR on complaints@ncr.org.za', 'Never give anyone your banking login, OTP or ID copy to ''check your profile''; that is how the scam becomes identity theft']::text[],
  'free: disputes, paid-up letters, prescription and clearance certificates cost nothing; the NCR complaint line is 0860 627 627 (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
