-- k.debt_collectors_rights (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debt_collectors_rights',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['debt collector', 'debt collectors', 'collector calling', 'harassing calls', 'harassment', 'calls at work', 'threatening sms', 'collection agency', 'attorney letter', 'letter of demand', 'summons', 'they said they will take my furniture', 'sheriff', 'collector fees', 'collection fees', 'tracing fees', 'council for debt collectors', 'cfdc', 'complaint against collector', 'stop calling me', 'phoning my family', 'rights against collectors']::text[],
  'Your rights when a debt collector calls',
  'A debt collector must be registered with the Council for Debt Collectors; collecting without registration is a criminal offence under the Debt Collectors Act. They may ask you to pay; they may not threaten you, pretend to be a sheriff or a court, phone your employer or family about your debt, or add fees beyond the regulated tariff. Nobody can take your furniture without a court order served by a sheriff. Ask for the collector''s registration number and the written breakdown of the debt, pay only what you agreed in writing, and complain free to the Council on 012 804 9808 or info@cfdc.org.za if they break the rules. If the debt is older than 3 years with no payment, do not acknowledge it before checking prescription.',
  'a collector, attorney or ''tracing agent'' is phoning, messaging or sending letters about a debt',
  'you have a court order against you; then the route is the court or a registered debt counsellor, not the Council',
  ARRAY['Ask the caller for their name, the company, their Council for Debt Collectors registration number, and a written statement of the debt; a registered collector has all four', 'Check the number on the Council''s register at cfdc.org.za or by phoning 012 804 9808; an unregistered collector is committing a crime and you need not deal with them', 'Check the date of the last payment on the debt: if more than 3 years ago with no acknowledgment, say nothing about owing it and read the prescribed-debt rules first', 'Pay only what you can, in writing: ''I can pay R200 on the 27th of each month. Confirm in writing and I will start.'' Pay by a route that leaves a record', 'Keep a log of every call: date, time, name, what was said; threats, calls to your employer or family, or fake court documents go into a sworn complaint to the Council', 'Never pay cash to someone at your door and never give your card details over the phone; a collector is paid into the creditor''s or their own registered account']::text[],
  'free to check the register and to complain; collector fees are set by the regulated tariff under the Debt Collectors Act, so ask for the breakdown (Council for Debt Collectors FAQ, checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
