-- k.nca_caps_reckless (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.nca_caps_reckless',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['interest rate', 'maximum interest', 'interest cap', 'how much interest can they charge', 'too much interest', 'initiation fee', 'service fee', 'r69 service fee', 'reckless lending', 'reckless credit', 'they gave me a loan i couldn''t afford', 'affordability assessment', 'national credit act', 'nca', 'short term loan', 'short-term loan interest', '5% per month', 'unsecured loan rate', 'repo rate plus 21', 'complain about interest', 'credit agreement unfair', 'set aside loan']::text[],
  'The interest caps, and what reckless lending means',
  'The National Credit Act caps what a registered lender may charge. The published caps are: short-term credit (up to R8,000, repayable within 6 months) 5% a month on the first loan and 3% a month on another in the same year; unsecured loans the repo rate plus 21% a year; plus a capped initiation fee and a monthly service fee. A 2016 court case over the short-term caps was appealed, so confirm the current figures with the NCR. A lender must also check you can afford the loan before granting it (section 81); credit given without that check, or that you plainly could not afford, is reckless credit, and a court can set aside or suspend what you owe. This is a shield, not a reason to borrow: the caps still make small loans the most expensive money in the country.',
  'you are being charged interest or fees that look wrong, or you were given credit you could never afford',
  'the lender is a mashonisa with no NCR number; then the whole agreement is unlawful, which is the stronger rule',
  ARRAY['Read your credit agreement for three lines: the interest rate, the initiation fee and the monthly service fee; the lender must have given you a copy', 'Compare the rate with the caps: 5% a month (3% on a repeat loan in the same year) for short-term credit up to R8,000, and the repo rate plus 21% a year for unsecured loans; confirm the current numbers with the NCR on 0860 627 627', 'If the rate or fees are above the cap, write to the lender quoting the agreement and ask for the overcharge to be reversed; give them 20 business days', 'If a lender gave you credit without asking for payslips, bank statements or your other debts, or the instalment was more than you could ever pay, that is reckless credit under section 80; say so in writing', 'Lodge a free complaint with the NCR (form 29 on ncr.org.za, complaints@ncr.org.za) or with the National Financial Ombud on 0860 800 900 with the agreement and statements attached', 'Never take a new loan because the rate is ''within the cap''; the cap is the ceiling, not a good price']::text[],
  'free to complain; published caps are 5% a month (3% on a repeat loan) for short-term credit up to R8,000 and repo rate plus 21% a year for unsecured credit, under NCA regulation 42, with a 2016 court challenge to the short-term caps, so confirm with the NCR (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
