-- k.garnishee_order (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.garnishee_order',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['garnishee', 'garnishee order', 'emolument attachment', 'emoluments attachment order', 'eao', 'salary deduction for debt', 'money taken off my salary', 'employer deducting for a loan', '25 percent of salary', 'court order on my salary', 'payroll deduction', 'they are taking from my pay', 'stop garnishee', 'garnishee without court', 'clerk of the court', 'magistrate', 'judgment against me', 'my salary is garnished']::text[],
  'A garnishee on your salary: what is legal',
  'An emoluments attachment order (what people call a garnishee) lets a creditor take debt payments straight from your salary, but only if a magistrate''s court granted it after deciding it is just and equitable; a clerk''s stamp alone is not enough since the Constitutional Court''s 2016 ruling and the 2017 law change. The total of all such orders may not exceed 25% of your basic salary. If more than that is coming off, or you never saw a court, your employer''s payroll must show you the order and you can apply to the same court to have it set aside or reduced. Legal Aid South Africa helps with this free if you earn under its means test.',
  'money for a debt is being deducted from your salary, or a lender is threatening to ''garnish'' you',
  'the deduction is one you signed for yourself, like a payroll loan or a debit order; that is cancelled with the lender, not the court',
  ARRAY['Ask your payroll or HR for a copy of the court order behind the deduction; they must have one, and it must be issued by a magistrate''s court, not just signed by a clerk', 'Check two things on it: the court''s name and the amount; if the total of all orders is more than 25% of your basic salary, it is above the legal cap', 'Write down what has been deducted so far from your payslips and compare it with the debt balance; orders sometimes run long after the debt is paid', 'If there is no proper court order, or it exceeds 25%, apply at that magistrate''s court to set it aside or reduce it; the clerk of the civil court gives you the form', 'Phone Legal Aid South Africa''s advice line or send a ''Please Call Me'' to 079 835 7179; it is free if your income is under their means test (R9,400 a month for a single person from April 2026)', 'Never agree to a ''voluntary'' salary deduction a lender puts in front of you to avoid court; it has none of the court''s protections']::text[],
  'free to challenge through Legal Aid SA if you qualify; the legal cap is 25% of basic salary across all orders (Magistrates'' Courts Act section 65J, checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
