-- k.prescribed_debt (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.prescribed_debt',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['prescribed debt', 'prescription', 'old debt', 'debt older than 3 years', 'three years', 'they want money from 2019', 'debt from years ago', 'written off', 'does debt expire', 'expired debt', 'collector for an old account', 'acknowledge debt', 'admit the debt', 'old cellphone contract', 'old account', 'section 126b', 'debt has prescribed', 'can they still collect', 'time barred', 'must i pay', 'do i have to pay', 'still owe', 'years ago', 'account from years ago', 'old account they want money', 'want money for an old account']::text[],
  'Prescribed debt: after 3 years of silence, say nothing',
  'Most ordinary debts (store accounts, cellphone contracts, personal loans, credit cards) prescribe after 3 years with no payment, no written acknowledgment and no summons. Section 126B of the National Credit Act, since March 2015, bars a creditor from collecting, selling or reactivating a prescribed credit-agreement debt. The trap is simple: if you acknowledge the debt in any way, by paying R10, by saying ''yes that''s mine'' on the phone, or by signing anything, the 3 years start again. So when a collector calls about an old account, ask for the date of the last payment in writing, and say nothing about owing it until you have checked. Home loans and SARS debts prescribe much later.',
  'a collector or lender contacts you about a debt you have not paid or heard about for 3 years or more',
  'you paid, acknowledged or were served a summons within the last 3 years, or the debt is a home loan, a court judgment or tax',
  ARRAY['Say only: ''Please send me the account details and the date of the last payment in writing.'' Do not confirm the debt is yours on the phone', 'Check the last payment date on your own statements or your credit report; if it is more than 3 years ago with no summons and nothing signed, the debt has probably prescribed', 'Write back: ''This debt has prescribed under the Prescription Act and section 126B of the National Credit Act. I do not acknowledge it. Please stop collection.'' Keep a copy', 'If it is still on your credit report, dispute it with the bureau as prescribed; the bureau has 20 business days and it is free', 'If the collector keeps going, complain to the NCR on 0860 627 627 or the National Financial Ombud on 0860 800 900 with your letter attached', 'Never pay ''just a little to make them stop'' or sign an acknowledgment of debt on an old account; one payment restarts the 3 years']::text[],
  'free; ordinary debt prescribes after 3 years without payment, acknowledgment or summons (Prescription Act; NCA section 126B since March 2015), home loans and judgments much later (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
