-- k.no_new_credit (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.no_new_credit',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['consolidation loan', 'debt consolidation', 'borrow to pay debt', 'new loan to pay old loan', 'balance transfer', 'cash advance', 'overdraft', 'credit card to pay', 'buy now pay later', 'bnpl', 'payflex', 'mobicred', 'revolving loan', 'top up loan', 'should i take a loan', 'loan to fix my debt', 'quick loan', 'instant loan app', 'borrowing again', 'more credit', 'another loan']::text[],
  'Why a new loan never fixes old debt',
  'A consolidation loan, a top-up, an overdraft, a credit card or a buy-now-pay-later plan all do the same thing: they add an initiation fee, a monthly service fee and interest to money you already owe, and they free up the old limits so the same habit fills them again. The National Credit Regulator''s figures show more than a third of credit-active South Africans already behind; most got there one ''small'' loan at a time. The rule in this plan is fixed: nothing new borrowed from anyone while the owed list exists. If the minimums truly do not fit, debt review is the legal route and costs less than another loan. If someone offers you credit, say the one line: ''Not while I am paying this off.''',
  'you are tempted by a consolidation loan, top-up, overdraft, credit card or buy-now-pay-later while you still owe money',
  'you owe nobody and are not considering credit; nothing to decide',
  ARRAY['Write down the full cost of the loan being offered, from its pre-agreement quote, which the lender must give you: initiation fee, monthly service fee, interest rate and the total you repay', 'Compare the total repayable with what you owe now; a consolidation that ''lowers the instalment'' almost always raises the total and the years', 'Ask what happens to the old accounts: if they stay open, the limit is there to be used again, which is how the debt doubles', 'Say the one line to any offer, including a bank''s app notification: ''Not while I am paying this off.'' Tap ''not interested'' and move on', 'If your minimums really do not fit your income, read the debt review entry; it is the legal version of what a consolidation loan pretends to be, with no new interest', 'Never take a loan from an app or a WhatsApp number; those are the most expensive and the least regulated']::text[],
  'free to refuse; a new loan adds an initiation fee, a monthly service fee and interest on top of what you owe, and the NCR reports more than 10 million credit-active consumers with impaired records (NCR June 2025, checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
