-- k.cushion_target (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.cushion_target',
  'ZA',
  'cushion',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['emergency fund', 'emergency savings', 'cushion', 'rainy day', 'savings target', 'how much should i save', 'nothing saved', 'no savings at all', 'something saved', 'start saving', 'save on low income', 'cannot save money', 'savings goal', 'first r500', 'r1000 saved', 'three months expenses', 'unexpected costs', 'surprise expenses', 'funeral costs', 'school fees', 'broke my phone', 'what if something breaks', 'emergencies', 'saved for emergencies', 'for emergencies', 'how much should i have saved', 'enough saved', 'how much should i be saving', 'save each month', 'how much to save', 'worth saving when i owe', 'save or pay debt', 'save while in debt']::text[],
  'Name the number: your first cushion target',
  'Every mashonisa loan starts with a surprise: a funeral contribution, a school letter, a broken phone, a taxi fare to a clinic. A cushion is a named amount you can reach that turns the next surprise into a nuisance. Pick the first target from your own life, not from a rule: the cost of the last surprise, or one week of your essentials from the month plan. For most people that is a few hundred rand, and it is meant to be small; the person who cannot make one month does not need ''three months of salary'' as a target, they need R500 they can reach. Write the number where you see it on payday. When you reach it, name the next one.',
  'you have nothing saved, or less than a week''s spending you can reach',
  'you already have more than a month''s essentials saved; then the goal entry applies',
  ARRAY['Write down the last 3 surprises that cost you money and what each one cost (the funeral contribution, the school shoes, the phone screen)', 'Pick the smallest of them, or one week of food and transport from your month plan, as the first target; round it to a number you can say, like R500', 'Write the number at the top of your month plan and in your notes app: ''Cushion: R500''', 'Open a separate place for it (a GoalSave or a savings pocket at your bank) so the everyday money cannot quietly eat it', 'Move the first amount today, however small, and set the rest to move on payday', 'When you reach the target, do not spend it on something planned; name the next number, and only use it for a real surprise']::text[],
  'free',
  'medium',
  '2026-10-30'::date
)
