-- k.separate_money (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.separate_money',
  'ZA',
  'cushion',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['separate account', 'savings account', 'savings pocket', 'goalsave', 'where to keep savings', 'keep savings separate', 'i spend my savings', 'savings disappear', 'out of sight', 'lock my savings', 'notice account', 'fixed deposit', 'stokvel for saving', 'cash under the mattress', 'where to save money', 'best savings account', 'high interest savings', 'open a savings account', 'keep money away from myself']::text[],
  'Keep the cushion where the month cannot reach it',
  'Savings in the same account as the groceries are not savings; they are next week''s groceries. The fix is physical separation, which is what the rule-of-thumb research (Drexler, Fischer and Schoar 2014) found worked better than any training: a different pocket, a different account, a name on it. Most banks give you a free savings pocket inside the app: GoTyme''s GoalSave pays interest from day 1 and more if you give 10 days'' notice before taking it out, which is a useful speed bump. Interest is a bonus; the point is that you have to decide to take it out, instead of it going without you noticing.',
  'your savings keep getting spent because they sit with your everyday money',
  'you have no bank account and no safe place at all; then a registered stokvel or burial society with written rules is the separate place',
  ARRAY['Open your banking app and look for ''GoalSave'', ''savings pocket'', ''flexi savings'' or ''notice savings''; at most banks it is free to open', 'Name it for what it is for (''Cushion'') so you see the purpose every time you open the app', 'Move the first amount today, even R20, so the pocket exists before payday', 'If the bank offers a notice option (GoTyme''s GoalSave pays more for 10 days'' notice), choose it; the delay is the protection', 'Keep no card linked to the pocket and do not add it to your tap-to-pay; money that needs a transfer back is money you think about', 'Never keep the cushion as cash at home or on a card someone else holds; if you must use cash, a sealed envelope with a date on it is the minimum']::text[],
  'free: a savings pocket at your own bank costs nothing to open; GoTyme publishes 6% a year on GoalSave rising to 10% with 10 days'' notice, confirm the current rates in the app (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
