-- k.payday_first (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.payday_first',
  'ZA',
  'cushion',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['pay yourself first', 'payday', 'save on payday', 'automatic saving', 'automatic transfer', 'scheduled transfer', 'recurring transfer', 'standing order', 'save before i spend', 'nothing left to save', 'save at month end', 'end of month nothing left', 'saving habit', 'auto save', 'round up', 'save r50 a month', 'save from my grant', 'grant day saving', 'save every month', 'debit order to savings']::text[],
  'Move it on payday, before you see it',
  'Saving what is left at the end of the month saves nothing, because nothing is left. Saving on the day money lands, before the first spend, works because the decision is made once and the month adjusts around it. Set a recurring transfer in your banking app from your main account to the cushion for the day after payday: R50 on a grant, R200 on a salary, whatever the month plan says. The amount matters less than the day. In a month it truly cannot be afforded, pause the transfer for that month; never borrow to keep it going, and never cancel it altogether.',
  'you mean to save but there is never anything left by the time you try',
  'your income is cash with no bank account; then the rule is the same but by hand: the first notes go into the envelope before anything is bought',
  ARRAY['Decide the amount from your month plan, pot 2, and round it to a number that feels easy; the day is what matters', 'Open your banking app, choose the cushion pocket (GoalSave or your bank''s savings pocket) and set a recurring transfer for the day after your money lands', 'Set a reminder on your phone for that day for the first 2 months, to check it moved', 'When income is a grant, set it for the grant date; when it is piece jobs, move it by hand the day you are paid, before you buy anything', 'In a month that is short, pause that month''s transfer in the app; do not cancel the schedule, and do not borrow to cover it', 'After 3 paydays, raise it a little if the month fit, and never lower it just because the balance looks big']::text[],
  'free: a recurring transfer inside your own bank''s app costs nothing at most banks, check the fee guide (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
