-- k.cushion_when_to_use (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.cushion_when_to_use',
  'ZA',
  'cushion',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['when to use savings', 'use my emergency fund', 'is this an emergency', 'dip into savings', 'spent my savings', 'refill savings', 'rebuild emergency fund', 'savings for a funeral', 'savings for school', 'emergency vs want', 'borrow or use savings', 'should i use my savings', 'savings rule', 'what counts as emergency', 'broke my phone', 'car repair', 'medical emergency', 'family emergency', 'taxi to hospital']::text[],
  'What the cushion is for, and how to refill it',
  'The cushion has one job: to stop a surprise from becoming a loan. So the test for using it is simple: would you otherwise borrow for this? A funeral contribution, a clinic trip, a school letter, a broken stove: yes. A sale, a birthday, a new phone when the old one works: no, that goes on the waiting list. When you do use it, that is the cushion doing its job, not a failure. The week after, write the new balance, restart the payday transfer, and add anything you can until the number is back. Using it and refilling it a few times a year is exactly what a cushion is for.',
  'something has come up and you are deciding whether to use your savings or borrow',
  'you have no cushion yet; then the question is the first target',
  ARRAY['Ask the one question: ''If I did not have this money, would I borrow for this?'' If yes, it is what the cushion is for; if no, it waits 24 hours on the waiting list', 'Take only what the surprise costs, not the whole pocket, and move it the day you need it', 'Write the new balance in your notes app with the date and what it was for', 'Restart the payday transfer the next payday; if you paused it for the surprise, unpause it', 'Add any extra that month (a refund, a small job) straight to the pocket until the number is back', 'Never borrow to ''protect'' the cushion: paying 5% a month interest to keep R500 untouched costs more than using it']::text[],
  'free',
  'medium',
  '2026-10-30'::date
)
