-- k.goalsave_rules (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.goalsave_rules',
  'ZA',
  'cushion',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['goalsave', 'goal save', 'gotyme', 'go tyme', 'tymebank', 'tyme bank', 'gotyme interest', '10 percent interest', 'notice', '10 days notice', 'how does goalsave work', 'goalsave withdrawal', 'how many goalsaves', 'goalsave limit', 'gotyme savings', 'tymebank savings', 'gotyme app', 'open goalsave', 'kiosk', 'pick n pay kiosk', 'boxer kiosk']::text[],
  'GoalSave at GoTyme: how the pockets work',
  'GoalSave is the savings pocket inside the GoTyme Bank app (the bank was TymeBank until January 2026). On its own GoalSave page GoTyme describes interest of 6% a year from day one and a bonus taking it to 10% a year if you give 10 days'' notice before closing, with up to 20 GoalSaves and a combined cap of R250,000; third-party reviews describe a different ladder (4% rising to 6% after 90 days, then 10% with notice), so the exact tiers must be confirmed in the app before you count on them. There is no fee to open one. For a cushion, the notice option is the useful part: 10 days is long enough to stop a want and short enough for a real emergency.',
  'you bank with GoTyme or are opening an account there and want a separate place for savings',
  'you bank elsewhere; use your own bank''s savings pocket, the rule of separation is the same',
  ARRAY['Open the GoTyme Bank app, tap ''Save'' and choose ''GoalSave''; the account itself is free to open', 'Name the GoalSave for its purpose (''Cushion'', ''School fees'') and set the target amount from your month plan', 'Read the interest terms shown in the app at that moment: GoTyme''s page describes 6% a year rising to 10% with 10 days'' notice, but published figures differ, so the app is the source', 'Move the first amount today from your GoTyme account, and set a recurring transfer for the day after payday', 'When you need the money, choose the notice option if you can wait 10 days; immediate withdrawal is allowed but may lose the bonus interest', 'Never open a GoalSave with money you have borrowed to put in it; the interest is less than any loan costs']::text[],
  'free to open; GoTyme''s own GoalSave page describes 6% a year rising to 10% a year with 10 days'' notice, up to 20 GoalSaves and R250,000 in total; published figures differ, so confirm the tiers in the GoTyme app (checked 2026-10-30)',
  'low',
  '2026-10-30'::date
)
