-- k.free_credit_report (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.free_credit_report',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['credit report', 'credit record', 'credit score', 'check my credit', 'free credit report', 'credit bureau', 'transunion', 'experian', 'xds', 'compuscan', 'clearscore', 'itc', 'blacklisted', 'am i blacklisted', 'credit check', 'credit profile', 'what is on my record', 'my name is listed', 'credit history', 'once a year free', 'see my credit report', 'lenders see', 'declined for credit', 'why was i declined']::text[],
  'Your free credit report, once a year from every bureau',
  'Section 72 of the National Credit Act gives you one free credit report a year from each registered credit bureau, so you can see exactly what lenders see: every account, every late payment, any judgment, and anything in your name that should not be. Get it on the bureau''s own site with your own ID: TransUnion at transunion.co.za, Experian through its Up platform at up.experian.co.za, XDS through Splendi. Read it for three things: an account you do not recognise, a debt with no payment for 3 years that may have prescribed, and anything paid that still shows as owing. Each of those is a free dispute. Nobody, including this service, needs your ID number to do this; you type it on the bureau''s site only.',
  'you have ever had an account, loan or contract in your name, or you were declined for credit and do not know why',
  'you have never had any credit, account or contract; the bureau may have no file on you yet',
  ARRAY['Go to transunion.co.za (free annual report page), up.experian.co.za or Splendi (XDS) on your phone and register with your own details; you will be asked for your ID number on their site, nowhere else', 'Answer the verification questions or the OTP they send, and download or view the report; online it is usually immediate', 'Read the accounts list and mark anything you do not recognise; that is possible fraud and goes to a dispute and SAFPS', 'Mark any account with no payment for 3 years and no summons; read the prescribed-debt rules before you touch it', 'Mark anything you have paid off that still shows a balance or ''adverse''; your paid-up letter is the evidence for a free dispute', 'Diary the date: you can get another free report from each bureau 12 months later, and never pay a site that charges for ''your free report''']::text[],
  'free: one report a year from each bureau under NCA section 72; TransUnion''s call centre is 0861 482 482 if the site will not verify you (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
