-- k.dispute_credit_listing (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.dispute_credit_listing',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['dispute', 'dispute credit report', 'wrong listing', 'incorrect information on credit report', 'account i don''t recognise', 'not my account', 'fraud on my credit report', 'remove judgment', 'judgment on my name', 'default listing', 'adverse listing', 'listed in error', '20 business days', 'nca section 72', 'bureau won''t fix', 'credit bureau complaint', 'ombud credit', 'clear my record', 'old debt on report', 'prescribed debt on report', 'paid but still listed']::text[],
  'Dispute what is wrong on your credit report, free',
  'If something on your credit report is wrong, section 72 of the National Credit Act says the bureau must investigate it at no charge and resolve it within 20 business days of your challenge, and the NCR''s guideline of December 2024 holds them to that. You dispute online on the bureau''s own site or by email, with evidence: a paid-up letter, a statement showing the last payment was over 3 years ago, or an affidavit that an account is not yours. A listing that cannot be proved must come off. If the bureau ignores you or refuses, the complaint goes free to the National Credit Regulator or the National Financial Ombud. For an old debt, never pay a cent or acknowledge it before checking prescription; that restarts the 3 years.',
  'your report shows an account you do not recognise, an old debt, or something paid that still shows as owing',
  'the listing is correct and current; then the fix is paying on time until it ages, not a dispute',
  ARRAY['Write one line for each wrong item: the account, what the report says, and what is true, with the evidence next to it (paid-up letter, statement, bank letter, SAPS case number for fraud)', 'Lodge the dispute on the bureau''s own site (TransUnion''s ''dispute an item'' page, Experian''s Up platform, XDS''s Splendi) or email, attaching the evidence; write the date down', 'Use plain words: ''I dispute the listing for [account]. It is [paid up on 12 March 2026 / not my account / prescribed, last payment June 2022]. Evidence attached. Please remove it under section 72 of the National Credit Act.''', 'Count 20 business days from the date you lodged; the bureau must have investigated and answered by then', 'If they refuse without proof, or do nothing, complain free to the NCR (complaints@ncr.org.za, 0860 627 627) or the National Financial Ombud on 0860 800 900, attaching your dispute and their reply', 'For an old debt, never pay ''to clear it'' and never sign an acknowledgment while disputing; a wrong listing is removed for free, not bought off']::text[],
  'free; the bureau must investigate without charge and resolve within 20 business days (NCA section 72, NCR guideline December 2024, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
