-- k.credit_score_moves (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.credit_score_moves',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['improve credit score', 'fix my credit', 'build credit', 'credit score low', 'raise my score', 'better credit score', 'credit score tips', 'how to get a good credit score', 'clean credit record', 'on time payments', 'pay on time', 'credit utilisation', 'store card limit', 'close accounts', 'too many accounts', 'credit score 600', 'score went down', 'what affects credit score', 'how long to fix credit', 'three months on time', 'clearscore score']::text[],
  'What actually moves your credit score',
  'Your score is a summary of what the bureaus see: whether you pay on time, how much of your limits you use, how many accounts you have, and anything adverse. The one thing that moves it most is paying every account on the date, month after month; each bureau weighs things a little differently and scores on its own scale, so do not chase one number. What does not help: opening new accounts to ''build'' a record (every application is a search against you, and it is new debt), paying a company to ''fix'' it, or closing a settled account in anger. What does: set every payment to the day after payday so you cannot miss, keep store and card balances well below the limit, dispute what is wrong, and give it 3 clean months before you look again.',
  'you have been declined, your score is low, or you want a clean record before a big goal',
  'you have never had credit and have no plans to; a score only matters when you need one',
  ARRAY['Pull your free report from one bureau and write the accounts with their ''paid on time'' history; that history, not the score, is what you are fixing', 'Set every account''s payment to the day after your money lands, by DebiCheck or a scheduled payment, so no month is missed', 'Pay store cards and credit cards down to well under their limits and keep them there; high usage against the limit pulls the score down', 'Dispute anything wrong (free, 20 business days) and get paid-up letters for anything settled', 'Do nothing new: no new accounts, no ''credit builder'' products, no applications, for 3 months; each one counts against you', 'After 3 months of every payment on the day, pull the report again from a different bureau (it is free) and compare; never pay a company that promises a score']::text[],
  'free; the bureaus'' own guidance is that payment history weighs most and each bureau scores on its own scale (TransUnion 0 to 999), so compare history, not scores (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
