-- k.paid_up_judgment_removal (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.paid_up_judgment_removal',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['judgment', 'judgement', 'court judgment on my name', 'paid judgment', 'remove judgment', 'judgment removal', 'rescission', 'rescind judgment', 'default judgment', 'judgment still showing', 'paid in full but judgment', '7 days', 'judgment on credit report', 'listed with a judgment', 'how long does a judgment stay', 'ncr regulations 2014', 'adverse information', 'default', 'paid default']::text[],
  'A paid judgment must come off within 7 days',
  'If a court judgment was granted against you and you have since paid it, you do not need a lawyer to clear it. Under the 2014 regulations on the removal of adverse consumer credit information, the creditor must send proof of payment to every registered bureau within 7 days of receiving it, and the bureau must remove the paid-up judgment within 7 days of receiving that proof; the bureaus must then tell each other within 3 days. The creditor may never relist it. Paid-up defaults are removed once the lender confirms paid-up status. So the move is: pay it, get the paid-up letter, send the letter to the bureaus yourself, and dispute if it is still there after a few weeks.',
  'a judgment or default on your credit report has been paid in full',
  'the judgment is unpaid; then it is a debt to settle or arrange, and a registered debt counsellor or Legal Aid SA can advise on rescission',
  ARRAY['Pay the judgment debt in full and ask the creditor or their attorney for a paid-up letter the same day, with the case number on it', 'Ask the creditor to send proof of payment to all registered bureaus; the regulations give them 7 days', 'Send the paid-up letter yourself to TransUnion, Experian and XDS through their dispute channels, so you are not waiting on the creditor', 'Count 7 days from when the bureau received it; the judgment must be removed, and the other bureaus informed within 3 days', 'Pull your free report after 3 weeks; if the judgment or the paid default still shows, lodge a section 72 dispute with the letter attached', 'Never pay a ''judgment removal'' company; the removal is the bureau''s legal duty and costs nothing']::text[],
  'free; creditor sends proof within 7 days, bureau removes within 7 days of receiving it, other bureaus within 3 days (Removal of Adverse Consumer Credit Information Regulations 2014, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
