-- k.debt_review_clearance (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.debt_review_clearance',
  'ZA',
  'credit_record',
  ARRAY['stretching', 'steady', 'building']::text[],
  ARRAY['clearance certificate', 'form 19 clearance', 'exit debt review', 'finished debt review', 'debt review flag', 'remove debt review flag', 'still under debt review', 'paid up debt review', 'nca section 71', 'debt review on my credit report', 'debt counsellor won''t give certificate', 'after debt review', 'life after debt review', 'can i get credit after debt review', 'debt review removal letter', 'national consumer tribunal', 'debt review listing', 'come off debt review']::text[],
  'Finishing debt review: the clearance certificate',
  'Debt review ends with a clearance certificate (Form 19), not just the last payment. Section 71 of the National Credit Act says your debt counsellor must issue it within 7 days of you satisfying the restructured plan, and within a further 7 days must file a copy with every registered credit bureau, which must then expunge the debt review record. If the counsellor drags their feet, you can apply to the National Consumer Tribunal. Until the certificate is filed, the flag stays and no lender may give you credit, so chase it in writing on the day of the last payment. The certificate is yours by law; never pay a ''removal'' company for it.',
  'you have made the last payment under a debt review plan, or paid up everything except a home loan that is current',
  'you still have restructured debts with balances; the certificate only comes when the plan is satisfied',
  ARRAY['On the day of the last restructured payment, message your debt counsellor: ''All restructured debts are paid. Please issue my clearance certificate (Form 19) under section 71 within 7 days.'' Keep the message', 'Ask the payment distribution agent for a final statement showing every account at zero; attach it', 'Count 7 days; the counsellor must have issued the certificate, and 7 days after that it must be filed with all the bureaus', 'Pull your free credit report after 3 weeks and check the debt review flag is gone; if not, dispute with the bureau attaching the certificate', 'If the counsellor refuses or stalls, complain to the NCR on 0860 627 627 or apply to the National Consumer Tribunal; both are free', 'Never take new credit in the first months after clearance just because you can; the cushion comes first']::text[],
  'free; the counsellor must issue the certificate within 7 days and file it with the bureaus within a further 7 days (NCA section 71, NCR guideline February 2026, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
