-- k.funeral_cover_rules (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.funeral_cover_rules',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['funeral cover', 'funeral policy', 'funeral plan', 'burial', 'waiting period', 'six months waiting', '6 month waiting period', 'accidental death', 'cooling off', 'cancel my policy', '31 days', 'funeral claim', 'claim rejected', 'premium', 'how much funeral cover', 'funeral insurance', 'cover my parents', 'cover my children', 'extended family cover', 'policy lapsed', 'missed a premium', 'underwriter', 'is this insurer registered', 'funeral cover scam']::text[],
  'Funeral cover: the rules that decide whether it pays',
  'A funeral policy is the cheapest protection a household can buy, and the one most often sold badly. The rules to know: most policies have a waiting period of up to 6 months for death from natural causes (some insurers 3 months), while accidental death is usually covered from day one; if you already served a waiting period on another funeral policy, the new insurer may not make you serve it again. You have a cooling-off period of 31 days after getting the policy documents to cancel and get your money back if you have not claimed. A missed premium can lapse the policy, so pay it the day after money lands. Before you sign, check the insurer or its underwriter is licensed with the FSCA.',
  'you are buying, holding or claiming on a funeral policy, or paying one you do not understand',
  'you have no dependants and someone else already covers your own funeral in writing',
  ARRAY['Read the policy schedule for 4 things: who is covered, the payout amount, the monthly premium, and the waiting period for natural death', 'Check the insurer''s name on the FSCA register at fsca.co.za or by phoning 0800 110 443; an unlicensed ''funeral scheme'' pays nobody', 'If you had a funeral policy before, tell the new insurer in writing; under the Policyholder Protection Rules they may not impose a new waiting period you have already served', 'Set the premium debit order for the day after money lands; a lapsed policy means a new waiting period', 'If you change your mind, cancel within 31 days of receiving the documents and the premiums must be refunded if you have not claimed', 'When claiming, send the death certificate and the claim form the same week and ask for the insurer''s written decision; if it is rejected unfairly, the National Financial Ombud on 0860 800 900 takes the complaint free']::text[],
  'the premium is set by the insurer; the rules that protect you are free: up to 6 months waiting for natural death, accidental death usually from day 1, 31 days cooling-off (FSCA guidance, Policyholder Protection Rules, checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
