-- k.double_cover (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.double_cover',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['two funeral policies', 'double cover', 'duplicate policy', 'too many policies', 'paying for the same thing twice', 'cancel a policy', 'which policy to keep', 'burial society and funeral policy', 'policy on my grant', 'covered twice', 'credit life and funeral', 'policy list', 'insurance audit', 'premiums eat my money', 'how many funeral policies', 'cancel insurance', 'insurance i don''t need', 'stop paying premiums', 'cellphone insurance', 'retail policy']::text[],
  'One policy that fits; cancel the doubles',
  'Most households are paying for the same funeral twice: a policy from a shop account, one through a grant deduction, a burial society, and the one the family took out years ago. Only one will be needed, and the rest are money thrown away every month. List every policy, society and plan with its premium, its payout, who it covers and its waiting period. Keep the one with the best payout per rand of premium that covers the people who actually depend on you, and whose waiting period you have already served. Cancel the doubles in writing, and watch for the grant: SASSA allows only one funeral deduction, and it may never be more than 10% of the grant.',
  'you pay more than one funeral policy, society or plan, or you are not sure what you are paying for',
  'you have exactly one policy that covers everyone who depends on you',
  ARRAY['Write every policy, burial society and plan on one page: the name, the monthly premium, the payout, who it covers, and the waiting period left', 'Check your bank statement and your grant statement for premiums you forgot: a policy sold with a store account, a cellphone ''cover'', a deduction on a grant', 'Divide each payout by its premium: the one that pays most per rand, covers the right people, and has served its waiting period is the one to keep', 'Cancel the doubles by phone and then in writing: ''Please cancel policy number [x] from [date] and confirm in writing.'' Keep the confirmation and watch next month''s statement', 'For a policy deducted from a SASSA grant you did not agree to, dispute it by SMS to 34548 with your ID number and the insurer''s name, and cancel with the insurer', 'Never cancel the policy you are keeping to ''start fresh''; a new policy means a new waiting period of up to 6 months']::text[],
  'free to cancel; the saving is every double premium; a SASSA grant may carry only one funeral deduction of at most 10% (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
