-- k.beneficiary_nomination (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.beneficiary_nomination',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['beneficiary', 'nominate beneficiary', 'who gets the money', 'change beneficiary', 'beneficiary on my policy', 'beneficiary form', 'policy papers', 'where are the documents', 'if i die', 'when i die', 'will', 'write a will', 'estate', 'master of the high court', 'provident fund beneficiary', 'pension beneficiary', 'life cover beneficiary', 'funeral payout to who', 'nomination form', 'my family won''t know']::text[],
  'Name who gets it, and tell them where the papers are',
  'A policy pays the person named on it, not the person who needs it. If the beneficiary is nobody, an ex-partner, or someone who has died, the payout goes into your estate and your family waits months while the Master of the High Court sorts it out. Check every policy, funeral plan, bank account and retirement fund for the named beneficiary, change it on the insurer''s or fund''s form where it is wrong, and tell that person two things: that the policy exists and where the papers and the policy number are. For a retirement fund the trustees decide according to who depended on you, but your nomination form guides them. A simple will, kept with the papers, finishes the job.',
  'someone depends on your income, and you have any policy, fund or account',
  'you have no policy, no fund and no account; then the first job is the one policy that fits',
  ARRAY['List every policy, fund and account you have, and next to each write who is named as the beneficiary; phone the insurer or fund if you do not know', 'Change any that are wrong on the insurer''s or fund''s own beneficiary form; most accept it by email or in the app, and it is free', 'For a provident or pension fund, fill in the fund''s nomination form naming everyone who depends on you; the trustees use it under section 37C of the Pension Funds Act', 'Tell the beneficiary, in person, that the policy exists, the insurer''s name, the policy number and where the papers are kept', 'Put the papers (or photos of them) in one place: a folder at home and a copy on your phone or email', 'Write a simple will naming who gets what, sign it in front of 2 witnesses who are not beneficiaries, and keep it with the papers; never leave it to ''the family will know''']::text[],
  'free: changing a beneficiary with the insurer or fund costs nothing; a basic will can be written yourself and witnessed by 2 people (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
