-- k.sim_swap_signs (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.sim_swap_signs',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['sim swap', 'simswap', 'lost signal', 'no network', 'phone has no signal', 'otp', 'one time pin', 'someone asked for my otp', 'bank called me', 'the bank phoned', 'fraud', 'scam', 'scammed', 'phishing', 'vishing', 'fake bank sms', 'money stolen from my account', 'my account was hacked', 'banking app fraud', 'approve this transaction', 'block my card', 'report fraud', 'sabric', 'bank will never ask', 'stop fraud settings']::text[],
  'The bank never asks for your PIN, OTP or app approval',
  'SABRIC''s 2025 report counted R2.41 billion stolen through digital banking, 88.6% of it through banking apps, and almost none of it by hacking: people were talked into it by someone pretending to be the bank, the police or a courier. Three facts stop most of it. The bank never phones to ask for your PIN, password, OTP or to approve something in the app; a real bank call never needs those. A SIM swap starts with your phone losing signal for no reason; if that happens, phone your network and your bank''s fraud line from another phone immediately. And no OTP is ever shared with anyone, including family, because the OTP is the money. Switch on every security setting in your app and keep the fraud number saved.',
  'you use a banking app, get bank SMSes, or someone has phoned claiming to be from the bank',
  'you have no bank account at all; then the risk is cash and the SASSA card PIN, same rule: tell nobody',
  ARRAY['Open your banking app''s security settings and switch on every lock: app PIN or fingerprint, transaction notifications, card lock, and limits on online and international purchases', 'Save your bank''s fraud line in your phone now (Capitec 0860 10 20 43, FNB 087 575 9444, Standard Bank 0800 222 050, Absa 0860 557 557, Nedbank 0800 110 929, GoTyme 0860 999 119) and confirm it against the number in your app, never from an SMS', 'If your phone loses signal for no reason, treat it as a SIM swap: phone your network from another phone, then the bank''s fraud line, and ask them to block the account', 'If anyone phones ''from the bank'' asking for a PIN, OTP, password or to approve an app message to ''stop fraud'', hang up and call the bank''s number from your card yourself', 'Never click a link in an SMS or WhatsApp to ''verify'', ''unlock'' or ''claim a refund''; open the app yourself instead', 'If money has gone: fraud line first, then the police case number, then SAFPS protective registration; all three are free']::text[],
  'free: every app security setting and every fraud line is free; SABRIC reported R2.41 billion in digital banking losses in 2025, 88.6% through banking apps (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
