-- k.ponzi_signs (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.ponzi_signs',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['ponzi', 'pyramid', 'pyramid scheme', 'investment scam', 'forex', 'forex trading', 'crypto', 'bitcoin investment', 'guaranteed returns', 'double your money', '30% a month returns', 'whatsapp investment', 'telegram investment', 'job scam', 'pay a fee for a job', 'registration fee for job', 'recruit', 'stokvel investment', 'is this legit', 'check if company is registered', 'fsp number', 'fsca', 'licensed', 'too good to be true', 'mmm', 'gifting circle', 'investment club', '30% a month', 'percent a month', 'promising returns', 'investment group', 'investment opportunity', 'wealth club']::text[],
  'Check any offer before a cent moves',
  'A real investment is licensed and boring; a scheme is urgent and exciting. The signs are the same every time: returns that are ''guaranteed'' or far above what a bank pays, pressure to recruit friends to earn, paying in to ''unlock'' a payout, a job that asks for a registration fee, and a contact that only exists on WhatsApp or Telegram. Under section 43 of the Consumer Protection Act, any scheme offering a return 20 percentage points or more above the repo rate is a multiplication scheme and illegal to promote or join. Before any money moves, check the company and its FSP number on the FSCA''s register at fsca.co.za or on 0800 110 443, and check the name matches the number; scammers borrow real FSP numbers.',
  'someone offers you an investment, a trading group, a ''stokvel'' with returns, or a job that needs a fee',
  'the money is going to a bank savings product or a fund whose FSP number you have already matched on the FSCA register',
  ARRAY['Ask for the company''s registered name and FSP number in writing, and the name of the person''s own licence', 'Search both on the FSCA register at fsca.co.za (or phone 0800 110 443) and check the name on the register matches the name you were given; a borrowed number is the commonest trick', 'Run the 5 signs: guaranteed returns, recruit-to-earn, pay-to-get-paid, a job that charges a fee, WhatsApp or Telegram only; one sign is enough to stop', 'Do the arithmetic: 20 percentage points above the repo rate is a multiplication scheme under section 43 of the Consumer Protection Act, and anything promising 30% a month is a scheme by definition', 'Say the one line and leave: ''Send me the FSP number and I will check it.'' Real providers are glad to; schemes argue', 'If you already paid, stop paying, keep every message, report it to the FSCA and the police, and warn the person who recruited you; never pay more to ''release'' your money']::text[],
  'free to check: the FSCA register and its line 0800 110 443 cost nothing; a return 20 percentage points above the repo rate is an illegal multiplication scheme under CPA section 43 (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
