-- k.safps_protective_reg (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.safps_protective_reg',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['safps', 'protective registration', 'lost my id', 'stolen id', 'id stolen', 'account opened in my name', 'loan in my name', 'impersonation', 'fraud prevention', 'protect my identity', 'lost wallet', 'stolen phone', 'id book stolen', 'passport stolen', 'register my lost id', 'fraud alert', 'victim of fraud']::text[],
  'Protective registration with SAFPS: free, and it works',
  'If your ID, passport, driver''s licence or phone is lost or stolen, or someone has opened an account in your name, register with the Southern African Fraud Prevention Service. Protective Registration is free: SAFPS puts a marker against your identity so that when anyone applies for credit, a contract or an account in your name, the member bank or lender gets an alert and must check it is really you. You apply on safps.org.za, by email to protection@safps.org.za with a certified copy of your ID and the form, or by phone on 011 867 2234, and you get a reference number within about 48 hours. It does not block you from getting credit yourself; it only makes the lender check harder. Do it the same day the ID goes missing.',
  'your ID or phone is lost or stolen, you have shared your ID copy with someone you do not trust, or there is an account you did not open',
  'nothing has been lost and nothing strange is on your credit report; it is still free, but the report check comes first',
  ARRAY['Report the lost or stolen ID at the police station and get the case number; SAFPS and the bank will ask for it', 'Go to safps.org.za, choose ''Apply for Protective Registration'', and fill in the form; or email the form with a certified ID copy to protection@safps.org.za, or phone 011 867 2234', 'Keep the reference number SAFPS sends (usually within 48 hours) with your police case number', 'If a lender already gave credit in your name, ask them in writing for a letter confirming impersonation; with that letter SAFPS can list you as a victim of impersonation too', 'Pull your free credit report from each bureau and dispute any account that is not yours, attaching the case number and the SAFPS reference', 'Never post a photo of your ID on WhatsApp groups or hand a copy to a ''job agent''; a copy is all a fraudster needs']::text[],
  'free: Protective Registration costs nothing and a reference number is issued within about 48 hours (SAFPS, checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
