-- k.family_line (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.family_line',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['black tax', 'family needs money', 'family asks for money', 'sending money home', 'support my parents', 'support my siblings', 'everyone depends on me', 'breadwinner', 'family pressure', 'how to say no to family', 'money for my mother', 'extended family', 'send money every month', 'fixed amount for family', 'family budget', 'relatives', 'cousins asking', 'guilt', 'family expects me to pay', 'ukwanda', 'supporting family on low income', 'asking me for money', 'keeps asking for money', 'family keeps asking', 'ask me for money', 'relatives ask for money', 'my family needs money', 'earn the least', 'pay for everyone', 'everyone at home', 'help my sister', 'sister''s school fees', 'family school fees', 'keep my own savings']::text[],
  'Set the family line: one amount, one day',
  'Helping family is not the problem; helping without a number is, because it is the line in your month that changes every time the phone rings, and it is usually the line that pushes a month into a loan. The fix is one fixed amount, sent on the same day every month by PayShap, said once and kindly: the amount, the day, and that it will come every month so they can plan around it. The amount comes from your month plan after bills and the money put aside, not from the last request. When an extra request comes, the answer is one line: ''That will have to wait for next month''s amount.'' It protects them as much as you: a fixed amount that arrives beats a bigger one that sometimes does not.',
  'family or relatives regularly ask for money and the amount changes every month',
  'nobody outside your household depends on you, or the family amount is already fixed and sent on a set day',
  ARRAY['Write down what you actually gave to family in each of the last 3 months, from your banking app and your memory; the real number is usually higher than you think', 'Look at your month plan: after pot 1 (bills) and pot 2 (cushion), what can the month carry every month without a loan? That is the family line', 'Choose the day: the day after your money lands, by PayShap to their ShapID, so it arrives before the asking starts', 'Say it once, in a calm moment, not when someone asks: ''From now on I send R[amount] on the [day] every month. It will always come. Extra requests will have to wait for the next month.''', 'Write it in the month plan as its own line, and send the same amount on the same day for 3 months so people can plan around it', 'When an extra request comes, use the one line and do not borrow to meet it; never cut the amount in anger, and never raise it because the asking got louder']::text[],
  'free; a PayShap payment under R100 is free at most banks, and sending on one day replaces several transfers (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
