-- k.stokvel_safety (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.stokvel_safety',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['stokvel', 'stokvels', 'stokvel constitution', 'join a stokvel', 'start a stokvel', 'stokvel rules', 'stokvel money', 'treasurer ran away', 'stokvel scam', 'stokvel bank account', 'nasasa', 'registered stokvel', 'savings club', 'grocery stokvel', 'rotating savings', 'umgalelo', 'gooi-gooi', 'society', 'stokvel payout', 'who holds the money', 'stokvel account', 'is my stokvel safe', 'stokvel audit', 'safe place to save', 'is a stokvel safe', 'stokvel pyramid', 'stokvel a pyramid scheme', 'is my stokvel legit', 'stokvel registered']::text[],
  'Check the stokvel you pay into',
  'More than 11 million South Africans belong to a stokvel, and a good one is the oldest cushion there is. A safe one has four things: a written constitution that says who the members are, how much and when you pay, how and when payouts happen, and what happens when someone leaves; a bank account in the stokvel''s name needing two or three signatures, not the treasurer''s personal account; books any member can see; and, for bigger groups, registration with NASASA, which has a sample constitution and a line on 010 007 2129. A ''stokvel'' that promises returns, pays you for recruiting, or needs you to pay in before you can take out is not a stokvel; it is a pyramid scheme, and illegal.',
  'you pay into a stokvel, burial society or savings club, or are thinking of joining one',
  'you belong to none; then this is a check for the future before you join one',
  ARRAY['Ask for the constitution and read it for 4 things: members, contributions and dates, how payouts are decided, and what happens when someone leaves or dies', 'Ask where the money sits: a bank account in the stokvel''s name needing 2 or 3 signatures is safe; cash with the treasurer or a personal account is not', 'Ask to see the books or the bank statement at the next meeting; every member has the right to look', 'Check whether the group is registered with NASASA (phone 010 007 2129 or email info@nasasa.co.za), and use NASASA''s sample constitution if yours has none', 'Test it against the pyramid signs: promised returns, money for recruiting, paying in to ''unlock'' a payout; any one of them, leave', 'Never pay a contribution in cash without a signed receipt in the book, and never hand your bank card or PIN to the treasurer ''for convenience''']::text[],
  'free to check; NASASA (010 007 2129) offers a sample constitution, and more than 11 million South Africans belong to a stokvel (NASASA 2025, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
