-- k.burial_society_vs_policy (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.burial_society_vs_policy',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['burial society', 'society', 'masingcwabane', 'umasingcwabane', 'burial scheme', 'society vs policy', 'burial society or funeral policy', 'society payout', 'society rules', 'society contribution', 'funeral society', 'who pays for the funeral', 'funeral costs', 'coffin', 'society did not pay', 'society collapsed', 'funeral parlour policy', 'undertaker policy', 'parlour scheme', 'is my burial society registered']::text[],
  'Burial society or funeral policy: what each one really pays',
  'A burial society pays from the members'' own pool, in cash or in kind (the tent, the coffin, the cooking), decided by its own rules; a funeral policy pays a fixed amount from a licensed insurer under the Policyholder Protection Rules, with a waiting period and a cooling-off right. Neither is better; the mistake is paying both for the same funeral, or trusting a society or a parlour ''scheme'' with no written rules. Ask the society what exactly it pays, in writing, and whether its money sits in a bank account with more than one signature. Ask a funeral parlour selling cover for the name of the licensed insurer behind it and check it on the FSCA register; a parlour is not an insurer.',
  'you pay into a burial society, a parlour scheme, or both a society and a policy',
  'you have one funeral policy with a licensed insurer and no society; then the policy list is the check',
  ARRAY['Write what the society promises to pay and in what form (cash, coffin, tent, groceries), from its constitution or minutes, not from memory', 'Ask the treasurer where the money is kept: a bank account in the society''s name with 2 or 3 signatures, with the statement shown at meetings', 'For a parlour or ''scheme'', ask for the underwriter''s name and FSP number and check it on fsca.co.za or on 0800 110 443; no licensed insurer means no legal cover', 'Put the society and every policy on one page with premium, payout and who is covered, and keep the combination that covers the family once, not twice', 'If the society''s rules are only in someone''s head, propose adopting NASASA''s sample constitution at the next meeting', 'Never stop a licensed policy to rely only on a society whose books you have not seen, and never pay a parlour in cash without a receipt and a policy document']::text[],
  'free to check; a society''s payout is set by its own rules, a policy''s by the schedule; the FSCA line 0800 110 443 confirms whether an insurer is licensed (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
