-- k.lending_to_family (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.lending_to_family',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['lend money to family', 'lending to friends', 'friend owes me', 'family owes me money', 'borrowed from me', 'won''t pay me back', 'my brother owes me', 'lend or give', 'loan to a friend', 'stand surety', 'sign surety', 'co-sign', 'guarantor', 'open an account for someone', 'cellphone contract for my cousin', 'take out a loan for a friend', 'my name for their account', 'lend my card', 'they used my name', 'family debt', 'in my name', 'contract in my name', 'phone contract in my name', 'account in my name for someone', 'take a contract for my cousin', 'sign for someone']::text[],
  'Lending to family: give it, write it, or say no',
  'Money lent to family is usually a gift with a grudge attached. The rule is three choices and nothing in between: give it if you can afford to never see it again; lend it in writing, with the amount, the date and how it comes back, if you cannot; or say no with the one line. Never do the fourth thing: putting your own name on their debt, by taking a loan, a cellphone contract or a store account for someone else, or signing surety. The lender does not know or care whose phone it is; the listing, the collectors and the garnishee come to you, and a family promise is no defence. The National Credit Act protects borrowers from lenders, not from each other.',
  'a relative or friend asks you to lend money, take credit in your name, or sign for them',
  'nobody is asking and your month plan already has the fixed family line',
  ARRAY['Decide which of the 3 it is before you answer: a gift from pot 3 you can afford, a written loan, or a no', 'For a loan, write it on paper or in a WhatsApp message both of you keep: ''I lend you R400 on 3 November 2026. You pay R100 on the 27th of each month until it is paid.'' A message is a record', 'Choose a repayment day that is their payday, not yours, and remind once, kindly, the day before', 'Say no to any request to open an account, take a contract or sign surety in your name with the one line: ''I don''t put my name on anyone''s debt, not even family.''', 'If you already have, get the account statement from the lender, pay the arrears yourself to protect your record, and cancel or transfer the account as soon as the contract allows', 'Never lend what you would have to borrow to replace, and never hand over your bank card to ''help out''']::text[],
  'free; a written note or a WhatsApp message both keep is enough to record a loan between people (checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
