-- k.pyramid_scheme_law (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.pyramid_scheme_law',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['pyramid scheme', 'gifting', 'gifting circle', 'blessing loom', 'loom', 'wealth circle', 'women empowering women', 'community stokvel', 'investment stokvel', 'multiplication scheme', 'cpa section 43', 'consumer protection act', 'recruit two people', 'pay in r500 get r4000', 'stokvel that pays interest', 'whatsapp stokvel', 'facebook stokvel', 'national consumer commission', 'report pyramid scheme', 'up money scheme', 'mmm', 'chain letter']::text[],
  'A ''stokvel'' that pays returns is a pyramid scheme',
  'Every few years the pyramid scheme comes back wearing a stokvel''s clothes: a ''gifting circle'', a ''blessing loom'', a ''community investment'' on WhatsApp or Facebook where you pay in and get paid when others join. Section 43 of the Consumer Protection Act makes it illegal to promote or take part in a pyramid scheme (payouts come from recruiting, not from anything sold), a chain letter, or a multiplication scheme (a promised return 20 percentage points or more above the repo rate). The National Consumer Tribunal fined Up Money R1 million for exactly this. The last people in always lose, and they are usually family. A real stokvel pays out what the members put in, in turn, and nothing more.',
  'someone invites you to a group that pays out when you recruit, or a ''stokvel'' promising a return on what you pay in',
  'the group is a rotating or grocery stokvel with a constitution, where payouts are the members'' own contributions in turn',
  ARRAY['Ask the one question: ''Where does the payout money come from?'' If the answer is new members, it is a pyramid scheme under section 43 of the Consumer Protection Act', 'Do the arithmetic on any promised return: paying R500 to receive R4,000 is a multiplication scheme, illegal whatever it is called', 'Check the signs: recruit-to-earn, pay to ''unlock'' your payout, WhatsApp or Facebook only, pressure to join ''before it closes''', 'Say no to the person who invited you with one line: ''I only put money where I can see the constitution and the bank statement.''', 'If you have paid in, stop, keep every message and proof of payment, and report it to the National Consumer Commission; the Tribunal has fined schemes like Up Money R1 million', 'Never recruit someone else to get your own money back; that makes you the one breaking the law, and it is usually family who loses']::text[],
  'free to walk away; promoting or joining a pyramid or multiplication scheme (20 percentage points above the repo rate) is prohibited under CPA section 43, and Up Money was fined R1 million (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
