-- k.goal_vehicle (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.goal_vehicle',
  'ZA',
  'goals',
  ARRAY['steady', 'building']::text[],
  ARRAY['goal', 'savings goal', 'bigger goal', 'long term saving', 'save for a house', 'save for a car', 'save for school', 'university fees', 'save for my child''s education', 'where to put savings', 'best place to save', 'tax free savings', 'tfsa', 'retirement', 'retirement annuity', 'unit trust', 'fixed deposit', 'notice deposit', 'investment for beginners', 'start investing', 'save for 5 years', 'vehicle for savings', 'save long term', 'education fund', 'save or invest', 'invest or save', 'safest way to grow', 'grow my money', 'grow r10000', 'buy a car', 'save for a car first', 'start a small business', 'business with my savings', 'invest']::text[],
  'Match the goal to the place the money lives',
  'Money without a destination drifts back into the month. Once the cushion exists, each bigger goal needs a vehicle that fits how far away it is. Within a year: a savings pocket or GoalSave at your bank, where the money is reachable. Several years away: a tax-free savings account, where the growth is never taxed, up to R46,000 a year from 1 March 2026 and R500,000 in a lifetime. A first home: the First Home Finance subsidy through the NHFC if your household earns R3,501 to R22,000 a month. Retirement: the fund you already have at work, left alone. The vehicle decides nothing about the amount; the goal sentence does that. One goal, one vehicle, one automatic transfer on payday.',
  'the cushion is in place and you are saving toward something with a number and a date',
  'you have no cushion yet or you still owe a mashonisa; the cushion and the owed list come before any goal',
  ARRAY['Write the goal in one sentence with a number and a date: ''R12,000 for Thabo''s school fees by January 2028''', 'Count the months to the date and divide: that is the monthly number, and it has to fit pot 2 of the month plan', 'Pick the vehicle by distance: under a year, a GoalSave or savings pocket at your bank; more than 3 years, a tax-free savings account (R46,000 a year, R500,000 lifetime); a first home, the NHFC First Home Finance subsidy if your household earns R3,501 to R22,000 a month', 'Open it with a provider you can check on the FSCA register, and name it for the goal', 'Set a recurring transfer for the day after payday for the monthly number, and nothing else touches it', 'Never fund a goal by withdrawing retirement savings or taking credit; a goal that costs interest or your pension is not a goal, it is a debt']::text[],
  'free to set up at most banks; tax-free savings allow R46,000 a year from 1 March 2026 and R500,000 in a lifetime (SARS), and First Home Finance covers household incomes of R3,501 to R22,000 a month (NHFC, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
