-- k.tfsa_rules (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.tfsa_rules',
  'ZA',
  'goals',
  ARRAY['steady', 'building']::text[],
  ARRAY['tfsa', 'tax free savings', 'tax-free savings account', 'tax free investment', 'r46000', 'r36000', 'tax free limit', 'lifetime limit', 'r500000', '40% penalty', 'over-contribute', 'tax free for my child', 'open tfsa', 'which tfsa', 'tfsa withdrawal', 'can i withdraw from tfsa', 'tax free unit trust', 'tax free fixed deposit', 'sars tax free', 'tfsa rules 2026']::text[],
  'Tax-free savings: the rules that bite',
  'A tax-free savings account grows without any tax on the interest or growth, which is why it is the right place for a goal 3 years or more away. From 1 March 2026 you may put in up to R46,000 a tax year (R36,000 before), across all your tax-free accounts together, and R500,000 in your lifetime. Anything over either limit is taxed at 40% by SARS, so one accidental extra deposit costs real money. Withdrawing is allowed at any time, but what you take out does not restore the room: the lifetime count only goes up. So use it only for money you will not need soon, start small, and let the yearly limit be the ceiling, not the target.',
  'you have a cushion and are saving for something 3 or more years away',
  'you are still building the cushion or paying expensive debt; a tax-free account is for money you will not touch',
  ARRAY['Open a tax-free savings account with a bank, unit trust company or investment platform you have checked on the FSCA register; the account must be labelled ''tax-free'' under SARS rules', 'Decide the monthly number from your goal sentence; it may be small, there is no minimum in the law', 'Set a recurring transfer for the day after payday and stay well under R46,000 a year across all your tax-free accounts (the limit from 1 March 2026)', 'Keep a running total in your notes app of everything you have ever paid in; the lifetime limit of R500,000 counts deposits, not the balance', 'Do not withdraw for anything except the goal; money taken out never gives you the contribution room back', 'Never pay in more than the limits, even by mistake: SARS taxes the excess at 40%, and never open a second one without counting the first']::text[],
  'free to open at most providers (fees differ, ask); annual limit R46,000 from 1 March 2026, lifetime R500,000, excess taxed at 40% (SARS, checked 2026-10-30)',
  'medium',
  '2026-10-30'::date
)
