-- k.first_home_finance (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.first_home_finance',
  'ZA',
  'goals',
  ARRAY['steady', 'building']::text[],
  ARRAY['flisp', 'first home finance', 'housing subsidy', 'home subsidy', 'government help to buy a house', 'first time buyer', 'buy my first house', 'bond subsidy', 'nhfc', 'deposit for a house', 'home loan', 'r22000 income subsidy', 'gap housing', 'subsidy for home loan', 'rdp vs flisp', 'how much is flisp', 'apply for flisp', 'flisp calculator', 'subsidy amount', 'own a house']::text[],
  'First Home Finance: the subsidy for a first home',
  'First Home Finance (the programme once called FLISP) is a once-off government subsidy toward buying a first home, for South African citizens and permanent residents whose household earns R3,501 to R22,000 a month, who have never owned property or had a housing subsidy, and who will live in the home. The subsidy is bigger the lower your income; published figures for 2026 differ (a top of R169,264, a bottom of R27,960 or R38,878), so use the NHFC''s calculator for your own number. It pays toward the deposit or reduces the home loan. Applications go through the NHFC''s online portal, which opens in windows, or through a participating bank when you apply for the loan.',
  'you want to buy a first home, have a steady income in the band, and have never owned property',
  'your household income is above R22,000 or below R3,501 a month, you have owned property before, or you already received a housing subsidy',
  ARRAY['Check the 4 conditions: household income R3,501 to R22,000 a month, first-time buyer, citizen or permanent resident, and you will live in the home', 'Use the NHFC First Home Finance calculator on nhfc.co.za with your income to see your subsidy; published ranges differ, so trust the calculator, not a blog', 'Get your credit record clean first: a home loan needs 3 months of on-time payments on everything, so this goal starts in the credit-record part of your plan', 'Get a home loan approval in principle from a bank and tell them you intend to apply for First Home Finance; some banks still ask for the approval first', 'Apply on the NHFC online portal during an open window (the portal closes between windows, so check nhfc.co.za) with your ID, payslips or bank statements and the loan quote; never through a third party who charges a fee', 'Never sign an offer to purchase before the subsidy and the loan are both confirmed in writing']::text[],
  'free to apply; household income band R3,501 to R22,000 a month; published 2026 subsidy figures differ (up to R169,264), so confirm on the NHFC calculator (checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
