-- k.two_pot_withdrawal (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.two_pot_withdrawal',
  'ZA',
  'goals',
  ARRAY['stretching', 'steady', 'building']::text[],
  ARRAY['two pot', 'two-pot', '2 pot system', 'savings pot', 'retirement pot', 'withdraw from my pension', 'withdraw from provident fund', 'cash out retirement', 'savings component withdrawal', 'r2000 minimum', 'once a year withdrawal', 'two pot tax', 'how much tax on two pot', 'two pot claim', 'fund administrator', 'pension fund withdrawal', 'provident fund', 'retirement fund', 'should i withdraw my two pot', 'two pot 2026', 'tax directive', 'pension savings pot', 'take money out of my pension', 'pension money', 'retirement money early', 'access my pension']::text[],
  'Two-pot: what a withdrawal costs you',
  'Since 1 September 2024 a third of each new retirement contribution goes into a savings pot you can reach before retirement. You may take one withdrawal from it per tax year, at least R2,000, through your fund''s own portal, and it is taxed at your marginal rate with no tax-free portion, and SARS deducts any tax you already owe before it pays. Once paid, it cannot be reversed or paid back in. It is your money, and in a real emergency it is better than a mashonisa; but every rand taken is a rand that will not be there at 60, and the tax alone usually costs more than the cushion would have. In this plan the order is fixed: cushion first, two-pot only for a true emergency, and never for a goal.',
  'you belong to a pension, provident or retirement annuity fund and are thinking of taking from the savings pot',
  'you have no retirement fund, or your need can be met from the cushion',
  ARRAY['Ask yourself the cushion question first: would you borrow for this? If not, it does not come out of the savings pot', 'Log in to your fund administrator''s two-pot portal (your HR or the fund''s member line has the link) and read your savings pot balance; do not guess', 'Work out the tax: the amount is added to your income for the year and taxed at your marginal rate, with no tax-free portion, and SARS first deducts any tax debt', 'Remember the rules: one withdrawal per tax year (1 March to 28 February), minimum R2,000, and it cannot be cancelled once the tax directive is issued', 'If you do withdraw, take only what the emergency costs, and put the rest of the plan back on payday the next month', 'Never withdraw to pay a ''quick'' debt you could snowball, and never for a goal; a goal has its own vehicle']::text[],
  'no fee from most funds, but the withdrawal is taxed at your marginal rate with no tax-free portion; one per tax year, minimum R2,000, cannot be reversed (SARS and fund guidance, checked 2026-10-30)',
  'high',
  '2026-10-30'::date
)
