-- k.goal_monthly_number (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.goal_monthly_number',
  'ZA',
  'goals',
  ARRAY['steady', 'building']::text[],
  ARRAY['how much to save a month', 'monthly savings amount', 'goal calculator', 'save r10000', 'save for december', 'save for christmas', 'save for school fees', 'january fees', 'school uniform', 'save for a trip', 'save for furniture', 'save for wedding', 'save for lobola', 'save for a deposit', 'divide by months', 'goal date', 'goal number', 'how long to save', 'realistic goal', 'goal too big', 'child''s school fees', 'school fees next year', 'fees next year', 'save for my child']::text[],
  'The goal sentence: a number, a date, a monthly amount',
  'A goal you cannot say in one sentence will not get saved for. Write it as: what, how much, by when. Find the real cost from a quote, a letter from the school, or last year''s receipt, never a guess. Count the months to the date and divide: that is the monthly number. If it does not fit pot 2 of your month plan, move the date, not the plan; a goal that needs a loan at the end is not a goal. Then automate it on payday into the vehicle that fits. The December-and-January trap catches most households: school fees, uniforms and the holiday arrive together, so that goal starts in February, not November.',
  'you have something you want to pay for in the next year or two and no number for it yet',
  'you have no cushion and expensive debt; the goal waits until those are handled',
  ARRAY['Write what the goal is in one line, like ''school fees and uniform for January 2027''', 'Find the real cost: ask the school for the fee letter, get a quote, or take last year''s receipt; write the number', 'Count the months between now and the date, and divide the cost by the months; that is the monthly number', 'Check it against pot 2 of the month plan; if it does not fit, move the date further out or lower the cost, never borrow the difference', 'Open or name a GoalSave or savings pocket for it and set the monthly number to move the day after payday', 'Never raid it for a want, and never plan the big January goal to start in November; start it in February and the month never feels it']::text[],
  'free',
  'low',
  '2026-10-30'::date
)
