-- k.partner_money (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.partner_money',
  'ZA',
  'family_money',
  ARRAY['stretching', 'steady', 'building']::text[],
  ARRAY['share the bills', 'split the bills', 'joint account', 'one account', 'partner', 'husband', 'wife', 'boyfriend', 'girlfriend', 'my husband hides money', 'hides money from me', 'what are my rights', 'married in community', 'community of property', 'fairly', 'who pays what', 'household budget together', 'couple money']::text[],
  'Money with a partner: who pays what, and what is yours',
  'Decide together, once, who pays which bills, in writing, and keep one account each for your own money even if you also share one. Fair is not always half-half: splitting the shared bills in the same proportion as what each of you earns leaves both of you with something. If you are married, your marriage contract decides who owns what and who answers for whose debts, and that matters more than whose name is on the account. If you do not know how you are married, or your partner is hiding money or running up debt in both your names, Legal Aid SA gives free advice to people who qualify, and nobody there is selling anything.',
  'you live with a partner and the bills, the accounts or the debts are shared or argued about',
  'you are single, or the question is about family outside your own household (see the family line)',
  ARRAY['Write every household bill in one list with who pays it now', 'Agree one way to split the shared bills, in the same proportion as what each of you brings in, and write it down', 'Keep one account each for your own money; if you share an account, it holds only the shared bills', 'Find out how you are married (your marriage certificate or the contract says), because that decides whose debt is whose', 'If money is being hidden or debt made in your name, ask Legal Aid SA whether you qualify for free advice before you sign anything']::text[],
  'Free; Legal Aid SA advice is free for people who qualify',
  'A debt made in a joint estate is both of yours; a shared account with no rules is the commonest money fight',
  '2026-10-30'::date
)
