-- k.maintenance_claim (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.maintenance_claim',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['maintenance', 'child maintenance', 'maintenance court', 'father doesn''t pay', 'father does not pay', 'doesn''t pay maintenance', 'child support from the father', 'ex won''t pay', 'maintenance order', 'claim maintenance', 'baby daddy', 'support for my child', 'the father must pay', 'garnish his salary for maintenance']::text[],
  'Child maintenance: the court does it free, no lawyer needed',
  'A child''s other parent must help pay for the child, and you do not need a lawyer or any money to make it happen. The maintenance office at your nearest magistrate''s court takes the application free, calls the other parent in, and the court can order a fixed monthly amount and, if it is not paid, have it taken straight from their salary. Bring your ID, the child''s birth certificate, proof of what the child costs you each month, and whatever you know about where the other parent works. It takes time, so start now rather than waiting for a promise.',
  'the child''s other parent is not contributing, or pays only sometimes',
  'a maintenance order already exists and is being paid (then the question is enforcement, same office)',
  ARRAY['Go to the maintenance office at the magistrate''s court nearest to where you live and ask to apply for maintenance', 'Take your ID, the child''s birth certificate, and proof of the child''s monthly costs (school, food, clothes, transport, medical) with receipts where you have them', 'Give the other parent''s name, ID number if you know it, address and where they work', 'Attend the date the court gives; the court can set a monthly amount and order it deducted from their pay', 'If an order exists and is not paid, go back to the same office with the order number and ask for enforcement']::text[],
  'Free at the maintenance office; no lawyer is needed',
  'Money the child is entitled to, every month, is the cheapest income in the house to claim',
  '2026-10-30'::date
)
