-- k.creditor_arrangement (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.creditor_arrangement',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady']::text[],
  ARRAY['lower instalment', 'smaller instalment', 'pay less each month', 'payment arrangement', 'arrangement with the bank', 'write to a creditor', 'letter to the bank', 'ask for more time', 'reduce my repayment', 'can''t afford the instalment', 'restructure', 'payment plan', 'negotiate with creditors', 'renegotiate']::text[],
  'Asking a creditor for a smaller instalment, in writing',
  'Before you miss a payment, ask the creditor in writing for a smaller instalment for a fixed number of months, say what you can pay, and keep paying that amount from the day you ask. Most lenders have a hardship or arrangements team whose job this is, and a written offer you kept to is the thing that protects you if it ever goes further. Keep every reply. If more than one creditor cannot be paid, the formal route is debt review through a registered debt counsellor, which stops the collectors while it runs; do not pay anyone who promises to make the debt disappear.',
  'you can pay something but not the full instalment, on one or two accounts',
  'you cannot pay anything at all on several accounts (then read the debt review entry)',
  ARRAY['Work out what you can pay each month on that account without missing food, rent or transport', 'Write to the creditor (email or their app''s message channel): your account number, that you cannot afford the full instalment, the amount you can pay, and for how many months', 'Pay that amount on the usual date from this month, whether or not they have replied', 'Keep the letter and every reply in one place on your phone', 'If they refuse and you have more than one account you cannot pay, ask a registered debt counsellor about debt review before the collectors start']::text[],
  'Free to ask; a debt counsellor''s fees are set by the NCR (see the debt review entry)',
  'A missed payment with no arrangement is what starts the collectors and the credit-record listing',
  '2026-10-30'::date
)
