-- k.prize_sms_scam (ZA)
INSERT INTO public.knowledge_entries (id, country, domain, stages, keywords, title, owner_summary, applies_when, not_when, steps, cost, stakes, verified_on)
VALUES (
  'k.prize_sms_scam',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['won money', 'you have won', 'won a prize', 'prize', 'competition', 'lucky draw', 'pay a fee to claim', 'release fee', 'claim fee', 'sms says i won', 'whatsapp says i won', 'lottery', 'lotto sms', 'prize money', 'do i pay the fee']::text[],
  '"You have won": never pay to receive money',
  'Nobody who is really giving you money asks you to pay a fee, airtime or a deposit first, and no real competition you did not enter can pick you as a winner. A message that says you have won and asks for a fee, your ID number, your bank details or an OTP is a scam, however official the logo looks. Do not reply, do not click the link, and never send money to release money. If you already paid, tell your bank straight away and report it at SAPS; if you gave an ID number, ask SAFPS for free protective registration.',
  'an SMS, WhatsApp, email or call says you have won something and asks you to do anything first',
  'a competition you entered yourself, where the organiser asks for nothing before paying out',
  ARRAY['Do not reply, do not click any link, and do not phone the number in the message', 'Ask one question: did I enter this? If not, it is a scam', 'Never pay a fee, buy airtime, or send an ID number, bank details or OTP to receive a prize', 'If you already paid or sent details, tell your bank''s fraud line now and report at SAPS with the message', 'Block the number and delete the message; if they phone, hang up']::text[],
  'Free',
  'The fee you pay to receive money is money gone, and the details you send are used to open accounts in your name',
  '2026-10-30'::date
)
