-- bank_fraud_report (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'bank_fraud_report',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['report fraud', 'fraud line', 'fraud number', 'block my card', 'block my account', 'money stolen', 'someone took money from my account', 'bank fraud', 'stop my card', 'lost my card', 'stolen card', 'sim swap', 'scammed', 'phishing', 'fraud department', 'capitec fraud', 'fnb fraud', 'absa fraud', 'standard bank fraud', 'nedbank fraud', 'gotyme fraud', 'tymebank fraud', 'freeze my account']::text[],
  'Your bank''s fraud line',
  'you think money has been taken, your phone lost signal for no reason, you shared an OTP or PIN by mistake, or your card or phone is gone',
  'nothing has happened yet and you only want to tighten settings; do that inside the app and save the number for later',
  'every bank runs a 24-hour fraud line that can block your card and account in minutes, and the first call is what limits the loss',
  'free: fraud lines are toll-free or standard-rate and blocking a card costs nothing (checked 2026-10-30)',
  'https://www.sabric.co.za/how-to-stay-safe/',
  'save your bank''s fraud number from the app or the back of your card → if something happens, phone it from any phone → ask for the card and account to be blocked and a fraud case opened → open a SAPS case → register with SAFPS',
  ARRAY['Save the number now, before anything happens, from the back of your card or inside the banking app, never from an SMS: Capitec 0860 10 20 43, FNB 087 575 9444, Standard Bank 0800 222 050, Absa 0860 557 557, Nedbank 0800 110 929, GoTyme (TymeBank) 0860 999 119.', 'If your phone suddenly has no signal, treat it as a SIM swap: phone your network from another phone to stop the swap, then phone the bank''s fraud line and ask them to block the account and the banking profile.', 'If someone phoned ''from the bank'' and you gave an OTP, PIN or approved an app message, hang up and phone the fraud line yourself immediately; do not wait to see if money moves.', 'Tell the agent exactly what happened and ask for three things: block the card, block the account or app profile, and open a fraud case with a reference number; write the reference down.', 'Go to the nearest police station and open a case the same day with that reference; the bank''s investigation and any insurance will ask for the SAPS case number.', 'Register with SAFPS for free Protective Registration on safps.org.za so nobody can open credit in your name, and pull your free credit report a month later to check.', 'Never give your PIN, password or OTP to the person who phones you, even if they know your name and ID number; the real bank''s fraud desk never asks for them.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open your banking app, find the fraud or ''report fraud'' number, and save it in your phone as ''Bank fraud line'' right now, then switch on transaction notifications in the app.'
)
