-- cdc_register (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'cdc_register',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['debt collector', 'council for debt collectors', 'cfdc', 'is this collector registered', 'check debt collector', 'complain about a debt collector', 'collector harassing me', 'collection agency', 'collector fees', 'report a debt collector', 'debt collectors act', 'collector register', 'sworn complaint', 'affidavit', 'collector threatened me']::text[],
  'Council for Debt Collectors register and complaints',
  'a collector or agency is contacting you and you want to check they are real, or they have threatened you, phoned your employer or added fees',
  'the person is the original lender or their attorney acting under a court order; those complaints go to the NCR, the ombud or the court',
  'every debt collector must be registered with the Council; the register tells you in a minute whether the person phoning you is allowed to, and the Council disciplines the ones who break the rules, free',
  'free: checking the register and lodging a complaint cost nothing (Council for Debt Collectors FAQ, checked 2026-10-30)',
  'https://www.cfdc.org.za/faqs/',
  'ask the collector for their registration number → check it on cfdc.org.za or by phone → keep a log of every call → if rules are broken, write a sworn complaint → send it to the Council',
  ARRAY['Ask the caller for their full name, the company, and their Council for Debt Collectors registration number; a registered collector has one and will give it.', 'Check it on the Council''s website at cfdc.org.za or phone the Council on 012 804 9808 and ask whether that name and company are registered; an unregistered collector is committing a criminal offence and you need not deal with them.', 'Start a log in your notes app: date, time, name, what was said; it becomes the evidence if they threaten you, phone your family or employer, or pretend to be a sheriff.', 'Ask in writing for a full statement of the debt showing the original amount, payments, interest and every fee; collector fees are limited to the regulated tariff.', 'If a rule is broken, write a complaint as an affidavit: what happened, when, who, what you want done; sign it in front of a commissioner of oaths (any police station does this free).', 'Send it to the Council by email to info@cfdc.org.za or through the complaint form on cfdc.org.za, with your call log and any SMSes attached; the Council notifies the collector and investigates.', 'Never pay cash to a collector at your door and never give card details over the phone; pay only into the account on the written statement, and only what you agreed in writing.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Message the collector who last contacted you: ''Please send me your Council for Debt Collectors registration number and a written statement of the account.'' Then check the number on cfdc.org.za.'
)
