-- debicheck (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'debicheck',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['debicheck', 'debit order', 'approve debit order', 'debit order approval', 'stop debit order', 'dispute debit order', 'reverse debit order', 'change debit order date', 'debit order bounced', 'unpaid debit order', 'unknown debit order', 'mandate', 'debit order sms', 'authenticate debit order', 'cancel debit order', 'debit order went off twice']::text[],
  'DebiCheck and debit order control in your banking app',
  'you have debit orders for debts, policies or accounts and want them timed for payday and nothing unexpected going off',
  'you have no bank account; cash payments are controlled by the envelope, not the app',
  'a DebiCheck mandate is a debit order you approved in your own app, so nothing new can be collected without you, and the same screen lets you dispute and reverse one that is wrong',
  'free to approve, move and dispute debit orders; a declined debit order costs a fee set by your bank (GoTyme publishes R3; check yours) and the dispute window is 60 days from 13 April 2026 (checked 2026-10-30)',
  'https://www.standardbank.co.za/southafrica/personal/products-and-services/security-centre/bank-safely/debicheck',
  'open the debit orders screen in your banking app → list every mandate → move each date to the day after money lands → approve only mandates you recognise → dispute any wrong debit within 60 days',
  ARRAY['Open your banking app and find ''Debit orders'' or ''DebiCheck'' (Capitec: Transact, Debit orders; FNB: My Bank Accounts, Debit orders; Standard Bank: Transact, Debit orders; Absa, Nedbank and GoTyme have the same under the account menu).', 'Write every debit order on your month plan: company, amount, date. Anything you do not recognise goes on a dispute list.', 'Phone each company and move its date to the day after your money lands; most change it on the call, and a debit order that lands before payday is the one that bounces and costs a declined fee.', 'When a DebiCheck approval request arrives by SMS or in the app, check the company, the amount and the date against your list before you tap Approve; decline anything unknown, and a lender cannot collect without the approval.', 'For a debit you never agreed to, open it in the app and choose Dispute (FNB and Absa let you dispute in-app; amounts over R200 at some banks need the call centre); from 13 April 2026 the window is 60 calendar days after the debit.', 'Phone the company the same day and cancel the agreement in writing, or the debit returns next month; a disputed DebiCheck that matched what you approved will usually not be reversed, so approve carefully.', 'If the company keeps debiting, lodge a free complaint with the National Financial Ombud on 0860 800 900; never close the account to escape a debit order, the debt follows you.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open your banking app, go to Debit orders, and write down every one with its date; circle any that go off before your payday and phone that company tomorrow to move it.'
)
