-- experian_free_report (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'experian_free_report',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['experian', 'experian credit report', 'experian free report', 'up experian', 'my credit check', 'mycreditcheck', 'compuscan', 'experian dispute', 'check my credit score experian', 'experian whatsapp', 'free credit report', 'credit report', 'credit score']::text[],
  'Experian free credit report (Up platform)',
  'you want to see what lenders see and dispute what is wrong, on your phone, with no payment',
  'you have never had any account, loan or contract; the bureau may hold no file on you yet',
  'Experian is one of the big registered bureaus and gives your report free through its Up platform, with disputes logged on the same site, and its WhatsApp line for consumer queries',
  'free: Experian provides free access to your report through Up, and the NCA guarantees one free report a year from each bureau (checked 2026-10-30)',
  'https://www.experian.co.za/consumer/my-free-credit-check-and-your-free-credit-report',
  'go to up.experian.co.za → register with your own ID details → verify by OTP → view and download the report → dispute wrong items on the same platform',
  ARRAY['On your phone open up.experian.co.za (Up, Powered by Experian); registration is free and you will be asked for your South African ID number on their site, not anywhere else.', 'Create a login with your email and cellphone number and confirm the OTP they send.', 'Open your credit report and read the accounts list first: mark any account you do not recognise, any account with no payment for 3 years, and anything paid that still shows as owing.', 'Download or screenshot the report and keep it in a folder on your phone with the date; you will compare it in 3 months.', 'To dispute an item, use the dispute option on the same platform: name the account, say what is wrong, attach your paid-up letter or statement; Experian must investigate free within 20 business days under section 72 of the National Credit Act.', 'If the site cannot verify you, message Experian''s consumer WhatsApp on +27 79 127 4906 or use the contact page on experian.co.za.', 'Never use a lookalike site that asks for a card to ''release'' your free report; the free report under the National Credit Act never needs a card.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open up.experian.co.za on your phone, register with your email and cellphone number, and open your report; mark anything you do not recognise.'
)
