-- fsca_check (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'fsca_check',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['fsca', 'fsp number', 'is this company registered', 'is this company licensed', 'check investment company', 'check insurer', 'check financial advisor', 'licensed financial service provider', 'forex scam', 'investment scam', 'ponzi', 'verify fsp', 'fsca search', 'fsca toll free', 'funeral insurer registered', 'financial services board', 'fsb']::text[],
  'FSCA licence check',
  'someone is offering you an investment, trading group, funeral policy or ''advisor'' service and you want to know if it is real before any money moves',
  'the money is going to your own bank''s savings product inside its app; the bank is already licensed',
  'anyone selling investments, insurance or financial advice must be licensed by the FSCA; the register tells you in two minutes whether the name and the FSP number match, and scammers borrow real numbers',
  'free: the FSCA register and the 0800 110 443 line cost nothing (checked 2026-10-30)',
  'https://www.fsca.co.za/',
  'ask for the registered name and FSP number → search the FSCA register on fsca.co.za or phone 0800 110 443 → check the name matches the number and the licence covers that product → check the licence is current',
  ARRAY['Ask the person or company, in writing, for their registered name, their FSP number and the name of the individual''s own licence; a real provider sends it without fuss.', 'Go to fsca.co.za on your phone and find the ''FSP search'' (also reachable at fsca.co.za/Fais/Search_FSP.htm) and search by the FSP number.', 'Check 3 things on the result: the name on the register is the same as the name you were given, the licence status is active, and the categories cover the product you are being sold (a short-term insurance licence does not cover investments).', 'If you cannot use the site, phone the FSCA on 0800 110 443 and ask them to confirm the name and number; it is free.', 'If the number is not found, belongs to another company, or the licence has lapsed, stop: do not send money, and keep the messages as evidence.', 'Report a fake or borrowed licence to the FSCA by phone or on their site, and warn the person who introduced you.', 'Never accept ''we are exempt from licensing'' or ''registered with CIPC'' as proof; a CIPC company number is not a financial services licence.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Message the person offering you the investment: ''Please send me your FSP number and registered company name.'' Then search the number on fsca.co.za before you reply.'
)
