-- gotyme_everyday (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'gotyme_everyday',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['gotyme', 'go tyme', 'tymebank', 'tyme bank', 'gotyme account', 'everyday account', 'gotyme fees', 'gotyme app', 'open gotyme account', 'kiosk', 'pick n pay kiosk', 'boxer kiosk', 'cash at till', 'withdraw at till', 'gotyme card', 'zero monthly fee', 'cheapest bank account', 'bank with no fees', 'send money gotyme', 'sendmoney', 'gotyme statement']::text[],
  'GoTyme Bank EveryDay account',
  'you pay a monthly account fee or ATM fees now, or you have no bank account and want one that costs nothing to hold',
  'you need a branch to walk into for every query; GoTyme is app, kiosk and phone, not branches',
  'a transactional account with no monthly fee, opened in the app in minutes with cash in and out at Pick n Pay and Boxer tills, so moving your own money stops costing you',
  'R0 monthly fee on GoTyme''s published fee page; small per-use fees for some actions (for example R3 for a declined debit order); published figures differ for till cash and SendMoney, so confirm in the GoTyme app (checked 2026-10-30)',
  'https://gotyme.co.za/personal/bank-account/current-account/fees-and-charges',
  'download the GoTyme Bank app → open the account with your ID → collect or activate your card at a Pick n Pay or Boxer kiosk → move your debit orders and income → check the fee page in the app',
  ARRAY['Download the GoTyme Bank app from the official app store (the bank was TymeBank until January 2026; existing TymeBank customers were moved over and the old app is being retired) and open an account with your ID; the bank says it takes under five minutes.', 'Read the fees screen in the app before you use it: GoTyme''s published fee page lists a free current account with no monthly charge, free card purchases, and small fees for some things, such as R3 for a declined debit order and a fee for a SendMoney voucher to someone without a GoTyme account; the app is the source, so confirm there.', 'Get your card at a Pick n Pay or Boxer kiosk, and use the supermarket till for cash withdrawals and deposits rather than an ATM; ask the kiosk what the till fee is, since the published pages differ.', 'Move your income to the account: give your employer or SASSA the new account details (SASSA changes bank details at its office, not by phone), and move your debit orders to the day after money lands.', 'Use PayShap or SendMoney inside the app for payments to people; GoTyme was reported to charge R0 for PayShap, confirm in the app.', 'Download a statement from the app at the end of the month and add up every fee line; the number should be close to zero.', 'Never give your app PIN or an OTP to anyone who phones, and save GoTyme''s fraud line 0860 999 119 from the app.']::text[],
  '2026-10-30'::date,
  TRUE,
  'NO_MONTHLY_FEE',
  'Download the GoTyme Bank app, start the account opening with your ID beside you, and read the fees screen before you finish so you know what every action costs.'
)
