-- gotyme_goalsave (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'gotyme_goalsave',
  'ZA',
  'cushion',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['goalsave', 'goal save', 'gotyme savings', 'tymebank goalsave', 'savings pocket', 'save in the app', '10 percent interest', 'notice savings', 'separate savings', 'emergency fund account', 'where to save my money', 'open goalsave', 'recurring transfer to savings', 'automatic savings', 'gotyme save', 'savings goal account']::text[],
  'GoTyme GoalSave',
  'you bank with GoTyme and want the cushion or a goal kept apart from spending money, growing by itself on payday',
  'you bank elsewhere; your own bank''s savings pocket does the same job, the separation is what matters',
  'a free savings pocket inside the GoTyme app, separate from the everyday money, with interest from day one and a 10-day notice option that is exactly the speed bump a cushion needs',
  'free to open; GoTyme''s own GoalSave page describes 6% a year rising to 10% a year with 10 days'' notice, up to 20 GoalSaves and R250,000 combined; published tiers differ, so confirm in the GoTyme app (checked 2026-10-30)',
  'https://gotyme.co.za/personal/save-and-invest/goalsave',
  'open the GoTyme app → tap Save, then GoalSave → name it and set the target → move the first amount today → set a recurring transfer for the day after payday',
  ARRAY['Open the GoTyme Bank app, tap ''Save'' and choose ''GoalSave''; opening one is free and you can have several (GoTyme''s page says up to 20, with a combined cap of R250,000).', 'Name it for its job, ''Cushion'' or ''School fees'', and type the target number from your plan; the name is what stops you spending it.', 'Read the interest terms on the screen at that moment: GoTyme''s GoalSave page describes 6% a year from day one and up to 10% a year if you give 10 days'' notice before closing, while other published descriptions differ, so the app is the source.', 'Move the first amount today from your EveryDay account, even R20, so the pocket exists before payday.', 'Set a recurring transfer to the GoalSave for the day after your money lands, for the amount in pot 2 of your month plan.', 'When you need the money, choose the notice option if you can wait 10 days to earn the full interest; immediate withdrawal is allowed but may pay less.', 'Never borrow to put money into a GoalSave; no savings rate beats the interest on a loan.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open the GoTyme app, tap Save, open a GoalSave called ''Cushion'', and move R20 into it right now so it exists before payday.'
)
