-- municipal_indigent_register (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'municipal_indigent_register',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching']::text[],
  ARRAY['indigent', 'indigent register', 'indigent application', 'free basic services', 'free electricity', 'free water', 'municipality', 'municipal office', 'customer care centre', 'rates rebate', 'pensioner rebate', 'cannot afford municipal bill', 'municipal arrears', 'apply for free electricity', 'register as indigent', 'ekurhuleni indigent', 'city of johannesburg indigent', 'cape town indigent', 'ethekwini indigent']::text[],
  'Municipal indigent office',
  'household income is low, someone gets a grant or pension, and you pay for electricity, water or rates',
  'your household income is clearly above your municipality''s published limit; ask anyway if you are not sure, the limits differ widely',
  'the municipality''s own office is the only place that can put your household on the indigent register, and that register is what unlocks free basic electricity, water and rates relief every month',
  'free to apply; usually 50 kWh of electricity a month (up to 60 kWh in some municipalities) and a water allowance; the income limit is set by each municipality (checked 2026-10-30)',
  'https://www.eskom.co.za/distribution/free-basic-electricity/',
  'find your municipality''s customer care or indigent office → ask for the indigent application form and the income limit → bring ID, proof of income, a municipal statement or prepaid token and bank statements → apply → claim the free token every month',
  ARRAY['Find your municipality''s customer care centre or indigent office (the address is on your municipal statement, on the municipality''s website, or ask at the ward councillor''s office).', 'Ask for the ''indigent register'' or ''free basic services'' application form and the current income limit; it is set by your municipality (Ekurhuleni published about R10,479 a month in 2026, many smaller towns far less).', 'Take your ID, proof of income or an affidavit that you have none (the office or a police station commissions it free), your latest municipal statement or a prepaid electricity token, and 3 months of bank statements if you have an account.', 'If the property is not in your name, bring a letter or affidavit from the owner saying you live there.', 'Hand in the form and ask for a receipt with the date; approval can take a few months, so ask when to come back.', 'Once approved, ask how to claim the free electricity: Eskom-supplied households dial *130*269# on the first of each month, municipal customers get it where they buy electricity; the free units do not carry over.', 'Diary the renewal date; most registers lapse after a year if you do not reapply, and never pay anyone to ''fast-track'' the application.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOR_QUALIFYING_USERS',
  'Find your municipality''s customer care number on your last municipal statement or its website and phone to ask for the indigent income limit and the documents they want.'
)
