-- nasasa_stokvel (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'nasasa_stokvel',
  'ZA',
  'family_money',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['nasasa', 'stokvel', 'register stokvel', 'stokvel constitution', 'sample constitution', 'stokvel rules', 'is my stokvel registered', 'report a stokvel', 'stokvel scam', 'stokvel association', 'start a stokvel', 'stokvel bank account', 'burial society rules', 'savings club constitution']::text[],
  'NASASA (National Stokvel Association of South Africa)',
  'you belong to or run a stokvel, burial society or savings club and want written rules, registration, or to check a group you have been invited to',
  'the ''stokvel'' promises returns or pays for recruiting; that is a pyramid scheme and the report goes to the National Consumer Commission, not NASASA',
  'NASASA is the self-regulatory body for stokvels under a Banks Act exemption; it has a sample constitution, registers groups, and takes reports about fake ones, which is the fastest way to tell a stokvel from a scheme',
  'free to contact; older sources say NASASA membership has no fee, confirm with NASASA on 010 007 2129 (checked 2026-10-30)',
  'https://nasasa.co.za/',
  'get the sample constitution from NASASA → adopt it at a meeting → open a bank account in the stokvel''s name with 2 or 3 signatures → apply to register by email → show the books at every meeting',
  ARRAY['Phone NASASA on 010 007 2129 or email info@nasasa.co.za and ask for the sample constitution and the registration form; sources differ on whether registration is required below R100,000 in contributions, so ask them.', 'At the next meeting, go through the constitution and fill in your group''s own rules: members, contribution and date, how and when payouts happen, what happens when someone leaves or dies, and who signs for the money.', 'Open a bank account in the stokvel''s name needing 2 or 3 signatures (most banks have a stokvel account); money never sits in the treasurer''s personal account or in cash.', 'Email the completed form and constitution to info@nasasa.co.za and keep the reply; ask whether there is a fee, since older sources say there is none.', 'Show the bank statement and the contributions book at every meeting, and give every member a signed receipt line for every contribution.', 'If you have been invited to a group and want to check it, ask NASASA whether it is registered, and read the constitution yourself before paying anything.', 'Never hand a bank card or PIN to the treasurer and never pay a contribution without a receipt in the book.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Email info@nasasa.co.za and ask for the sample stokvel constitution and the registration form, then read your own group''s rules against it.'
)
