-- ncr_complaint (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'ncr_complaint',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['ncr', 'national credit regulator', 'complain about lender', 'report a lender', 'report mashonisa', 'unregistered lender', 'reckless lending complaint', 'overcharged interest', 'ncr complaint', '0860 627 627', 'form 29 complaint', 'complaints@ncr.org.za', 'credit provider complaint', 'lender broke the law', 'report loan shark', 'ncr registered', 'check ncrcp', 'debt counsellor complaint']::text[],
  'National Credit Regulator complaints line',
  'a lender or debt counsellor has overcharged you, lent recklessly, is unregistered, or is holding your card or ID',
  'the complaint is about a bank account, an insurer or a bureau that will not fix a listing; those go to the National Financial Ombud',
  'the NCR is the regulator for every lender and debt counsellor; it is free, it checks registration numbers, and it acts on unregistered lenders, overcharging and reckless credit',
  'free: the complaint line, the register check and form 29 cost nothing (NCR, checked 2026-10-30)',
  'https://ncr.org.za/index.php/departments/complaints',
  'first raise it with the lender in writing → gather the agreement, statements and messages → phone 0860 627 627 or email complaints@ncr.org.za → fill in form 29 → keep the reference',
  ARRAY['Write to the lender or counsellor first: what is wrong, what you want, and a date; the NCR asks whether you tried, and the letter becomes evidence.', 'Gather the papers: the credit agreement, statements, proof of payments, and every SMS or WhatsApp; take photos with your phone if you have only paper.', 'Phone the NCR on 0860 627 627 (Monday to Thursday 8am to 5pm, Friday to 4:30pm) to check a lender''s or counsellor''s registration and to ask how to lodge; or email complaints@ncr.org.za.', 'Download the complaint initiation form (form 29) from ncr.org.za, fill it in with plain facts and dates, and send it with the papers; if someone lodges for you, they need your signed consent form too.', 'For an unregistered lender (mashonisa) say so clearly: no NCRCP number, the amount lent, what you have paid, and whether they hold your card or ID; the NCR investigates unregistered lending.', 'Write the reference number down and follow up by phone after 20 business days if you have heard nothing.', 'Never pay anyone to lodge a complaint for you, and be careful of emails or SMSes claiming to be from the NCR; the NCR has warned of a cyber-attack on its systems, so confirm contact details on ncr.org.za.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Phone 0860 627 627 and ask whether the lender or counsellor you are dealing with is registered; give the name and ask for the registration number.'
)
