-- ncr_debt_counsellor (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'ncr_debt_counsellor',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching']::text[],
  ARRAY['debt counsellor', 'find a debt counsellor', 'registered debt counsellor', 'ncrdc', 'debt review', 'apply for debt review', 'debt counselling near me', 'verify debt counsellor', 'is my debt counsellor registered', 'debt review company', 'debt counsellor fees', 'form 16 debt review', 'debt counsellor register', 'ncr register', 'debt review application']::text[],
  'NCR register of debt counsellors',
  'your repayments are more than your income can carry and you are ready to find out about debt review from someone registered',
  'you can cover every minimum from your income; the snowball clears it without fees or a listing',
  'only a debt counsellor registered with the NCR can put you under debt review, and the public register is the one way to tell a real counsellor from a removal scam before you sign Form 16',
  'free to search; debt review itself costs an application fee of R50 plus a restructuring fee capped by the NCR (published figures differ, R8,000 to R9,000) and a monthly aftercare fee of 5% with a cap; confirm on ncr.org.za (checked 2026-10-30)',
  'https://www.ncr.org.za/',
  'search the NCR register on ncr.org.za for a counsellor near you → check the NCRDC number and name match → ask the first-call questions → get the fees in writing → sign Form 16 only then',
  ARRAY['Go to ncr.org.za and open the register of registrants; search for debt counsellors in your province and write down 2 or 3 names with their NCRDC numbers, or phone 0860 627 627 and ask for registered counsellors near you.', 'Before any meeting, check that the name and the NCRDC number match on the register and the status is active; the NCR''s Circular 1 of 2024 warns that unregistered people borrow real counsellors'' numbers.', 'Make the first call and ask 3 questions: what are your fees in rand (application R50 plus a restructuring fee the NCR caps, published figures differ, so ask), which registered payment distribution agent do you use, and how long until the court order.', 'Ask for the fee quote and the process in writing before you sign Form 16, the application; a real counsellor sends it.', 'Bring your owed list, your payslips or income proof, your bank statements and your month plan; the counsellor must assess whether you are over-indebted within 30 business days.', 'Once you sign Form 16, the counsellor sends Form 17.1 to every creditor within 5 business days and your payments go through the distribution agent, not into the counsellor''s own account.', 'Never pay an upfront ''consultation'' fee beyond the R50 application, never sign with someone who contacted you first on WhatsApp, and never take new credit once under review; the law does not allow it.']::text[],
  '2026-10-30'::date,
  TRUE,
  'NO_MONTHLY_FEE',
  'Phone the NCR on 0860 627 627 and ask for the names and NCRDC numbers of two registered debt counsellors near you; write them down before you speak to anyone else.'
)
