-- nfo_complaint (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'nfo_complaint',
  'ZA',
  'debt',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['ombud', 'ombudsman', 'national financial ombud', 'nfo', 'banking ombud', 'credit ombud', 'insurance ombud', 'complain about my bank', 'complain about insurer', 'bank won''t help', 'insurer rejected my claim', 'bureau won''t fix my report', 'funeral claim rejected', 'unfair bank charges', '0860 800 900', 'nfosa', 'complaint about credit bureau', 'free complaint', 'dispute with bank']::text[],
  'National Financial Ombud (NFO)',
  'your bank, lender, insurer or a credit bureau has treated you unfairly, rejected a valid claim, or will not fix a wrong listing, and you have complained to them first',
  'you have not yet complained to the company itself; the NFO expects you to give them about 20 working days first',
  'since 1 March 2024 one free ombud handles complaints about banks, lenders, credit bureaus and insurers; it can order refunds, and you do not need a lawyer',
  'free: the National Financial Ombud charges consumers nothing (checked 2026-10-30)',
  'https://nfosa.co.za/',
  'complain to the company in writing and keep the reference → wait up to 20 working days → lodge with the NFO online, by email, WhatsApp or phone → send your evidence → follow the case number',
  ARRAY['Complain to the bank, lender, insurer or bureau first, in writing, and keep the reference number; the NFO will ask for it and gives the company about 20 working days to respond.', 'Gather the evidence: statements, the policy or agreement, your complaint and their reply, and any SMS or WhatsApp; photograph paper documents.', 'Lodge with the NFO: the online form on nfosa.co.za, email info@nfosa.co.za, WhatsApp 076 574 8055 (the number on the NFO''s own site; older bank pages show a different one), or phone 0860 800 900.', 'Write the complaint in plain words: what happened, the dates, what you lost, what you want (a refund, a listing removed, a claim paid), and attach the evidence.', 'Write down the NFO case number and reply to any request for more information within the time they give.', 'The NFO''s decision can be in your favour and the company must act on it; in its first year it reported more than R400 million returned to consumers.', 'Never pay a ''claims consultant'' to lodge for you; the NFO is free and will deal with you directly.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Find the reference number from your complaint to the company, then open nfosa.co.za on your phone and start the online complaint form with it.'
)
