-- nhfc_first_home_finance (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'nhfc_first_home_finance',
  'ZA',
  'goals',
  ARRAY['steady', 'building']::text[],
  ARRAY['first home finance', 'flisp', 'nhfc', 'housing subsidy', 'subsidy calculator', 'apply for flisp', 'first home finance portal', 'government home subsidy', 'first time home buyer', 'home loan subsidy', 'buy a house', 'bond subsidy', 'subsidy application', 'flisp documents']::text[],
  'NHFC First Home Finance portal',
  'a first-time buyer, citizen or permanent resident, with household income of R3,501 to R22,000 a month and a clean enough record to get a home loan',
  'household income is outside R3,501 to R22,000 a month, you have owned property before, or you already received a housing subsidy',
  'the National Housing Finance Corporation runs the First Home Finance subsidy online; its calculator gives your own subsidy number and the portal is the only place to apply without a middleman',
  'free to apply; the subsidy covers household incomes of R3,501 to R22,000 a month, with published 2026 amounts up to R169,264 (figures differ, use the NHFC calculator) (checked 2026-10-30)',
  'https://nhfc.co.za/',
  'use the calculator on nhfc.co.za → clean the credit record → get a home loan quote and tell the bank you will apply → apply on the portal while a window is open → upload the documents and follow the status',
  ARRAY['Open nhfc.co.za on your phone, find First Home Finance and run the subsidy calculator with your gross household income; published 2026 figures differ (a top of R169,264 and a bottom of R27,960 or R38,878), so the calculator is your number.', 'Pull your free credit report and fix what is wrong; a home loan needs months of on-time payments, so start there.', 'Speak to a bank about a home loan and tell them you will apply for First Home Finance; some banks still want an approval in principle before the subsidy application.', 'Check nhfc.co.za for whether the application portal is open: the NHFC closes it between windows and says applications outside a window are not accepted.', 'Register on the First Home Finance online portal and upload what it asks for: ID, proof of income (payslips, or bank statements if you are self-employed), the loan quote, and the consent for NHFC to verify your income with your employer.', 'Follow the status updates the portal sends at each stage and reply to any request within the time given.', 'Never pay anyone to submit for you; the NHFC rejects manual submissions by third parties, and never sign an offer to purchase until the subsidy and the loan are both confirmed in writing.']::text[],
  '2026-10-30'::date,
  FALSE,
  'GOVERNMENT_GRANT',
  'Open nhfc.co.za, find the First Home Finance calculator and type in your household''s monthly income to see the subsidy amount you could qualify for.'
)
