-- notes_money_log (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'notes_money_log',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['notes app', 'notebook', 'write it down', 'money log', 'spending log', 'track my spending', 'track expenses', 'simple budget', 'record my spending', 'list my debts', 'owed list', 'policy list', 'keep a record', 'phone notes', 'google keep', 'samsung notes', 'write down every rand', 'where my money goes']::text[],
  'Your phone''s notes app as a money log',
  'you want to see where the money goes, keep your owed list and policy list, and do it on a prepaid phone with no data',
  'you already keep a full record in a spreadsheet or the bank app and it works for you',
  'the notes app already on your phone is the only tool that works at a taxi rank, with no data, in 10 seconds; a week of lines in it shows more than any budgeting app',
  'free',
  'https://keep.google.com/',
  'open the notes app → make one page per list (Week 1, Owed, Policies, Waiting) → write one line per spend the same day → add up on day 7 → keep the lists where you see them on payday',
  ARRAY['Open the notes app that is already on your phone (Samsung Notes, Google Keep, Apple Notes) and make a page called ''Week 1'' with today''s date.', 'Each time money leaves your hands, write one line the same day: ''taxi R18'', ''airtime R12'', ''bread R19''; include cash, the small things and money given to a child.', 'On day 7, add it up, write the total at the bottom, and circle the 3 biggest lines; those are where your month plan starts.', 'Make a second page called ''Owed'': one line per debt with who, how much is left, what you pay a month and the interest or fee; put the most expensive at the top.', 'Make a third page called ''Policies'': each funeral policy or society with the premium, the payout, who is covered and the waiting period.', 'Make a fourth called ''Waiting'' for anything unplanned you want to buy; it waits there 24 hours before any money moves.', 'Pin the pages or put them in a folder called ''Money'', and never store a PIN, password or card number in a note; the notes app is not a safe.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open your phone''s notes app, make a page called ''Week 1'' with today''s date, and write down everything you have spent today, one line each.'
)
