-- payshap (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'payshap',
  'ZA',
  'spending',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['payshap', 'pay shap', 'shapid', 'shap id', 'pay by cellphone number', 'instant payment', 'send money', 'send money to family', 'transfer money', 'cheapest way to send money', 'ewallet', 'cash send', 'pay someone', 'rtc fee', 'immediate payment', 'instant eft', 'pay my stokvel', 'register shapid', 'request money']::text[],
  'PayShap',
  'you send money to people, pay a stokvel or a share of groceries, and want it instant and cheap without a voucher or a branch',
  'the person has no bank account at all; a cash voucher or the till is the only route then',
  'instant payments to a cellphone number through your own banking app, free or near-free below R100 at most banks, which is where family money and small bills live',
  'free at some banks and mostly free or near-free under R100, up to about R7.50 a payment at others; fees are set by each bank and change, so confirm in your bank''s fee guide (checked 2026-10-30)',
  'https://www.payshap.co.za/',
  'open your banking app → find PayShap → register your ShapID (your cellphone number) → ask the person for theirs → send a R10 test → move your small regular payments to it',
  ARRAY['Open your banking app and find ''PayShap'' or ''Pay by cellphone number'' (Capitec: Transact, PayShap; FNB: Pay, PayShap; Standard Bank, Absa, Nedbank and GoTyme under Pay or Transfers).', 'Register your ShapID: your cellphone number linked to this account, so people can pay you by number; it is free.', 'Look up the PayShap fee in your bank''s fee guide in the app: many banks charge R0 under R100 (TymeBank/GoTyme was reported free at every amount; Absa and Standard Bank charge more above R100), and the per-payment limit is R3,000 at some banks and higher at others.', 'Ask the person you pay to register their ShapID too; at Absa and Nedbank a payment to a ShapID is cheaper than one to an account number.', 'Send R10 as a test and confirm it arrived instantly; then move your fixed family amount, stokvel contribution and other small payments to PayShap in amounts under R100 where the free rule applies.', 'Use ''Request money'' where your bank has it to be paid back by family or for a shared cost; it is cheaper than chasing cash.', 'Never pay a stranger by PayShap for something you have not received; it is instant and cannot be reversed, which is why scammers ask for it.']::text[],
  '2026-10-30'::date,
  TRUE,
  'NO_MONTHLY_FEE',
  'Open your banking app, find PayShap, register your cellphone number as your ShapID, and send R10 to a family member to see it land.'
)
