-- safps_protective_registration (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'safps_protective_registration',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['safps', 'protective registration', 'identity theft', 'id stolen', 'lost id', 'someone opened an account in my name', 'fraud in my name', 'register my id', 'fraud prevention service', 'impersonation', 'stolen phone', 'lost wallet', 'id copy leaked', 'protect my identity', 'fraud victim']::text[],
  'SAFPS Protective Registration',
  'your ID, passport or phone is lost or stolen, an account was opened in your name, or you sent your ID copy to someone you now distrust',
  'nothing has been lost or stolen and your credit report is clean; still free, but pull the report first',
  'a free marker against your identity on the fraud-prevention database that every member bank and lender checks, so a credit application in your name triggers a check that it is really you',
  'free: Protective Registration costs nothing and the reference number is issued within about 48 hours (SAFPS, checked 2026-10-30)',
  'https://www.safps.org.za/Home/OurServices_ApplyProtectiveRegistration',
  'get a SAPS case number → apply on safps.org.za, by email or by phone → send a certified ID copy with the form → get the reference within 48 hours → dispute any accounts that are not yours',
  ARRAY['Report the lost or stolen ID, or the account you did not open, at the police station and get the case number; SAFPS and the banks ask for it.', 'Go to safps.org.za, open ''Apply for Protective Registration'' and fill in the form; or email the completed form with a certified copy of your ID to protection@safps.org.za; or phone SAFPS on 011 867 2234.', 'Get an ID copy certified free at any police station; some guides also ask for proof of address, so take one along.', 'SAFPS issues a Protective Registration reference number within about 48 hours; save it with your case number.', 'If a lender already opened credit in your name, ask them in writing for a letter confirming the impersonation; with it, SAFPS can also list you as a victim of impersonation.', 'Pull your free credit report from each bureau and dispute every account that is not yours, quoting the SAPS case number and the SAFPS reference.', 'Never post a photo of your ID in a WhatsApp group and never send a copy to a ''job agent'' or a ''loan agent''; a copy is all a fraudster needs.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open safps.org.za on your phone, find ''Apply for Protective Registration'', and start the form with your ID beside you; it is free.'
)
