-- saps_case (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'saps_case',
  'ZA',
  'protection',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['police', 'saps', 'open a case', 'case number', 'police station', 'report to the police', 'threatened', 'intimidation', 'mashonisa threats', 'they took my card', 'stolen', 'theft', 'fraud case', 'affidavit', 'sworn statement', '10111', 'crime stop', 'police refuse to open case', 'cas number']::text[],
  'Open a case at SAPS',
  'someone is threatening you, holding your card or ID, has stolen from you, or has used your identity',
  'the problem is a civil debt with no threat or crime; that goes to the NCR, the ombud or a debt counsellor',
  'a police case number is what a bank, an insurer, SAFPS and the NCR all ask for, and it is the record that turns a mashonisa''s threat or a stolen card into something the law can act on',
  'free: opening a case, a statement and a certified copy at a police station cost nothing (checked 2026-10-30)',
  'https://www.saps.gov.za/',
  'go to the nearest police station (any one, not only your area) → give a statement → get the CAS number → keep it with your other references → ask for the investigating officer''s name',
  ARRAY['Go to the nearest police station; any station must open the case even if the crime happened in another area, and for an emergency phone 10111.', 'Tell the officer at the desk you want to open a case and give a statement; bring your ID, any messages or screenshots, and for a stolen card the bank''s fraud reference.', 'Give the facts in order with dates and names; the officer writes it as a statement you sign, so read it before you sign.', 'Ask for the CAS (case) number before you leave and write it down; without it there is no case.', 'Ask for the name of the investigating officer and the station''s number so you can follow up the next working day.', 'If the desk refuses to open a case, ask calmly for the shift commander, or phone the SAPS National Complaints line on 0800 333 177; nobody may be refused a case.', 'Give the CAS number to your bank, SAFPS and the NCR; and never pay anyone at the station or anyone who offers to ''make the docket move''.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Put your ID, your phone with the screenshots, and the bank''s fraud reference in one place, and look up the address of the nearest police station; go today, not tomorrow.'
)
