-- sars_efiling (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'sars_efiling',
  'ZA',
  'income',
  ARRAY['stretching', 'steady', 'building']::text[],
  ARRAY['sars', 'efiling', 'sars efiling', 'mobiapp', 'sars app', 'tax return', 'file my tax', 'auto assessment', 'auto-assessment', 'tax refund', 'irp5', 'itr12', 'register for tax', 'tax number', 'sars refund', 'sars contact', '0800 00 7277', 'filing season', 'tax season 2026', 'accept auto assessment']::text[],
  'SARS eFiling and the SARS MobiApp',
  'you have an IRP5 with PAYE deducted, paid medical aid or retirement contributions, or got an auto-assessment SMS from SARS',
  'your only income is a grant or cash piece jobs with no tax ever deducted; there is nothing to refund',
  'the only place a tax refund is claimed; if your employer deducted PAYE and you earned near or under the threshold, or paid medical aid, the refund sits at SARS until you check the auto-assessment or file',
  'free to register and file; the tax threshold was R95,750 for under-65s for the year to 28 February 2026, and the 2026 individual filing deadline was 23 October 2026 (checked 2026-10-30)',
  'https://www.sars.gov.za/individuals/how-to-file-a-return/',
  'register on sars.gov.za or in the SARS MobiApp with your ID → check the auto-assessment against your IRP5 → accept by doing nothing if correct, or file the ITR12 if not → confirm your bank account on your profile → wait for the refund',
  ARRAY['Download the SARS MobiApp from the official app store, or go to sars.gov.za and choose eFiling; register with your ID number and cellphone; if you have no tax number, registration creates one.', 'Get your IRP5 from your employer (or find it already loaded on your SARS profile) and your medical aid tax certificate if you have one.', 'In filing season (for the 2026 year, auto-assessments were issued from 1 to 12 July and individual filing ran from 13 July to 23 October 2026), open your assessment in the app and compare the income and deductions with your IRP5.', 'If it is correct, you do nothing; the refund is paid into the bank account on your SARS profile. If it is wrong, open the ITR12 return in the app, fix it and file before the deadline SARS publishes.', 'Check that the bank account on your profile is in your own name and verified; SARS pays refunds only to a verified account.', 'If you are stuck, phone the SARS Contact Centre on 0800 00 7277 or book a branch visit through the app rather than queueing.', 'Never respond to an SMS or email ''from SARS'' with a link to claim a refund; SARS pays refunds through eFiling, and never pay a ''refund agent'' who found you on WhatsApp.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Download the SARS MobiApp, register with your ID number and cellphone, and look for an auto-assessment or your IRP5 on your profile.'
)
