-- sassa_office (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'sassa_office',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['sassa office', 'sassa', 'apply for grant', 'grant application', 'old age grant application', 'child support grant application', 'disability grant application', 'nearest sassa', 'sassa documents', 'sassa toll free', '0800 60 10 11', 'grant review', 'grant stopped', 'grant suspended', 'change sassa bank details', 'sassa card', 'postbank card', 'report deduction', 'sassa appeal']::text[],
  'Your nearest SASSA office',
  'someone in your household may qualify for an older person''s, child support, disability or foster child grant, or a grant has stopped or is short',
  'your only question is the R370 SRD grant, which is applied for and checked online only',
  'the office is where a permanent grant is applied for, where bank details are changed, and where an unlawful deduction is reported; it is free and the receipt it gives you is proof of the date you applied',
  'free to apply; grant amounts reported for April 2026 are R2,400 (older person), R2,420 from age 75 and R580 per child (child support), from news reports, confirm at the office (checked 2026-10-30)',
  'https://www.sassa.gov.za/',
  'phone 0800 60 10 11 for the nearest office and the documents → gather ID, birth certificates, proof of income and bank statements → apply in person → keep the receipt → follow up after the decision time',
  ARRAY['Phone SASSA''s toll-free line 0800 60 10 11 and ask for the nearest office, its hours, and the exact documents for the grant you want; offices differ in what they ask.', 'Gather the usual papers: your 13-digit ID (or the affidavit SASSA accepts if you have none), the child''s birth certificate for a child grant, proof of income or an affidavit of no income, proof of marital status, and 3 months of bank statements if you have an account.', 'For a disability grant, ask the office about the medical assessment; it is done through SASSA''s doctor and you do not pay for it.', 'Go early, apply in person, and make sure you leave with the receipt showing the date; if approved, the grant is paid from that date.', 'Ask when the decision is due and how you will be told; if it is refused, you have the right to appeal in writing, and the office will tell you the form and the time limit.', 'To change bank details or report a deduction you did not agree to, go to the office with your ID and the statement; deductions can also be disputed by SMS to 34548 with your ID number and the company''s name.', 'Never pay anyone to help you apply or to ''speed up'' a grant; applying is free and SASSA staff may not ask for money.']::text[],
  '2026-10-30'::date,
  TRUE,
  'GOVERNMENT_GRANT',
  'Phone 0800 60 10 11, ask for your nearest SASSA office and the documents needed for the grant someone in your house may qualify for, and write them down.'
)
