-- sassa_srd_online (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'sassa_srd_online',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching']::text[],
  ARRAY['srd', 'srd online', 'srd.sassa.gov.za', 'apply for srd', 'srd status', 'check srd status', 'r370 grant', 'r370', 'sassa srd', 'srd appeal', 'srd declined', 'srd banking details', 'update srd details', 'srd pending', 'srd approved', 'unemployed grant', 'social relief grant']::text[],
  'SASSA SRD online portal (srd.sassa.gov.za)',
  'you are 18 to 59, get no other grant or UIF, have little or no income, and have a cellphone number in your name',
  'you receive another SASSA grant or UIF, or your income is above the threshold SASSA publishes on the site',
  'the R370 grant is applied for, checked and appealed only on this site; it takes a few minutes on a phone and costs nothing',
  'free to apply; the grant is R370 a month to 31 March 2027; the income threshold published by third parties is R624 a month, confirm on srd.sassa.gov.za (checked 2026-10-30)',
  'https://srd.sassa.gov.za/',
  'open srd.sassa.gov.za → apply with your ID number and cellphone number → add banking details in your own name → check status monthly → appeal on the site if declined',
  ARRAY['Open srd.sassa.gov.za on your phone (the only official site; it extends the grant to 31 March 2027) and choose ''Apply''.', 'Enter your ID number and a cellphone number registered in your name; SASSA sends OTPs to it, so keep it active.', 'Add banking details for an account in your own name if you have one; it speeds payment, and you can change them only on this site, never by WhatsApp or phone.', 'Each month, go to ''Check status'' with your ID and cellphone number; SASSA re-checks income every month against bank inflows, so a month can be declined after an earlier approval.', 'If declined, read the reason shown and appeal on the site within the time it shows, attaching proof if the reason is wrong.', 'For general questions, phone SASSA''s toll-free line 0800 60 10 11; SASSA''s WhatsApp line is widely published as 082 046 8553, but confirm it on sassa.gov.za before you trust any number sent to you.', 'Never pay anyone to apply, ''unlock'' or ''fix'' your SRD, and never share your ID number or banking details in a WhatsApp group; the real site asks for nothing but what is above.']::text[],
  '2026-10-30'::date,
  TRUE,
  'GOVERNMENT_GRANT',
  'Open srd.sassa.gov.za on your phone, choose Apply or Check status, and enter your ID number and the cellphone number in your name.'
)
