-- sheets_budget (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'sheets_budget',
  'ZA',
  'spending',
  ARRAY['stretching', 'steady', 'building']::text[],
  ARRAY['spreadsheet', 'google sheets', 'excel', 'budget spreadsheet', 'budget template', 'monthly budget sheet', 'track my budget', 'budget on my phone', 'sheets app', 'plan my month', 'three pots sheet', 'bills list', 'budget planner', 'free budget app']::text[],
  'A Google Sheets month plan',
  'you have a smartphone with some data, income lands once or twice a month, and the notes-app log has shown you where the money goes',
  'you have no data or your phone struggles with apps; the notes app or a notebook does the same job by hand',
  'a free sheet on your phone adds up the three pots for you, so on payday you see in one screen whether the month fits before anything is spent',
  'free',
  'https://www.google.com/sheets/about/',
  'install Google Sheets → make a sheet with 3 sections (Bills, Aside, The rest) → type the amounts from your month plan → add the totals → open it on payday and fill in what landed',
  ARRAY['Install Google Sheets from the official app store (free with a Google account) and create a new sheet called ''Month plan''.', 'In row 1 type the money that lands on payday (after deductions, lowest month if it changes); in the rows below make three blocks with a heading each: ''Bills'' (rent, electricity, every debt minimum, each with its due day), ''Aside'' (cushion transfer, family amount), and ''The rest''.', 'Under each block type the amounts in one column, and at the bottom of each block put a sum formula: =SUM() over that block''s amounts.', 'At the bottom put the calculation that matters: money in, minus Bills, minus Aside; what is left is ''The rest'', and divide it by the weeks to the next payday for a weekly food-and-transport number.', 'On payday, open the sheet, type what actually landed, and pay Bills and move Aside the same day; if the bottom number is negative, that is a debt problem, and the owed list comes first.', 'After 2 weeks, compare the sheet with your notes-app log and fix the lines that did not fit.', 'Never keep account numbers, PINs or passwords in the sheet; amounts and names only.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Install Google Sheets, make a sheet called ''Month plan'', and type the three headings Bills, Aside and The rest with the amounts from your notes-app log.'
)
