-- tfsa_account (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'tfsa_account',
  'ZA',
  'goals',
  ARRAY['steady', 'building']::text[],
  ARRAY['tfsa', 'tax free savings account', 'tax-free savings', 'open a tax free account', 'tax free investment', 'where to open tfsa', 'tfsa for my child', 'tax free unit trust', 'tax free fixed deposit', 'r46000 limit', 'long term savings account', 'save for 5 years', 'education savings', 'retirement extra savings']::text[],
  'A tax-free savings account',
  'you have a cushion, no expensive debt, and a goal years away such as school fees, a deposit or extra retirement savings',
  'you are still building the cushion or paying a mashonisa or store account; a tax-free account is for money you will not touch',
  'the right home for a goal 3 or more years away: no tax on the growth, up to R46,000 a year from 1 March 2026, opened with a bank or investment platform you can check on the FSCA register',
  'free to open at most banks; fees differ by provider (ask); annual limit R46,000 from 1 March 2026, lifetime R500,000, excess taxed at 40% by SARS (checked 2026-10-30)',
  'https://www.sars.gov.za/types-of-tax/personal-income-tax/tax-free-investments/',
  'check the provider on the FSCA register → open the account labelled ''tax-free'' → set a recurring transfer for the day after payday → keep a running total of deposits → never exceed R46,000 a year or R500,000 lifetime',
  ARRAY['Choose a provider: most big banks, unit trust companies and investment platforms offer a tax-free savings account; GoTyme Bank was not reported to offer one as of 2026, so ask your bank or compare a few, and check the provider''s FSP number on fsca.co.za.', 'Ask two questions before opening: what are the fees (a tax-free fixed deposit at a bank usually has none; a unit trust charges a yearly percentage), and is the account registered as tax-free with SARS.', 'Open it in the app or online with your ID and tax number; it must be in your own name (a parent can open one for a child, but the child''s limits are used).', 'Set a recurring transfer for the day after payday for the monthly number in your goal sentence; there is no legal minimum.', 'Keep a running total in your notes app of every deposit ever made across all your tax-free accounts: the limit is R46,000 a tax year (from 1 March 2026) and R500,000 in a lifetime, and SARS taxes anything over at 40%.', 'Leave it alone: withdrawals are allowed, but what you take out never gives you the contribution room back.', 'Never open a second tax-free account without counting the first, and never move money from the cushion into it; the cushion must stay reachable.']::text[],
  '2026-10-30'::date,
  TRUE,
  'UNKNOWN',
  'Open your banking app and search for ''tax-free savings''; if your bank has one, read its fee line, and if not, write down two providers to compare on fsca.co.za tomorrow.'
)
