-- transunion_free_report (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'transunion_free_report',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['transunion', 'transunion credit report', 'transunion free report', 'annual free credit report', 'transunion dispute', 'transunion south africa', 'itc', 'itc check', 'credit report', 'credit score', 'check my credit record', 'transunion contact', '0861 482 482', 'blacklisted check']::text[],
  'TransUnion free annual credit report',
  'you want the report most lenders pull, free, and a place to dispute a wrong listing with evidence',
  'you have never had any account, loan or contract; TransUnion may have no file on you yet, and the site may not verify you',
  'TransUnion is the largest registered bureau; the National Credit Act gives you its report free once a year, and its site has a dispute page for anything wrong',
  'free: one report a year under NCA section 72; TransUnion''s call centre is 0861 482 482 (checked 2026-10-30)',
  'https://www.transunion.co.za/product/annual-free-credit-report',
  'go to transunion.co.za → open the free annual credit report page → register with your own ID details → answer the verification questions or OTP → view the report → use the dispute page for wrong items',
  ARRAY['On your phone open transunion.co.za and find the ''free annual credit report'' page (transunion.co.za/product/annual-free-credit-report); you will be asked for your South African ID number on their site, nowhere else.', 'Register with your details, answer the verification questions or enter the OTP sent to your phone, and the report opens on screen; it may also be emailed to you.', 'Read the accounts first and mark 3 things: any account you do not recognise, any account with no payment for 3 years, and anything paid that still shows as owing.', 'Save a screenshot or the PDF in a folder with the date; you will compare it in 3 months.', 'To dispute, use the ''dispute or query an item'' link on TransUnion''s contact page and attach your paid-up letter, statement or police case number; TransUnion must investigate free within 20 business days under section 72 of the National Credit Act.', 'If the site cannot verify you, phone TransUnion''s call centre on 0861 482 482 and choose the option for an agent.', 'Never pay a ''free credit report'' site that asks for a card, and diary 12 months from today for your next free report from TransUnion.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open transunion.co.za on your phone, find the free annual credit report page, and register with your own details; mark anything on the report you do not recognise.'
)
