-- ufiling_uif (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'ufiling_uif',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['ufiling', 'uif', 'uif online', 'claim uif', 'uif claim', 'unemployment benefit', 'lost my job', 'retrenched', 'ui-19', 'ui19', 'uif documents', 'labour centre', 'department of labour', 'uif status', 'uif payment', 'uif not paid', 'maternity benefit', 'uif call centre']::text[],
  'uFiling (UIF online claims)',
  'you were employed with UIF deducted, lost the job in the last 12 months, and have the UI-19 from your employer',
  'you resigned, were never registered for UIF, or your last day was more than 12 months ago; and it needs an employment record, so it does not work for cash piece jobs',
  'the Department of Employment and Labour''s online portal is where an unemployment claim is lodged without a day in a queue; the same claim can be made at a labour centre if the site fails',
  'free to claim; benefits are 38% to 60% of salary, 1 day per 4 days worked up to 365 days, claim within 12 months (checked 2026-10-30)',
  'https://ufiling.labour.gov.za/',
  'get the UI-19 and salary schedule from your employer → register on ufiling.labour.gov.za → register as a work seeker → apply for unemployment benefits and upload the documents → keep signing the continuation forms',
  ARRAY['Get the completed UI-19 form and a salary schedule from your employer the week you leave; they must give it to you, and nothing starts without it.', 'Open ufiling.labour.gov.za and register with your ID number and the details on your UI-19; if the site is down, the same claim is made at your nearest labour centre.', 'Register as a work seeker when prompted; an unemployment claim requires it.', 'Choose ''Apply for benefits'', then ''Unemployment benefits'', and upload the UI-19, a copy of your ID, your last payslips, and the UI-2.8 banking form with your own bank account details; keep the originals.', 'Lodge within 12 months of your last working day; late claims are turned away.', 'Expect roughly 1 day of benefit for every 4 days worked, up to 365 days, at 38% to 60% of your pay (lower earners get the higher rate), paid in instalments while you submit the continuation forms the portal asks for.', 'If nothing happens after a few weeks, phone the UIF line on 0800 030 007 (the number published for the UIF call centre; some sources give 0800 843 843), and never pay an ''agent'' to claim for you.']::text[],
  '2026-10-30'::date,
  FALSE,
  'FREE_FOR_QUALIFYING_USERS',
  'Message or email your employer: ''Please send me my completed UI-19 and salary schedule so I can claim UIF.'' Then open ufiling.labour.gov.za and start registering.'
)
