-- xds_free_report (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'xds_free_report',
  'ZA',
  'credit_record',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['xds', 'splendi', 'xds credit report', 'xds free report', 'splendi credit report', 'third bureau', 'credit bureau xds', 'free credit report', 'credit report', 'dispute xds', 'xds contact', '0860 937 000']::text[],
  'XDS free credit report (Splendi)',
  'you have pulled TransUnion or Experian and want the third view, or a lender says it used XDS',
  'you have never had any credit or contract; the bureau may have no file on you',
  'XDS is the third big bureau and some lenders report only to it; its free consumer service Splendi shows the report and takes disputes online, so staggering the three bureaus gives you a free look every few months',
  'free: Splendi is XDS''s free consumer service, and the NCA guarantees one free report a year; XDS''s line is 0860 937 000 (checked 2026-10-30)',
  'https://www.xds.co.za/for-me/',
  'go to Splendi via xds.co.za → register with your own ID details → verify → view the report → dispute wrong items online or by phone',
  ARRAY['On your phone open xds.co.za and follow the link to Splendi, XDS''s free consumer service; you will be asked for your South African ID number on their site only.', 'Register with your email and cellphone number and complete the verification they send.', 'Open the report and mark the same 3 things as on the other bureaus: accounts you do not recognise, accounts with no payment for 3 years, and paid accounts still showing as owing.', 'Screenshot or download it with the date and keep it with your TransUnion and Experian reports.', 'Dispute a wrong item on Splendi with your evidence attached, or phone XDS on 0860 937 000; the bureau must investigate free within 20 business days under section 72 of the National Credit Act.', 'If XDS does not answer within 20 business days, complain free to the NCR on 0860 627 627 or the National Financial Ombud on 0860 800 900.', 'Never pay a site that charges for ''your XDS report''; Splendi is free, and the National Credit Act report is free once a year anyway.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOREVER',
  'Open xds.co.za on your phone, follow the Splendi link, and register with your email and cellphone number to see your XDS report.'
)
