-- ccma_referral (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'ccma_referral',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching', 'steady', 'building']::text[],
  ARRAY['ccma', 'refer to ccma', 'unfair dismissal', 'not paid my severance', 'employer owes me money', 'unpaid wages', 'unpaid salary', 'retrenchment dispute', 'labour dispute', '0861 16 16 16', 'lra 7.11', 'ccma form', 'fired unfairly', 'dismissed', 'employer won''t pay', 'notice pay', 'leave pay']::text[],
  'CCMA referral',
  'you were dismissed or retrenched and the severance, notice or leave pay was not paid, or the dismissal was unfair',
  'you were self-employed or doing cash piece jobs with no employer; the CCMA needs an employer to refer against',
  'the Commission for Conciliation, Mediation and Arbitration hears unfair dismissal and severance disputes free, with no lawyer needed, and its case officers help you fill in the form',
  'free: referring a dispute to the CCMA costs nothing, and the statutory severance minimum is 1 week''s pay per completed year (checked 2026-10-30)',
  'https://www.ccma.org.za/',
  'phone 0861 16 16 16 to check the CCMA (or a bargaining council) covers you → fill in form LRA 7.11 → serve a copy on the employer → file it with the CCMA → attend the conciliation date',
  ARRAY['Phone the CCMA on 0861 16 16 16 and describe the dispute; they tell you whether the CCMA or a bargaining council handles it and where the nearest office is.', 'Note the time limit: an unfair dismissal must be referred within 30 days of the dismissal, counting weekends and holidays; a severance-only claim is referred in writing under the Basic Conditions of Employment Act, so do it in the same week.', 'Download form LRA 7.11 from ccma.org.za or get it at the office; the case management officers there help you complete it free.', 'Serve a copy on the employer (by email, fax or hand delivery with proof) and file the original with the CCMA with the proof of service.', 'Bring your contract, payslips, the dismissal or retrenchment letter and any messages to the conciliation; it is a meeting with a commissioner, not a court, and you may speak for yourself.', 'If conciliation fails, the commissioner tells you the next step (arbitration or the Labour Court); for severance, the legal minimum is 1 week''s pay per completed year of service.', 'Never pay a ''labour consultant'' who promises a win, and never sign a ''full and final'' settlement at work without the amounts written on it.']::text[],
  '2026-10-30'::date,
  FALSE,
  'FREE_FOREVER',
  'Phone the CCMA on 0861 16 16 16, say what happened and when, and ask for the referral form and the time limit that applies to you.'
)
