-- eskom_fbe_token (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'eskom_fbe_token',
  'ZA',
  'income',
  ARRAY['surviving', 'stretching']::text[],
  ARRAY['free electricity token', 'fbe token', 'free basic electricity', 'claim free units', '*130*269#', 'eskom free electricity', 'free units every month', 'prepaid meter free units', 'indigent electricity', 'eskom indigent', '50 kwh', 'free electricity dial', 'token not working', 'didn''t get my free units']::text[],
  'Eskom free basic electricity token',
  'your household is registered as indigent with the municipality and Eskom supplies your prepaid electricity',
  'you are not yet on the indigent register (apply at the municipality first), or your electricity comes from the municipality, which issues the token where you buy electricity',
  'once your household is on the indigent register, the free units are only yours if you claim the token each month; a dial code does it in under a minute',
  'free: 50 kWh to 60 kWh of electricity a month for registered indigent households, claimed by dialling *130*269# (Eskom, checked 2026-10-30)',
  'https://www.eskom.co.za/distribution/free-basic-electricity/',
  'get onto the municipal indigent register → wait for the municipality to load you on Eskom''s system → dial *130*269# on the first of the month → enter the token in the meter → repeat every month',
  ARRAY['Apply at your municipality''s indigent office first; Eskom says the municipality decides who qualifies and loads your details onto the Eskom system.', 'Ask the municipality when your details will be on Eskom''s system; approval and loading can take a few months.', 'On the first of each month, dial *130*269# (Eskom''s page also lists *130*869#) from the cellphone linked to your meter and follow the prompts to claim the token.', 'Type the 20-digit token into your prepaid meter the same way as a bought token; the free allocation is 50 kWh to 60 kWh depending on the municipality.', 'Claim every month; a household gets one free token a month and unused units are forfeited, they do not carry over.', 'If the code says you do not qualify, go back to the municipality with your indigent approval letter; Eskom cannot register you itself.', 'Never pay anyone offering ''free electricity tokens'' for a fee; the free units come only through the municipality''s register.']::text[],
  '2026-10-30'::date,
  TRUE,
  'FREE_FOR_QUALIFYING_USERS',
  'Check whether your household is on the municipal indigent register; if it is, dial *130*269# from the phone linked to your meter and claim this month''s token.'
)
