-- fund_two_pot_portal (ZA)
INSERT INTO public.tools (id, country, domain, stages, keywords, name, fits, not_when, why, cost, url, setup, walkthrough, verified_on, informal_business_supported, free_type, ten_minute_action)
VALUES (
  'fund_two_pot_portal',
  'ZA',
  'goals',
  ARRAY['stretching', 'steady', 'building']::text[],
  ARRAY['two pot portal', 'two-pot withdrawal', 'savings pot claim', 'withdraw savings pot', 'fund administrator', 'alexander forbes', 'old mutual two pot', 'sanlam two pot', 'momentum two pot', 'liberty two pot', 'gepf two pot', 'pension fund member portal', 'provident fund claim', 'two pot tax', 'two pot balance', 'check my retirement balance']::text[],
  'Your fund administrator''s two-pot portal',
  'you belong to a pension, provident or retirement annuity fund and want to see your savings pot balance, or face a real emergency the cushion cannot cover',
