-- ============================================================================
-- 0035_charles_templates.sql
-- ============================================================================

/*
# Charles — the six WhatsApp templates, reworded for one household's money

Apply in Supabase → SQL Editor → New query → paste → Run.
Run AFTER 0034. Safe to run more than once.

1. What this does, in plain terms
db/0006 seeded Charlie's six templates (names charlie_*, wording about a
business). Charles's follow-ups are about a person's money, so the bodies and
the Meta names change; the template ids the code looks up (commitment_check,
monday_focus, month_end_money, monthly_checkin, reengage, login_code) and the
variable positions do not. The copy-paste set for Meta is docs/META-TEMPLATES.md:
name, category, language and body must match what is below exactly.

2. Status
Every template goes back to 'draft': nothing is sent from a template until
Meta has approved the new wording and you mark it approved (see the last
section of docs/META-TEMPLATES.md).
*/

UPDATE public.wa_templates SET meta_name = 'charles_commitment_check', body = 'Did you manage to {{1}}? Tap Done, or Help me if you got stuck.', variables = ARRAY['what_they_committed_to'], status = 'draft' WHERE id = 'commitment_check';
UPDATE public.wa_templates SET meta_name = 'charles_monday_focus', body = 'This week, {{1}}: {{2}}. Reply NEXT when you want the step.', variables = ARRAY['first_name','one_thing'], status = 'draft' WHERE id = 'monday_focus';
UPDATE public.wa_templates SET meta_name = 'charles_month_end_money', body = 'Payday is close, {{1}}. Want the three pots for this month before the money lands? Reply YES.', variables = ARRAY['first_name'], status = 'draft' WHERE id = 'month_end_money';
UPDATE public.wa_templates SET meta_name = 'charles_monthly_checkin', body = 'Quick one, {{1}}: did the month fit the money this time — yes, nearly, or no?', variables = ARRAY['first_name'], status = 'draft' WHERE id = 'monthly_checkin';
UPDATE public.wa_templates SET meta_name = 'charles_reengage', body = 'Still thinking about {{1}}? Reply and we pick up exactly where we left off.', variables = ARRAY['their_open_headache'], status = 'draft' WHERE id = 'reengage';
UPDATE public.wa_templates SET meta_name = 'charles_login_code', body = 'Your Charles code is {{1}}. It works for ten minutes. If you did not ask for it, ignore this message.', variables = ARRAY['code'], status = 'draft' WHERE id = 'login_code';

-- A fresh project where 0006 was never run against Charlie gets the same rows.
INSERT INTO public.wa_templates (id, meta_name, language, category, body, variables, status) VALUES
  ('commitment_check', 'charles_commitment_check', 'en', 'UTILITY', 'Did you manage to {{1}}? Tap Done, or Help me if you got stuck.', ARRAY['what_they_committed_to'], 'draft'),
  ('monday_focus', 'charles_monday_focus', 'en', 'UTILITY', 'This week, {{1}}: {{2}}. Reply NEXT when you want the step.', ARRAY['first_name','one_thing'], 'draft'),
  ('month_end_money', 'charles_month_end_money', 'en', 'UTILITY', 'Payday is close, {{1}}. Want the three pots for this month before the money lands? Reply YES.', ARRAY['first_name'], 'draft'),
  ('monthly_checkin', 'charles_monthly_checkin', 'en', 'UTILITY', 'Quick one, {{1}}: did the month fit the money this time — yes, nearly, or no?', ARRAY['first_name'], 'draft'),
  ('reengage', 'charles_reengage', 'en', 'UTILITY', 'Still thinking about {{1}}? Reply and we pick up exactly where we left off.', ARRAY['their_open_headache'], 'draft'),
  ('login_code', 'charles_login_code', 'en', 'AUTHENTICATION', 'Your Charles code is {{1}}. It works for ten minutes. If you did not ask for it, ignore this message.', ARRAY['code'], 'draft')
ON CONFLICT (id) DO NOTHING;


-- ============================================================================
-- 0036_statement.sql
-- ============================================================================

/*
# Charles — the bank statement a person chose to send (apply AFTER 0035)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once. The code does not depend on it: until it runs, a statement is
still read and said back, and the column write fails quietly.

1. What this does, in plain terms
Adds `businesses.statement jsonb`: the totals and payees api/_lib/statement.ts
kept from a bank statement, payslip or credit report the person sent on
WhatsApp. Money in by source, money out by payee with its kind, bank fees,
cash drawn, days below zero, what was left, and the page's own flags (a
returned debit order, an arrears note). Read once, with one model call told
to leave out the account number, card number, ID number, the holder's name
and every reference number; scrubbed again in code; and the file itself is
never stored anywhere.

It is on the household row, so "forget my money" deletes it with everything
else, and it is reachable only through the backend's service role (0001).

2. Rule 12, kept
Charles never asks for an account number and never keeps one. A statement
carries one; this column never does. test/statement.test.ts pins that.
*/

ALTER TABLE public.businesses ADD COLUMN IF NOT EXISTS statement jsonb;

COMMENT ON COLUMN public.businesses.statement IS 'The bank statement (or payslip, credit report) the person chose to send, as totals and payees only (api/_lib/statement.ts). Never the file, never an account number.';


-- ============================================================================
-- 0037_cards.sql
-- ============================================================================

/*
# Charles — cards: the small pages a person opens from a WhatsApp link (apply AFTER 0036)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once. Until it runs, no card link can be made and Charles says the
figures in words instead.

1. What this does, in plain terms
A card (api/_lib/cards.ts) is a snapshot of one picture of the person's
money, built in code from their own figures: the month in three pots, when a
debt is gone, the Money Map, what the statement says, getting to a number.
Each is reached by a long random link; the token is stored here as a hash,
with the snapshot it shows, for sixty days.

  - `token_hash`: sha256 of the link token, peppered like every other
    credential (api/_lib/crypto.ts). The token itself is never stored.
  - `data`: the snapshot: figures, labels, notes. Never a phone number, an
    account number or a surname (statement.ts drops identifiers before
    anything is kept; cards.ts uses first names only).
  - `expires_at`: the link stops working after this; `opened_at` is the last
    time it was opened.

2. Locked like every other person-data table
RLS on, no policies: only the backend's service role reads or writes it. The
page itself is served by api/card.ts, which looks the token up with the
service role. "Forget my money" deletes the rows with the household (the
cascade below, and api/_lib/db.ts forgetBusiness deletes them explicitly too).
*/

CREATE TABLE IF NOT EXISTS public.cards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('month', 'debt', 'map', 'statement', 'goal')),
  token_hash text NOT NULL UNIQUE,
  data jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  opened_at timestamptz
);

CREATE INDEX IF NOT EXISTS cards_business_idx ON public.cards (business_id, created_at DESC);

ALTER TABLE public.cards ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.cards IS 'Snapshots behind the card links Charles sends on WhatsApp (api/_lib/cards.ts): figures only, sixty days, deleted with the household.';


-- ============================================================================
-- 0038_knowledge_graph.sql
-- ============================================================================

/*
# Charles — the household knowledge graph (apply AFTER 0037)

Apply in Supabase → SQL Editor → New query → paste → Run. Safe to run more
than once. The code does not depend on it: until it runs, the graph Charles
derives from the diagnostic, the statement and the plan still works, and
nothing learned from conversation is kept.

1. What this does, in plain terms
api/_lib/graph.ts keeps what one household's money touches as a small graph:
the person at the centre, and around them where money comes from, who they
owe and what they pay, who they support, their cover, their stokvel or
burial society, where they save and bank, the bills they pay. Every edge
says where it came from (they said it, a setup answer, their statement,
their own AI) and when, so Charles can be specific without ever claiming
the person said something they did not (rule 2), and every figure on it is
one they typed or a page showed (rule 10).

  - kg_nodes: one row per thing, per household. `key` is a normalised name
    ("the mashonisa" and "loan shark" are one node).
  - kg_edges: one row per (household, thing, relation). `amount` and `per`
    are what is paid or received each time, `balance` what is still owed.
    `status` is closed when they paid it off or stopped. `history` keeps the
    last few amounts, so "was R200 a week" survives a change.

What the graph derives from the household row (the diagnostic, the
statement, the goal and the rule) is computed every time and also lives
here once learned; what the person says in conversation, and what their own
AI records with the connector's record_fact, lives only here.

2. The library graph needs nothing here
The links between knowledge entries, tools and plan modules are computed
from the library itself on every load (api/_lib/libgraph.ts).

3. Locked like every other person-data table
RLS on, no policies: only the backend's service role reads or writes these.
"Forget my money" deletes them with the household (the cascades below, and
api/_lib/db.ts forgetBusiness deletes them explicitly too). Never an ID,
account, card or reference number: graph.ts refuses one before it is written.

4. The memory card
Card kind 'memory' ("what Charles knows", drawn) is added to cards.kind.
*/

CREATE TABLE IF NOT EXISTS public.kg_nodes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('self', 'income', 'creditor', 'dependant', 'cover', 'savings', 'bank', 'group', 'bill', 'goal', 'rule')),
  key text NOT NULL CHECK (char_length(key) BETWEEN 1 AND 60),
  label text NOT NULL CHECK (char_length(label) BETWEEN 1 AND 60),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (business_id, kind, key)
);

CREATE TABLE IF NOT EXISTS public.kg_edges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  dst_id uuid NOT NULL REFERENCES public.kg_nodes(id) ON DELETE CASCADE,
  rel text NOT NULL CHECK (rel IN ('earns_from', 'owes', 'supports', 'covered_by', 'saves_in', 'banks_with', 'member_of', 'pays', 'working_towards', 'lives_by')),
  amount numeric CHECK (amount IS NULL OR amount >= 0),
  per text CHECK (per IS NULL OR per IN ('week', 'month')),
  balance numeric CHECK (balance IS NULL OR balance >= 0),
  day int CHECK (day IS NULL OR day BETWEEN 1 AND 31),
  note text CHECK (note IS NULL OR char_length(note) <= 200),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'closed')),
  source text NOT NULL CHECK (source IN ('said', 'answer', 'statement', 'plan', 'connector')),
  sources text[] NOT NULL DEFAULT '{}',
  history jsonb NOT NULL DEFAULT '[]'::jsonb,
  first_seen timestamptz NOT NULL DEFAULT now(),
  last_seen timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz,
  UNIQUE (business_id, dst_id, rel)
);

CREATE INDEX IF NOT EXISTS kg_nodes_business_idx ON public.kg_nodes (business_id);
CREATE INDEX IF NOT EXISTS kg_edges_business_idx ON public.kg_edges (business_id);

ALTER TABLE public.kg_nodes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kg_edges ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.kg_nodes IS 'The household knowledge graph: one row per thing a household''s money touches (api/_lib/graph.ts). Service role only; deleted with the household.';
COMMENT ON TABLE public.kg_edges IS 'The household knowledge graph: how the person is linked to each thing, with amounts, where it came from and when. Never an identifier.';

-- The memory card ("what Charles knows", drawn).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'cards_kind_check' AND conrelid = 'public.cards'::regclass) THEN
    ALTER TABLE public.cards DROP CONSTRAINT cards_kind_check;
  END IF;
  ALTER TABLE public.cards ADD CONSTRAINT cards_kind_check CHECK (kind IN ('month', 'debt', 'map', 'statement', 'goal', 'memory'));
END $$;
